{
  "name": "KierowcaPRO - Zarobki",
  "description": "Aplikacja PWA do obliczania zarobków kierowcy, zarządzania kursami i stawkami za tonę. Zastępuje arkusze kalkulacyjne."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface LocationRate {
  id: string;
  name: string;
  rate: number; // Stawka za tonę (Przelicznik)
}

export interface Trip {
  id: string;
  locationId: string;
  locationName: string; // Kopia nazwy na wypadek usunięcia z bazy
  weight: number; // Tony
  rate: number; // Przelicznik użyty w tym kursie
  amount: number; // Kwota (Tony * Przelicznik)
  bonus: number; // Premia 2%
}

export enum DayType {
  WORK = 'WORK',
  VACATION = 'URLOP',
  WORKSHOP = 'WARSZTAT',
  SICK = 'L4'
}

export interface WorkDay {
  id: string;
  date: string; // YYYY-MM-DD
  type: DayType;
  startTime: string; // HH:MM
  endTime: string; // HH:MM
  restTime: string; // HH:MM (Odpoczynek)
  trips: Trip[];
  totalAmount: number; // Suma kwot z kursów
  totalBonus: number; // Suma premii
  totalWeight: number; // Suma ton
  note: string;
}

export interface MonthlyStats {
  month: string; // YYYY-MM
  totalEarned: number;
  totalTons: number;
  daysWorked: number;
}

import { WorkDay, LocationRate, Trip, DayType } from '../types';

const STORAGE_KEYS = {
  DAYS: 'kierowcapro_days',
  LOCATIONS: 'kierowcapro_locations',
};

// --- Locations Logic ---

export const getLocations = (): LocationRate[] => {
  const data = localStorage.getItem(STORAGE_KEYS.LOCATIONS);
  return data ? JSON.parse(data) : [];
};

export const saveLocations = (locations: LocationRate[]) => {
  localStorage.setItem(STORAGE_KEYS.LOCATIONS, JSON.stringify(locations));
};

// --- Work Days Logic ---

export const getWorkDays = (): WorkDay[] => {
  const data = localStorage.getItem(STORAGE_KEYS.DAYS);
  return data ? JSON.parse(data) : [];
};

export const saveWorkDays = (days: WorkDay[]) => {
  localStorage.setItem(STORAGE_KEYS.DAYS, JSON.stringify(days));
};

export const getDayById = (id: string): WorkDay | undefined => {
  const days = getWorkDays();
  return days.find((d) => d.id === id);
};

export const saveDay = (day: WorkDay) => {
  const days = getWorkDays();
  const index = days.findIndex((d) => d.id === day.id);

  // Recalculate totals ensuring formatting is correct
  const updatedDay = calculateDayTotals(day);

  if (index >= 0) {
    days[index] = updatedDay;
  } else {
    days.push(updatedDay);
  }
  // Sort by date desc
  days.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  saveWorkDays(days);
};

export const deleteDay = (id: string) => {
  const days = getWorkDays().filter((d) => d.id !== id);
  saveWorkDays(days);
};

// --- Calculation Logic ---

export const calculateTrip = (weight: number, rate: number): { amount: number; bonus: number } => {
  const amount = weight * rate;
  const bonus = amount * 0.02; // 2% bonus
  return { amount, bonus };
};

export const calculateDayTotals = (day: WorkDay): WorkDay => {
  if (day.type !== DayType.WORK) {
    return {
      ...day,
      totalAmount: 0,
      totalBonus: 0,
      totalWeight: 0,
      trips: []
    };
  }

  let totalAmount = 0;
  let totalBonus = 0;
  let totalWeight = 0;

  const recalculatedTrips = day.trips.map(trip => {
    const { amount, bonus } = calculateTrip(trip.weight, trip.rate);
    totalAmount += amount;
    totalBonus += bonus;
    totalWeight += trip.weight;
    return { ...trip, amount, bonus };
  });

  return {
    ...day,
    trips: recalculatedTrips,
    totalAmount,
    totalBonus,
    totalWeight
  };
};

// --- Import/Export ---

export const exportData = () => {
  const data = {
    locations: getLocations(),
    days: getWorkDays(),
    exportDate: new Date().toISOString(),
  };
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `kierowcapro_backup_${new Date().toISOString().slice(0, 10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
};

export const importData = async (file: File): Promise<boolean> => {
  try {
    const text = await file.text();
    const data = JSON.parse(text);
    if (data.locations && Array.isArray(data.locations)) {
      saveLocations(data.locations);
    }
    if (data.days && Array.isArray(data.days)) {
      saveWorkDays(data.days);
    }
    return true;
  } catch (e) {
    console.error("Import failed", e);
    return false;
  }
};

import React, { useState, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { Plus, Trash2, Save, ArrowLeft, Calculator } from 'lucide-react';
import { WorkDay, DayType, LocationRate, Trip } from '../types';
import * as StorageService from '../services/storage';

interface DayEditorProps {
  dayId?: string | null;
  onClose: () => void;
}

const DayEditor: React.FC<DayEditorProps> = ({ dayId, onClose }) => {
  const [locations, setLocations] = useState<LocationRate[]>([]);

  const [day, setDay] = useState<WorkDay>({
    id: uuidv4(),
    date: new Date().toISOString().slice(0, 10),
    type: DayType.WORK,
    startTime: '04:00',
    endTime: '16:00',
    restTime: '00:45',
    trips: [],
    totalAmount: 0,
    totalBonus: 0,
    totalWeight: 0,
    note: ''
  });

  useEffect(() => {
    setLocations(StorageService.getLocations());
    if (dayId) {
      const existingDay = StorageService.getDayById(dayId);
      if (existingDay) setDay(existingDay);
    }
  }, [dayId]);

  const handleTripChange = (tripId: string, field: keyof Trip, value: any) => {
    const updatedTrips = day.trips.map(trip => {
      if (trip.id !== tripId) return trip;

      const newTrip = { ...trip, [field]: value };

      // Auto-update rate if location changes
      if (field === 'locationId') {
        const loc = locations.find(l => l.id === value);
        if (loc) {
          newTrip.locationName = loc.name;
          newTrip.rate = loc.rate;
        }
      }

      // Recalculate amounts
      const { amount, bonus } = StorageService.calculateTrip(newTrip.weight, newTrip.rate);
      newTrip.amount = amount;
      newTrip.bonus = bonus;

      return newTrip;
    });

    setDay({ ...day, trips: updatedTrips });
  };

  const addTrip = () => {
    setDay({
      ...day,
      trips: [
        ...day.trips,
        {
          id: uuidv4(),
          locationId: '',
          locationName: '',
          weight: 0,
          rate: 0,
          amount: 0,
          bonus: 0
        }
      ]
    });
  };

  const removeTrip = (id: string) => {
    setDay({ ...day, trips: day.trips.filter(t => t.id !== id) });
  };

  const handleSave = () => {
    StorageService.saveDay(day);
    onClose();
  };

  // Live calculation for preview
  const totals = StorageService.calculateDayTotals(day);

  return (
    <div className="flex flex-col h-full bg-slate-50">
      {/* Header */}
      <div className="bg-white border-b border-slate-200 p-4 flex items-center justify-between sticky top-0 z-10 shadow-sm">
        <button onClick={onClose} className="p-2 text-slate-600 hover:bg-slate-100 rounded-full">
          <ArrowLeft size={24} />
        </button>
        <h2 className="text-lg font-bold text-slate-800">
          {dayId ? 'Edycja Dnia' : 'Nowy Dzień'}
        </h2>
        <button 
          onClick={handleSave} 
          className="flex items-center gap-2 bg-primary text-white px-4 py-2 rounded-lg font-medium shadow hover:bg-blue-700 transition"
        >
          <Save size={18} />
          <span>Zapisz</span>
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6 pb-24">

        {/* Basic Info */}
        <section className="bg-white p-4 rounded-xl shadow-sm space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium text-slate-500 mb-1">Data</label>
              <input 
                type="date" 
                value={day.date} 
                onChange={e => setDay({...day, date: e.target.value})}
                className="w-full p-2 border border-slate-300 rounded-lg bg-slate-50"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-500 mb-1">Typ dnia</label>
              <select 
                value={day.type} 
                onChange={e => setDay({...day, type: e.target.value as DayType})}
                className="w-full p-2 border border-slate-300 rounded-lg bg-slate-50"
              >
                <option value={DayType.WORK}>Praca</option>
                <option value={DayType.VACATION}>Urlop</option>
                <option value={DayType.WORKSHOP}>Warsztat</option>
                <option value={DayType.SICK}>L4</option>
              </select>
            </div>
          </div>

          {day.type === DayType.WORK && (
            <div className="grid grid-cols-3 gap-3">
              <div>
                <label className="block text-xs font-medium text-slate-500 mb-1">Start</label>
                <input 
                  type="time" 
                  value={day.startTime}
                  onChange={e => setDay({...day, startTime: e.target.value})}
                  className="w-full p-2 border border-slate-300 rounded-lg text-center"
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-500 mb-1">Koniec</label>
                <input 
                  type="time" 
                  value={day.endTime}
                  onChange={e => setDay({...day, endTime: e.target.value})}
                  className="w-full p-2 border border-slate-300 rounded-lg text-center"
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-500 mb-1">Pauza</label>
                <input 
                  type="time" 
                  value={day.restTime}
                  onChange={e => setDay({...day, restTime: e.target.value})}
                  className="w-full p-2 border border-slate-300 rounded-lg text-center"
                />
              </div>
            </div>
          )}
        </section>

        {/* Trips Section */}
        {day.type === DayType.WORK && (
          <section className="space-y-4">
            <div className="flex justify-between items-center px-1">
              <h3 className="text-sm font-semibold text-slate-700 uppercase tracking-wider">Lista Kursów</h3>
              <button 
                onClick={addTrip}
                className="text-primary text-sm font-semibold flex items-center gap-1 hover:underline"
              >
                <Plus size={16} /> Dodaj kurs
              </button>
            </div>

            {day.trips.map((trip, index) => (
              <div key={trip.id} className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 relative">
                <div className="grid grid-cols-12 gap-3">
                  <div className="col-span-12">
                     <label className="block text-xs font-medium text-slate-500 mb-1">Miejscowość</label>
                     <select
                        value={trip.locationId}
                        onChange={(e) => handleTripChange(trip.id, 'locationId', e.target.value)}
                        className="w-full p-2 border border-slate-300 rounded-lg"
                      >
                        <option value="">-- Wybierz --</option>
                        {locations.map(loc => (
                          <option key={loc.id} value={loc.id}>{loc.name} ({loc.rate} zł/t)</option>
                        ))}
                      </select>
                  </div>
                  <div className="col-span-4">
                    <label className="block text-xs font-medium text-slate-500 mb-1">Tony</label>
                    <input 
                      type="number" 
                      step="0.1"
                      value={trip.weight || ''}
                      onChange={(e) => handleTripChange(trip.id, 'weight', parseFloat(e.target.value) || 0)}
                      className="w-full p-2 border border-slate-300 rounded-lg font-mono"
                      placeholder="0"
                    />
                  </div>
                  <div className="col-span-4">
                    <label className="block text-xs font-medium text-slate-500 mb-1">Stawka</label>
                    <input 
                      type="number" 
                      disabled
                      value={trip.rate}
                      className="w-full p-2 bg-slate-100 border border-slate-200 rounded-lg text-slate-500"
                    />
                  </div>
                   <div className="col-span-4">
                    <label className="block text-xs font-medium text-slate-500 mb-1">Suma</label>
                    <div className="w-full p-2 bg-slate-50 border border-slate-200 rounded-lg font-bold text-slate-700 text-right">
                      {trip.amount.toFixed(2)}
                    </div>
                  </div>
                </div>

                <button 
                  onClick={() => removeTrip(trip.id)}
                  className="absolute -top-2 -right-2 bg-white text-danger border border-slate-200 p-1.5 rounded-full shadow-sm"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            ))}

            {day.trips.length === 0 && (
              <div className="text-center p-8 bg-white rounded-xl border-2 border-dashed border-slate-200 text-slate-400">
                Brak kursów. Dodaj pierwszy kurs przyciskiem powyżej.
              </div>
            )}
          </section>
        )}

        {/* Live Summary Footer */}
        {day.type === DayType.WORK && (
           <div className="bg-slate-800 text-white rounded-xl p-4 shadow-lg space-y-2">
             <div className="flex justify-between text-sm text-slate-300">
                <span>Tony: {totals.totalWeight.toFixed(2)} t</span>
                <span>Premia 2%: {totals.totalBonus.toFixed(2)} zł</span>
             </div>
             <div className="flex justify-between items-end border-t border-slate-600 pt-2">
                <span className="text-slate-300">Zarobek całkowity:</span>
                <span className="text-2xl font-bold text-green-400">
                  {(totals.totalAmount + totals.totalBonus).toFixed(2)} zł
                </span>
             </div>
           </div>
        )}

        {/* Note */}
        <div className="bg-white p-4 rounded-xl shadow-sm">
           <label className="block text-xs font-medium text-slate-500 mb-1">Notatki / Tankowanie</label>
           <textarea 
             className="w-full p-2 border border-slate-300 rounded-lg"
             rows={3}
             value={day.note}
             onChange={e => setDay({...day, note: e.target.value})}
             placeholder="Wpisz dodatkowe informacje..."
           />
        </div>

      </div>
    </div>
  );
};

export default DayEditor;

import React, { useState, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { Trash2, Plus, Download, Upload, Save, X } from 'lucide-react';
import { LocationRate } from '../types';
import * as StorageService from '../services/storage';

const LocationsManager: React.FC = () => {
  const [locations, setLocations] = useState<LocationRate[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [newLoc, setNewLoc] = useState({ name: '', rate: '' });
  const [message, setMessage] = useState('');

  useEffect(() => {
    setLocations(StorageService.getLocations());
  }, []);

  const handleAdd = () => {
    if (!newLoc.name || !newLoc.rate) return;
    const rate = parseFloat(newLoc.rate.replace(',', '.'));
    if (isNaN(rate)) return;

    const updated = [...locations, { id: uuidv4(), name: newLoc.name, rate }];
    StorageService.saveLocations(updated);
    setLocations(updated);
    setNewLoc({ name: '', rate: '' });
    setIsAdding(false);
  };

  const handleDelete = (id: string) => {
    if (confirm('Czy na pewno usunąć tę miejscowość?')) {
      const updated = locations.filter(l => l.id !== id);
      StorageService.saveLocations(updated);
      setLocations(updated);
    }
  };

  const handleExport = () => {
    StorageService.exportData();
    setMessage('Dane wyeksportowane!');
    setTimeout(() => setMessage(''), 3000);
  };

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const success = await StorageService.importData(e.target.files[0]);
      if (success) {
        setLocations(StorageService.getLocations());
        setMessage('Dane zaimportowane pomyślnie!');
      } else {
        setMessage('Błąd importu!');
      }
      setTimeout(() => setMessage(''), 3000);
    }
  };

  return (
    <div className="p-4 space-y-4 pb-24">
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 text-center">
        <h2 className="text-xl font-bold text-slate-800 mb-2">Baza Miejscowości</h2>
        <p className="text-slate-500 text-sm mb-4">Dodawaj i edytuj stawki za tonę dla poszczególnych miejscowości.</p>

        <div className="flex justify-center gap-3">
          <button 
            onClick={() => setIsAdding(true)}
            className="bg-primary text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm hover:bg-blue-700"
          >
            <Plus size={18} /> Dodaj nową
          </button>
        </div>
      </div>

      {isAdding && (
        <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 animate-fade-in">
          <h3 className="text-sm font-bold text-blue-800 mb-3">Nowa Miejscowość</h3>
          <div className="space-y-3">
            <input 
              type="text" 
              placeholder="Nazwa miejscowości" 
              value={newLoc.name}
              onChange={e => setNewLoc({...newLoc, name: e.target.value})}
              className="w-full p-2 rounded-lg border border-blue-200"
            />
            <input 
              type="number" 
              placeholder="Stawka (zł/t)" 
              value={newLoc.rate}
              onChange={e => setNewLoc({...newLoc, rate: e.target.value})}
              className="w-full p-2 rounded-lg border border-blue-200"
            />
            <div className="flex gap-2 justify-end">
              <button onClick={() => setIsAdding(false)} className="p-2 text-slate-500"><X size={20}/></button>
              <button onClick={handleAdd} className="bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2">
                <Save size={18} /> Zapisz
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl shadow-sm overflow-hidden">
        {locations.length === 0 ? (
          <div className="p-8 text-center text-slate-400">Brak dodanych miejscowości.</div>
        ) : (
          <ul className="divide-y divide-slate-100">
            {locations.map(loc => (
              <li key={loc.id} className="p-4 flex justify-between items-center hover:bg-slate-50">
                <div>
                  <div className="font-semibold text-slate-800">{loc.name}</div>
                  <div className="text-sm text-slate-500">Stawka: <span className="font-mono font-medium text-primary">{loc.rate.toFixed(2)} zł</span> / t</div>
                </div>
                <button onClick={() => handleDelete(loc.id)} className="text-slate-400 hover:text-danger p-2">
                  <Trash2 size={18} />
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>

      <div className="mt-8 pt-8 border-t border-slate-200">
        <h3 className="text-sm font-bold text-slate-500 uppercase mb-4 tracking-wider">Zarządzanie Danymi</h3>
        <div className="grid grid-cols-2 gap-4">
          <button onClick={handleExport} className="flex flex-col items-center justify-center p-4 bg-white border border-slate-200 rounded-xl hover:bg-slate-50 transition">
            <Download className="text-slate-600 mb-2" />
            <span className="text-sm font-medium text-slate-700">Eksportuj Bazę</span>
          </button>
          <label className="flex flex-col items-center justify-center p-4 bg-white border border-slate-200 rounded-xl hover:bg-slate-50 transition cursor-pointer">
            <Upload className="text-slate-600 mb-2" />
            <span className="text-sm font-medium text-slate-700">Importuj Bazę</span>
            <input type="file" accept=".json" onChange={handleImport} className="hidden" />
          </label>
        </div>
        {message && <div className="mt-4 p-3 bg-green-100 text-green-800 rounded-lg text-center text-sm">{message}</div>}
      </div>
    </div>
  );
};

export default LocationsManager;

import React, { useEffect, useState } from 'react';
import { format, parseISO } from 'date-fns';
import { pl } from 'date-fns/locale';
import { Edit2, Trash2, TrendingUp, Calendar, Briefcase, Truck } from 'lucide-react';
import { WorkDay, DayType } from '../types';
import * as StorageService from '../services/storage';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid } from 'recharts';

interface DashboardProps {
  onEditDay: (id: string) => void;
  refreshTrigger: number;
}

const Dashboard: React.FC<DashboardProps> = ({ onEditDay, refreshTrigger }) => {
  const [days, setDays] = useState<WorkDay[]>([]);
  const [monthStats, setMonthStats] = useState({ earned: 0, tons: 0, count: 0 });

  useEffect(() => {
    const data = StorageService.getWorkDays();
    setDays(data);

    // Calculate current month stats
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const currentMonthDays = data.filter(d => {
      const date = new Date(d.date);
      return date.getMonth() === currentMonth && date.getFullYear() === currentYear;
    });

    const earned = currentMonthDays.reduce((acc, d) => acc + d.totalAmount + d.totalBonus, 0);
    const tons = currentMonthDays.reduce((acc, d) => acc + d.totalWeight, 0);

    setMonthStats({
      earned,
      tons,
      count: currentMonthDays.filter(d => d.type === DayType.WORK).length
    });

  }, [refreshTrigger]);

  const handleDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm('Czy usunąć ten dzień?')) {
      StorageService.deleteDay(id);
      setDays(StorageService.getWorkDays());
    }
  };

  // Prepare chart data (Last 7 entries)
  const chartData = [...days].reverse().slice(-7).map(d => ({
    name: format(parseISO(d.date), 'dd.MM'),
    zarobek: d.totalAmount + d.totalBonus
  }));

  return (
    <div className="p-4 space-y-6 pb-24">
      {/* Header Stats */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-gradient-to-br from-blue-600 to-blue-700 rounded-2xl p-4 text-white shadow-lg shadow-blue-200">
          <div className="flex items-center gap-2 text-blue-100 mb-1 text-xs uppercase tracking-wide font-bold">
            <TrendingUp size={14} /> Ten miesiąc
          </div>
          <div className="text-2xl font-bold">{monthStats.earned.toFixed(0)} zł</div>
          <div className="text-xs text-blue-200 mt-1">Suma zarobków</div>
        </div>
        <div className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
           <div className="flex items-center gap-2 text-slate-400 mb-1 text-xs uppercase tracking-wide font-bold">
            <Truck size={14} /> Przewiezione
          </div>
          <div className="text-2xl font-bold text-slate-700">{monthStats.tons.toFixed(0)} t</div>
          <div className="text-xs text-slate-400 mt-1">{monthStats.count} dni pracy</div>
        </div>
      </div>

      {/* Chart */}
      {days.length > 0 && (
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 h-64">
          <h3 className="text-sm font-bold text-slate-500 mb-4">Ostatnie dni</h3>
          <ResponsiveContainer width="100%" height="85%">
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
              <XAxis dataKey="name" fontSize={12} tickLine={false} axisLine={false} />
              <Tooltip 
                cursor={{fill: '#f1f5f9'}}
                contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} 
              />
              <Bar dataKey="zarobek" fill="#2563eb" radius={[4, 4, 0, 0]} barSize={20} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* Recent List */}
      <div>
        <h3 className="text-lg font-bold text-slate-800 mb-3">Historia</h3>
        <div className="space-y-3">
          {days.length === 0 ? (
            <div className="text-center p-8 text-slate-400">Brak wpisów. Dodaj pierwszy dzień!</div>
          ) : (
            days.map(day => (
              <div 
                key={day.id} 
                onClick={() => onEditDay(day.id)}
                className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 active:scale-[0.98] transition-transform cursor-pointer"
              >
                <div className="flex justify-between items-start mb-2">
                  <div className="flex items-center gap-2">
                    <div className={`p-2 rounded-lg ${
                      day.type === DayType.WORK ? 'bg-blue-50 text-primary' : 
                      day.type === DayType.VACATION ? 'bg-yellow-50 text-yellow-600' : 
                      'bg-slate-100 text-slate-500'
                    }`}>
                      {day.type === DayType.WORK ? <Briefcase size={18}/> : <Calendar size={18}/>}
                    </div>
                    <div>
                      <div className="font-bold text-slate-700">
                        {format(parseISO(day.date), 'd MMMM yyyy', { locale: pl })}
                      </div>
                      <div className="text-xs text-slate-400">
                        {day.type === DayType.WORK ? `${day.startTime} - ${day.endTime}` : day.type}
                      </div>
                    </div>
                  </div>
                  <div className="text-right">
                    {day.type === DayType.WORK ? (
                      <>
                        <div className="font-bold text-green-600">
                          +{(day.totalAmount + day.totalBonus).toFixed(2)} zł
                        </div>
                        <div className="text-xs text-slate-400">{day.trips.length} kursy</div>
                      </>
                    ) : (
                      <div className="text-xs font-medium px-2 py-1 bg-slate-100 rounded text-slate-500">
                        {day.type}
                      </div>
                    )}
                  </div>
                </div>

                {/* Mini preview of trips if work day */}
                {day.type === DayType.WORK && day.trips.length > 0 && (
                  <div className="mt-3 pt-3 border-t border-slate-50 text-xs text-slate-500 truncate">
                    {day.trips.map(t => t.locationName).join(', ')}
                  </div>
                )}

                <div className="mt-2 flex justify-end gap-3 opacity-0 hover:opacity-100 transition-opacity">
                   <button onClick={(e) => handleDelete(day.id, e)} className="text-danger p-1"><Trash2 size={16}/></button>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

