// --- Locations Logic ---

export const getLocations = (): LocationRate[] => {
  const data = localStorage.getItem(STORAGE_KEYS.LOCATIONS);
  if (data) {
    return JSON.parse(data);
  } else {
    // Seed initial data if empty
    saveLocations(INITIAL_LOCATIONS);
    return INITIAL_LOCATIONS;
  }
};

export const saveLocations = (locations: LocationRate[]) => {
  localStorage.setItem(STORAGE_KEYS.LOCATIONS, JSON.stringify(locations));
};

// --- Work Days Logic ---

export const getWorkDays = (): WorkDay[] => {
  const data = localStorage.getItem(STORAGE_KEYS.DAYS);
  return data ? JSON.parse(data) : [];
};

export const saveWorkDays = (days: WorkDay[]) => {
  localStorage.setItem(STORAGE_KEYS.DAYS, JSON.stringify(days));
};

export const getDayById = (id: string): WorkDay | undefined => {
  const days = getWorkDays();
  return days.find((d) => d.id === id);
};

export const saveDay = (day: WorkDay) => {
  const days = getWorkDays();
  const index = days.findIndex((d) => d.id === day.id);

  // Recalculate totals ensuring formatting is correct
  const updatedDay = calculateDayTotals(day);

  if (index >= 0) {
    days[index] = updatedDay;
  } else {
    days.push(updatedDay);
  }
  // Sort by date desc
  days.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  saveWorkDays(days);
};

export const deleteDay = (id: string) => {
  const days = getWorkDays().filter((d) => d.id !== id);
  saveWorkDays(days);
};

// --- Calculation Logic ---

export const calculateTrip = (weight: number, rate: number): { amount: number; bonus: number } => {
  const amount = weight * rate;
  const bonus = amount * 0.02; // 2% bonus
  return { amount, bonus };
};

const calculateDurationHours = (start: string, end: string): number => {
  if (!start || !end) return 0;
  const [startH, startM] = start.split(':').map(Number);
  const [endH, endM] = end.split(':').map(Number);

  let diff = (endH * 60 + endM) - (startH * 60 + startM);
  if (diff < 0) diff += 24 * 60; // Handle overnight

  return diff / 60;
};

export const calculateDayTotals = (day: WorkDay): WorkDay => {
  // Logic based on user excel formulas/constants

  // 1. URLOP = 210 PLN Fixed
  if (day.type === DayType.VACATION) {
    return {
      ...day,
      totalAmount: 210,
      totalBonus: 0,
      totalWeight: 0,
      trips: []
    };
  }

  // 2. WARSZTAT = 10 PLN / Hour (Derived from "WARSZTAT 10")
  if (day.type === DayType.WORKSHOP) {
    const hours = calculateDurationHours(day.startTime, day.endTime);
    // Assuming 10 PLN per hour based on input "WARSZTAT 10"
    const amount = hours * 10; 
    return {
      ...day,
      totalAmount: amount,
      totalBonus: 0,
      totalWeight: 0,
      trips: []
    };
  }

  // 3. SICK (L4) - Usually 0 or distinct, keeping 0 for now unless specified
  if (day.type === DayType.SICK) {
    return {
      ...day,
      totalAmount: 0,
      totalBonus: 0,
      totalWeight: 0,
      trips: []
    };
  }

  // 4. WORK - Calculate Trips
  let totalAmount = 0;
  let totalBonus = 0;
  let totalWeight = 0;

  const recalculatedTrips = day.trips.map(trip => {
    const { amount, bonus } = calculateTrip(trip.weight, trip.rate);
    totalAmount += amount;
    totalBonus += bonus;
    totalWeight += trip.weight;
    return { ...trip, amount, bonus };
  });

  return {
    ...day,
    trips: recalculatedTrips,
    totalAmount,
    totalBonus,
    totalWeight
  };
};

// --- Import/Export ---

export const exportData = () => {
  const data = {
    locations: getLocations(),
    days: getWorkDays(),
    exportDate: new Date().toISOString(),
  };
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `kierowcapro_backup_${new Date().toISOString().slice(0, 10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
};

export const importData = async (file: File): Promise<boolean> => {
  try {
    const text = await file.text();
    const data = JSON.parse(text);
    if (data.locations && Array.isArray(data.locations)) {
      saveLocations(data.locations);
    }
    if (data.days && Array.isArray(data.days)) {
      saveWorkDays(data.days);
    }
    return true;
  } catch (e) {
    console.error("Import failed", e);
    return false;
  }
};

import React, { useState, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { Plus, Trash2, Save, ArrowLeft, Clock } from 'lucide-react';
import { WorkDay, DayType, LocationRate, Trip } from '../types';
import * as StorageService from '../services/storage';

interface DayEditorProps {
  dayId?: string | null;
  onClose: () => void;
}

const DayEditor: React.FC<DayEditorProps> = ({ dayId, onClose }) => {
  const [locations, setLocations] = useState<LocationRate[]>([]);

  const [day, setDay] = useState<WorkDay>({
    id: uuidv4(),
    date: new Date().toISOString().slice(0, 10),
    type: DayType.WORK,
    startTime: '04:00',
    endTime: '16:00',
    restTime: '00:45',
    trips: [],
    totalAmount: 0,
    totalBonus: 0,
    totalWeight: 0,
    note: ''
  });

  useEffect(() => {
    setLocations(StorageService.getLocations());
    if (dayId) {
      const existingDay = StorageService.getDayById(dayId);
      if (existingDay) setDay(existingDay);
    }
  }, [dayId]);

  const handleTripChange = (tripId: string, field: keyof Trip, value: any) => {
    const updatedTrips = day.trips.map(trip => {
      if (trip.id !== tripId) return trip;

      const newTrip = { ...trip, [field]: value };

      // Auto-update rate if location changes
      if (field === 'locationId') {
        const loc = locations.find(l => l.id === value);
        if (loc) {
          newTrip.locationName = loc.name;
          newTrip.rate = loc.rate;
        }
      }

      // Recalculate amounts
      const { amount, bonus } = StorageService.calculateTrip(newTrip.weight, newTrip.rate);
      newTrip.amount = amount;
      newTrip.bonus = bonus;

      return newTrip;
    });

    setDay({ ...day, trips: updatedTrips });
  };

  const addTrip = () => {
    setDay({
      ...day,
      trips: [
        ...day.trips,
        {
          id: uuidv4(),
          locationId: '',
          locationName: '',
          weight: 0,
          rate: 0,
          amount: 0,
          bonus: 0
        }
      ]
    });
  };

  const removeTrip = (id: string) => {
    setDay({ ...day, trips: day.trips.filter(t => t.id !== id) });
  };

  const handleSave = () => {
    StorageService.saveDay(day);
    onClose();
  };

  // Live calculation for preview
  const totals = StorageService.calculateDayTotals(day);

  return (
    <div className="flex flex-col h-full bg-slate-50">
      {/* Header */}
      <div className="bg-white border-b border-slate-200 p-4 flex items-center justify-between sticky top-0 z-10 shadow-sm">
        <button onClick={onClose} className="p-2 text-slate-600 hover:bg-slate-100 rounded-full">
          <ArrowLeft size={24} />
        </button>
        <h2 className="text-lg font-bold text-slate-800">
          {dayId ? 'Edycja Dnia' : 'Nowy Dzień'}
        </h2>
        <button 
          onClick={handleSave} 
          className="flex items-center gap-2 bg-primary text-white px-4 py-2 rounded-lg font-medium shadow hover:bg-blue-700 transition"
        >
          <Save size={18} />
          <span>Zapisz</span>
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6 pb-24">

        {/* Basic Info */}
        <section className="bg-white p-4 rounded-xl shadow-sm space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium text-slate-500 mb-1">Data</label>
              <input 
                type="date" 
                value={day.date} 
                onChange={e => setDay({...day, date: e.target.value})}
                className="w-full p-2 border border-slate-300 rounded-lg bg-slate-50"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-500 mb-1">Typ dnia</label>
              <select 
                value={day.type} 
                onChange={e => setDay({...day, type: e.target.value as DayType})}
                className="w-full p-2 border border-slate-300 rounded-lg bg-slate-50 font-medium text-slate-700"
              >
                <option value={DayType.WORK}>Praca (Kursy)</option>
                <option value={DayType.VACATION}>Urlop (210 zł)</option>
                <option value={DayType.WORKSHOP}>Warsztat (10 zł/h)</option>
                <option value={DayType.SICK}>L4 (0 zł)</option>
              </select>
            </div>
          </div>

          {(day.type === DayType.WORK || day.type === DayType.WORKSHOP) && (
            <div className="grid grid-cols-3 gap-3 animate-fade-in">
              <div>
                <label className="block text-xs font-medium text-slate-500 mb-1">Start</label>
                <input 
                  type="time" 
                  value={day.startTime}
                  onChange={e => setDay({...day, startTime: e.target.value})}
                  className="w-full p-2 border border-slate-300 rounded-lg text-center"
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-500 mb-1">Koniec</label>
                <input 
                  type="time" 
                  value={day.endTime}
                  onChange={e => setDay({...day, endTime: e.target.value})}
                  className="w-full p-2 border border-slate-300 rounded-lg text-center"
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-500 mb-1">Pauza</label>
                <input 
                  type="time" 
                  value={day.restTime}
                  onChange={e => setDay({...day, restTime: e.target.value})}
                  className="w-full p-2 border border-slate-300 rounded-lg text-center"
                />
              </div>
            </div>
          )}
        </section>

        {/* Info Box for specific day types */}
        {day.type === DayType.VACATION && (
          <div className="bg-yellow-50 border border-yellow-200 p-4 rounded-xl text-yellow-800 text-sm flex items-center gap-2">
            <Clock size={18} />
            Dla urlopu naliczana jest stała stawka <strong>210 PLN</strong>.
          </div>
        )}

        {day.type === DayType.WORKSHOP && (
           <div className="bg-blue-50 border border-blue-200 p-4 rounded-xl text-blue-800 text-sm flex items-center gap-2">
            <Clock size={18} />
            Dla warsztatu naliczana jest stawka godzinowa <strong>10 PLN/h</strong>.
          </div>
        )}

        {/* Trips Section */}
        {day.type === DayType.WORK && (
          <section className="space-y-4 animate-fade-in">
            <div className="flex justify-between items-center px-1">
              <h3 className="text-sm font-semibold text-slate-700 uppercase tracking-wider">Lista Kursów</h3>
              <button 
                onClick={addTrip}
                className="text-primary text-sm font-semibold flex items-center gap-1 hover:underline"
              >
                <Plus size={16} /> Dodaj kurs
              </button>
            </div>

            {day.trips.map((trip, index) => (
              <div key={trip.id} className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 relative">
                <div className="grid grid-cols-12 gap-3">
                  <div className="col-span-12">
                     <label className="block text-xs font-medium text-slate-500 mb-1">Miejscowość</label>
                     <select
                        value={trip.locationId}
                        onChange={(e) => handleTripChange(trip.id, 'locationId', e.target.value)}
                        className="w-full p-2 border border-slate-300 rounded-lg"
                      >
                        <option value="">-- Wybierz --</option>
                        {locations.map(loc => (
                          <option key={loc.id} value={loc.id}>{loc.name} ({loc.rate} zł)</option>
                        ))}
                      </select>
                  </div>
                  <div className="col-span-4">
                    <label className="block text-xs font-medium text-slate-500 mb-1">Tony / Ilość</label>
                    <input 
                      type="number" 
                      step="0.1"
                      value={trip.weight || ''}
                      onChange={(e) => handleTripChange(trip.id, 'weight', parseFloat(e.target.value) || 0)}
                      className="w-full p-2 border border-slate-300 rounded-lg font-mono"
                      placeholder="0"
                    />
                  </div>
                  <div className="col-span-4">
                    <label className="block text-xs font-medium text-slate-500 mb-1">Stawka</label>
                    <input 
                      type="number" 
                      disabled
                      value={trip.rate}
                      className="w-full p-2 bg-slate-100 border border-slate-200 rounded-lg text-slate-500"
                    />
                  </div>
                   <div className="col-span-4">
                    <label className="block text-xs font-medium text-slate-500 mb-1">Suma</label>
                    <div className="w-full p-2 bg-slate-50 border border-slate-200 rounded-lg font-bold text-slate-700 text-right">
                      {trip.amount.toFixed(2)}
                    </div>
                  </div>
                </div>

                <button 
                  onClick={() => removeTrip(trip.id)}
                  className="absolute -top-2 -right-2 bg-white text-danger border border-slate-200 p-1.5 rounded-full shadow-sm"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            ))}

            {day.trips.length === 0 && (
              <div className="text-center p-8 bg-white rounded-xl border-2 border-dashed border-slate-200 text-slate-400">
                Brak kursów. Dodaj pierwszy kurs przyciskiem powyżej.
              </div>
            )}
          </section>
        )}

        {/* Live Summary Footer */}
        <div className="bg-slate-800 text-white rounded-xl p-4 shadow-lg space-y-2 sticky bottom-0 z-10">
           {day.type === DayType.WORK && (
             <div className="flex justify-between text-sm text-slate-300">
                <span>Tony: {totals.totalWeight.toFixed(2)} t</span>
                <span>Premia 2%: {totals.totalBonus.toFixed(2)} zł</span>
             </div>
           )}
           <div className="flex justify-between items-end border-t border-slate-600 pt-2">
              <span className="text-slate-300">Zarobek całkowity:</span>
              <span className="text-2xl font-bold text-green-400">
                {(totals.totalAmount + totals.totalBonus).toFixed(2)} zł
              </span>
           </div>
        </div>

        {/* Note */}
        <div className="bg-white p-4 rounded-xl shadow-sm">
           <label className="block text-xs font-medium text-slate-500 mb-1">Notatki / Tankowanie</label>
           <textarea 
             className="w-full p-2 border border-slate-300 rounded-lg"
             rows={3}
             value={day.note}
             onChange={e => setDay({...day, note: e.target.value})}
             placeholder="Wpisz dodatkowe informacje..."
           />
        </div>

      </div>
    </div>
  );
};

