import React, { useState, useEffect } from 'react';
import { format, parseISO, startOfMonth, endOfMonth, isWithinInterval } from 'date-fns';
import { pl } from 'date-fns/locale';
import { Truck, Clock, Calculator, Wallet, Calendar } from 'lucide-react';
import { WorkDay, DayType } from '../types';
import * as StorageService from '../services/storage';

const MonthlySummary: React.FC = () => {
  const [days, setDays] = useState<WorkDay[]>([]);
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [stats, setStats] = useState({
    baseEarnings: 0,
    fuelBonus: 0,
    hourlyBonus: 0,
    totalEarnings: 0,
    totalTons: 0,
    totalTrips: 0,
    daysWorked: 0
  });
  const [locationStats, setLocationStats] = useState<any[]>([]);

  useEffect(() => {
    const allDays = StorageService.getWorkDays();
    setDays(allDays);
  }, []);

  useEffect(() => {
    if (days.length === 0) return;

    // Filter days for selected month
    const [year, month] = selectedMonth.split('-').map(Number);
    const filteredDays = days.filter(d => {
      const date = new Date(d.date);
      return date.getMonth() === month - 1 && date.getFullYear() === year;
    });

    // 1. Calculate Global Stats
    let baseEarnings = 0;
    let fuelBonus = 0;
    let hourlyBonus = 0;
    let totalTons = 0;
    let totalTrips = 0;
    let daysWorked = 0;

    filteredDays.forEach(day => {
      // Sum totals regardless of day type (Urlop/Warsztat add to earnings too)
      baseEarnings += day.totalAmount; 
      fuelBonus += day.totalBonus;
      hourlyBonus += (day.totalHourlyBonus || 0);
      totalTons += day.totalWeight;

      if (day.type === DayType.WORK) {
        totalTrips += day.trips.length;
        daysWorked++;
      }
    });

    setStats({
      baseEarnings,
      fuelBonus,
      hourlyBonus,
      totalEarnings: baseEarnings + fuelBonus + hourlyBonus,
      totalTons,
      totalTrips,
      daysWorked
    });

    // 2. Group by Location (for printout comparison)
    const grouped: Record<string, { count: number, tons: number, amount: number, name: string }> = {};

    filteredDays.forEach(day => {
      if (day.type === DayType.WORK) {
        day.trips.forEach(trip => {
          const key = trip.locationName;
          if (!grouped[key]) {
            grouped[key] = { name: key, count: 0, tons: 0, amount: 0 };
          }
          grouped[key].count += 1;
          grouped[key].tons += trip.weight;
          grouped[key].amount += trip.amount;
        });
      }
    });

    // Convert to array and sort by name
    const groupedArray = Object.values(grouped).sort((a, b) => a.name.localeCompare(b.name));
    setLocationStats(groupedArray);

  }, [days, selectedMonth]);

  return (
    <div className="flex flex-col h-full bg-slate-50 p-4 space-y-6 pb-24">
      {/* Month Selector */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center justify-between">
        <div className="flex items-center gap-2 text-slate-700 font-bold">
          <Calendar className="text-primary" />
          <span>Wybierz miesiąc:</span>
        </div>
        <input 
          type="month" 
          value={selectedMonth}
          onChange={(e) => setSelectedMonth(e.target.value)}
          className="p-2 border border-slate-300 rounded-lg bg-slate-50 font-medium"
        />
      </div>

      {/* Financial Summary Cards */}
      <div className="grid grid-cols-2 gap-3">
        <div className="bg-white p-3 rounded-xl shadow-sm border border-slate-100">
           <div className="text-xs text-slate-400 mb-1 flex items-center gap-1 uppercase font-bold tracking-wide">
             <Truck size={12} /> Kursy (Podstawa)
           </div>
           <div className="text-lg font-bold text-slate-700">{stats.baseEarnings.toFixed(2)} zł</div>
        </div>
        <div className="bg-white p-3 rounded-xl shadow-sm border border-slate-100">
           <div className="text-xs text-slate-400 mb-1 flex items-center gap-1 uppercase font-bold tracking-wide">
             <Calculator size={12} /> Premia 20%
           </div>
           <div className="text-lg font-bold text-blue-600">{stats.fuelBonus.toFixed(2)} zł</div>
        </div>
        <div className="bg-white p-3 rounded-xl shadow-sm border border-slate-100">
           <div className="text-xs text-slate-400 mb-1 flex items-center gap-1 uppercase font-bold tracking-wide">
             <Clock size={12} /> Godzinówka
           </div>
           <div className="text-lg font-bold text-orange-600">{stats.hourlyBonus.toFixed(2)} zł</div>
        </div>
        <div className="bg-slate-800 p-3 rounded-xl shadow-sm border border-slate-700 text-white">
           <div className="text-xs text-slate-300 mb-1 flex items-center gap-1 uppercase font-bold tracking-wide">
             <Wallet size={12} /> Razem Wypłata
           </div>
           <div className="text-xl font-bold text-green-400">{stats.totalEarnings.toFixed(2)} zł</div>
        </div>
      </div>

      {/* Detailed List for Printout Comparison */}
      <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col">
        <div className="p-4 border-b border-slate-100 bg-slate-50">
          <h3 className="font-bold text-slate-700 flex items-center gap-2">
            <Truck size={18} /> Zestawienie Miejscowości
          </h3>
          <p className="text-xs text-slate-500 mt-1">Porównaj te dane z wydrukiem z firmy.</p>
        </div>

        <div className="overflow-y-auto flex-1">
          {locationStats.length === 0 ? (
            <div className="p-8 text-center text-slate-400">Brak kursów w wybranym miesiącu.</div>
          ) : (
            <table className="w-full text-sm text-left">
              <thead className="text-xs text-slate-500 uppercase bg-slate-50 sticky top-0">
                <tr>
                  <th className="px-4 py-3 font-medium">Miejscowość</th>
                  <th className="px-2 py-3 font-medium text-center">Ilość</th>
                  <th className="px-2 py-3 font-medium text-right">Tony</th>
                  <th className="px-4 py-3 font-medium text-right">Zarobek</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {locationStats.map((loc, idx) => (
                  <tr key={idx} className="hover:bg-slate-50">
                    <td className="px-4 py-3 font-medium text-slate-700">
                      {loc.name}
                    </td>
                    <td className="px-2 py-3 text-center text-slate-500">
                      {loc.count}
                    </td>
                    <td className="px-2 py-3 text-right font-mono text-slate-600">
                      {loc.tons.toFixed(1)}
                    </td>
                    <td className="px-4 py-3 text-right font-bold text-green-600">
                      {loc.amount.toFixed(2)}
                    </td>
                  </tr>
                ))}
              </tbody>
              <tfoot className="bg-slate-50 font-bold text-slate-700 sticky bottom-0 border-t border-slate-200">
                 <tr>
                  <td className="px-4 py-3">SUMA</td>
                  <td className="px-2 py-3 text-center">{stats.totalTrips}</td>
                  <td className="px-2 py-3 text-right">{stats.totalTons.toFixed(1)}</td>
                  <td className="px-4 py-3 text-right">{stats.baseEarnings.toFixed(2)}</td>
                </tr>
              </tfoot>
            </table>
          )}
        </div>
      </div>
    </div>
  );
};

export default MonthlySummary;

