// --- Locations Logic ---

export const getLocations = (): LocationRate[] => {
  const data = localStorage.getItem(STORAGE_KEYS.LOCATIONS);
  if (data) {
    return JSON.parse(data);
  } else {
    // Seed initial data if empty
    saveLocations(INITIAL_LOCATIONS);
    return INITIAL_LOCATIONS;
  }
};

export const saveLocations = (locations: LocationRate[]) => {
  localStorage.setItem(STORAGE_KEYS.LOCATIONS, JSON.stringify(locations));
};

// --- Work Days Logic ---

export const getWorkDays = (): WorkDay[] => {
  const data = localStorage.getItem(STORAGE_KEYS.DAYS);
  return data ? JSON.parse(data) : [];
};

export const saveWorkDays = (days: WorkDay[]) => {
  localStorage.setItem(STORAGE_KEYS.DAYS, JSON.stringify(days));
};

export const getDayById = (id: string): WorkDay | undefined => {
  const days = getWorkDays();
  return days.find((d) => d.id === id);
};

export const saveDay = (day: WorkDay) => {
  const days = getWorkDays();
  const index = days.findIndex((d) => d.id === day.id);

  // Recalculate totals ensuring formatting is correct
  const updatedDay = calculateDayTotals(day);

  if (index >= 0) {
    days[index] = updatedDay;
  } else {
    days.push(updatedDay);
  }
  // Sort by date desc
  days.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  saveWorkDays(days);
};

export const deleteDay = (id: string) => {
  const days = getWorkDays().filter((d) => d.id !== id);
  saveWorkDays(days);
};

// --- Calculation Logic ---

export const calculateTrip = (weight: number, rate: number): { amount: number; bonus: number } => {
  const amount = weight * rate;
  const bonus = amount * 0.20; // 20% fuel bonus
  return { amount, bonus };
};

const calculateDurationHours = (start: string, end: string): number => {
  if (!start || !end) return 0;
  const [startH, startM] = start.split(':').map(Number);
  const [endH, endM] = end.split(':').map(Number);

  let diff = (endH * 60 + endM) - (startH * 60 + startM);
  if (diff < 0) diff += 24 * 60; // Handle overnight

  return diff / 60;
};

export const calculateDayTotals = (day: WorkDay): WorkDay => {
  // Logic based on user excel formulas/constants

  // 1. URLOP = 210 PLN Fixed
  if (day.type === DayType.VACATION) {
    return {
      ...day,
      totalAmount: 210,
      totalBonus: 0,
      totalHourlyBonus: 0,
      totalWeight: 0,
      workshopHours: 0,
      totalWorkshop: 0,
      trips: []
    };
  }

  // 2. WORK - Calculate Trips AND Hourly Bonus AND Workshop
  let totalAmount = 0;
  let totalBonus = 0;
  let totalWeight = 0;
  let totalHourlyBonus = 0;

  // Hourly Bonus: Hours * 4.5 PLN
  if (day.startTime && day.endTime) {
     const hours = calculateDurationHours(day.startTime, day.endTime);
     totalHourlyBonus = hours * 4.5;
  }

  // Workshop Bonus: Hours * 10 PLN
  const workshopHours = day.workshopHours || 0;
  const totalWorkshop = workshopHours * 10;

  const recalculatedTrips = day.trips.map(trip => {
    const { amount, bonus } = calculateTrip(trip.weight, trip.rate);
    totalAmount += amount;
    totalBonus += bonus;
    totalWeight += trip.weight;
    return { ...trip, amount, bonus };
  });

  return {
    ...day,
    trips: recalculatedTrips,
    totalAmount,
    totalBonus,
    totalHourlyBonus,
    totalWorkshop,
    totalWeight
  };
};

// --- Import/Export ---

export const exportData = () => {
  const data = {
    locations: getLocations(),
    days: getWorkDays(),
    exportDate: new Date().toISOString(),
  };
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `kierowcapro_backup_${new Date().toISOString().slice(0, 10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
};

export const importData = async (file: File): Promise<boolean> => {
  try {
    const text = await file.text();
    const data = JSON.parse(text);
    if (data.locations && Array.isArray(data.locations)) {
      saveLocations(data.locations);
    }
    if (data.days && Array.isArray(data.days)) {
      saveWorkDays(data.days);
    }
    return true;
  } catch (e) {
    console.error("Import failed", e);
    return false;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { Plus, Trash2, Save, ArrowLeft, Clock, Search, X, Wrench } from 'lucide-react';
import { WorkDay, DayType, LocationRate, Trip } from '../types';
import * as StorageService from '../services/storage';

interface DayEditorProps {
  dayId?: string | null;
  onClose: () => void;
}

const DayEditor: React.FC<DayEditorProps> = ({ dayId, onClose }) => {
  const [locations, setLocations] = useState<LocationRate[]>([]);

  const [day, setDay] = useState<WorkDay>({
    id: uuidv4(),
    date: new Date().toISOString().slice(0, 10),
    type: DayType.WORK,
    startTime: '04:00',
    endTime: '04:00',
    trips: [],
    workshopHours: 0,
    totalWorkshop: 0,
    totalAmount: 0,
    totalBonus: 0,
    totalHourlyBonus: 0,
    totalWeight: 0,
    note: ''
  });

  useEffect(() => {
    setLocations(StorageService.getLocations());
    if (dayId) {
      const existingDay = StorageService.getDayById(dayId);
      if (existingDay) setDay(existingDay);
    }
  }, [dayId]);

  const handleTripChange = (tripId: string, field: keyof Trip, value: any) => {
    const updatedTrips = day.trips.map(trip => {
      if (trip.id !== tripId) return trip;

      const newTrip = { ...trip, [field]: value };

      // Auto-update rate if location changes
      if (field === 'locationId') {
        const loc = locations.find(l => l.id === value);
        if (loc) {
          newTrip.locationName = loc.name;
          newTrip.rate = loc.rate;
        }
      }

      // Recalculate amounts
      const { amount, bonus } = StorageService.calculateTrip(newTrip.weight, newTrip.rate);
      newTrip.amount = amount;
      newTrip.bonus = bonus;

      return newTrip;
    });

    setDay({ ...day, trips: updatedTrips });
  };

  const addTrip = () => {
    setDay({
      ...day,
      trips: [
        ...day.trips,
        {
          id: uuidv4(),
          locationId: '',
          locationName: '',
          weight: 0,
          rate: 0,
          amount: 0,
          bonus: 0
        }
      ]
    });
  };

  const removeTrip = (id: string) => {
    setDay({ ...day, trips: day.trips.filter(t => t.id !== id) });
  };

  const handleSave = () => {
    StorageService.saveDay(day);
    onClose();
  };

  const toggleWorkshop = () => {
    if (day.workshopHours && day.workshopHours > 0) {
      setDay({ ...day, workshopHours: 0 });
    } else {
      setDay({ ...day, workshopHours: 1 });
    }
  };

  // Live calculation for preview
  const totals = StorageService.calculateDayTotals(day);

  return (
    <div className="flex flex-col h-full bg-slate-50">
      {/* Header - Fixed Top */}
      <div className="bg-white border-b border-slate-200 p-4 flex items-center justify-between sticky top-0 z-20 shadow-sm flex-none">
        <button onClick={onClose} className="p-2 text-slate-600 hover:bg-slate-100 rounded-full">
          <ArrowLeft size={24} />
        </button>
        <h2 className="text-lg font-bold text-slate-800">
          {dayId ? 'Edycja Dnia' : 'Nowy Dzień'}
        </h2>
        <button 
          onClick={handleSave} 
          className="flex items-center gap-2 bg-primary text-white px-4 py-2 rounded-lg font-medium shadow hover:bg-blue-700 transition"
        >
          <Save size={18} />
          <span>Zapisz</span>
        </button>
      </div>

      {/* Scrollable Content */}
      <div className="flex-1 overflow-y-auto p-4 space-y-6">

        {/* Basic Info */}
        <section className="bg-white p-4 rounded-xl shadow-sm space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium text-slate-500 mb-1">Data</label>
              <input 
                type="date" 
                value={day.date} 
                onChange={e => setDay({...day, date: e.target.value})}
                className="w-full p-3 border border-slate-300 rounded-lg bg-gray-50 text-lg"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-500 mb-1">Typ dnia</label>
              <select 
                value={day.type} 
                onChange={e => setDay({...day, type: e.target.value as DayType})}
                className="w-full p-3 border border-slate-300 rounded-lg bg-gray-50 font-medium text-slate-700"
              >
                <option value={DayType.WORK}>Praca (Kursy)</option>
                <option value={DayType.VACATION}>Urlop (210 zł)</option>
              </select>
            </div>
          </div>

          {(day.type === DayType.WORK) && (
            <div className="grid grid-cols-2 gap-3 animate-fade-in">
              <div>
                <label className="block text-xs font-medium text-slate-500 mb-1">Start</label>
                <input 
                  type="time" 
                  value={day.startTime}
                  onChange={e => setDay({...day, startTime: e.target.value})}
                  className="w-full p-3 border border-slate-300 rounded-lg text-center bg-gray-50 text-lg"
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-500 mb-1">Koniec</label>
                <input 
                  type="time" 
                  value={day.endTime}
                  onChange={e => setDay({...day, endTime: e.target.value})}
                  className="w-full p-3 border border-slate-300 rounded-lg text-center bg-gray-50 text-lg"
                />
              </div>
            </div>
          )}
        </section>

        {/* Info Box for specific day types */}
        {day.type === DayType.VACATION && (
          <div className="bg-yellow-50 border border-yellow-200 p-4 rounded-xl text-yellow-800 text-sm flex items-center gap-2">
            <Clock size={18} />
            Dla urlopu naliczana jest stała stawka <strong>210 PLN</strong>.
          </div>
        )}

        {/* Workshop Option */}
        {day.type === DayType.WORK && (
          <section className="bg-white p-4 rounded-xl shadow-sm">
             <label className="flex items-center gap-3 cursor-pointer">
                <input 
                  type="checkbox" 
                  checked={(day.workshopHours || 0) > 0}
                  onChange={toggleWorkshop}
                  className="w-5 h-5 text-blue-600 rounded focus:ring-blue-500"
                />
                <div className="flex items-center gap-2 text-slate-700 font-medium">
                   <Wrench size={18} className="text-slate-500" />
                   Warsztat / Naprawa
                </div>
             </label>

             {day.workshopHours !== undefined && day.workshopHours > 0 && (
                <div className="mt-4 pl-8 animate-fade-in">
                   <label className="block text-xs font-medium text-slate-500 mb-1">Ilość godzin na warsztacie (x 10 zł)</label>
                   <div className="flex items-center gap-2">
                     <input 
                      type="number"
                      step="0.5"
                      value={day.workshopHours}
                      onChange={e => setDay({...day, workshopHours: parseFloat(e.target.value) || 0})}
                      className="w-24 p-2 border border-slate-300 rounded-lg text-center font-bold"
                     />
                     <span className="text-slate-500 font-medium">h = </span>
                     <span className="text-green-600 font-bold">{(day.workshopHours * 10).toFixed(2)} zł</span>
                   </div>
                </div>
             )}
          </section>
        )}

        {/* Trips Section */}
        {day.type === DayType.WORK && (
          <section className="space-y-4 animate-fade-in">
            <div className="flex justify-between items-center px-1">
              <h3 className="text-sm font-semibold text-slate-700 uppercase tracking-wider">Lista Kursów</h3>
            </div>

            {day.trips.map((trip) => (
              <TripCard 
                key={trip.id} 
                trip={trip} 
                locations={locations}
                onChange={(field, val) => handleTripChange(trip.id, field, val)}
                onRemove={() => removeTrip(trip.id)}
              />
            ))}

             {/* Big Add Button */}
             <button 
                onClick={addTrip}
                className="w-full py-4 rounded-xl bg-primary text-white text-lg font-bold shadow-md shadow-blue-200 flex items-center justify-center gap-2 active:scale-[0.98] transition-transform"
              >
                <Plus size={24} /> Dodaj kurs
              </button>
          </section>
        )}

        {/* Note */}
        <div className="bg-white p-4 rounded-xl shadow-sm">
           <label className="block text-xs font-medium text-slate-500 mb-1">Notatki / Tankowanie</label>
           <textarea 
             className="w-full p-2 border border-slate-300 rounded-lg bg-gray-50"
             rows={3}
             value={day.note}
             onChange={e => setDay({...day, note: e.target.value})}
             placeholder="Wpisz dodatkowe informacje..."
           />
        </div>

      </div>

      {/* Live Summary Footer - Fixed Block at bottom (not floating) */}
      <div className="bg-slate-800 text-white p-4 shadow-lg space-y-2 flex-none z-20">
           {day.type === DayType.WORK && (
             <>
             <div className="flex justify-between text-sm text-slate-300">
                <span>Tony: {totals.totalWeight.toFixed(2)} t</span>
                <span>Premia Paliwo (20%): {totals.totalBonus.toFixed(2)} zł</span>
             </div>
             <div className="flex justify-between text-sm text-slate-300">
                <span>Godziny: {(totals.totalHourlyBonus / 4.5).toFixed(1)} h (+ {totals.totalHourlyBonus.toFixed(2)} zł)</span>
                {totals.totalWorkshop !== undefined && totals.totalWorkshop > 0 ? (
                    <span className="text-orange-300">Warsztat: {totals.totalWorkshop.toFixed(2)} zł</span>
                ) : (
                    <span></span>
                )}
             </div>
             </>
           )}
           <div className="flex justify-between items-end border-t border-slate-600 pt-2">
              <span className="text-slate-300">Zarobek całkowity:</span>
              <span className="text-2xl font-bold text-green-400">
                {(totals.totalAmount + totals.totalBonus + (totals.totalHourlyBonus || 0) + (totals.totalWorkshop || 0)).toFixed(2)} zł
              </span>
           </div>
      </div>
    </div>
  );
};

// Sub-component for Trip Card to handle Search State efficiently
const TripCard: React.FC<{
  trip: Trip;
  locations: LocationRate[];
  onChange: (field: keyof Trip, value: any) => void;
  onRemove: () => void;
}> = ({ trip, locations, onChange, onRemove }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  // Initialize search term if trip has location
  useEffect(() => {
    if (trip.locationName && !isSearching) {
      setSearchTerm(trip.locationName);
    }
  }, [trip.locationName, isSearching]);

  const filteredLocations = locations.filter(l => 
    l.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelectLocation = (loc: LocationRate) => {
    setSearchTerm(loc.name);
    setIsSearching(false);
    onChange('locationId', loc.id);
  };

  const handleSearchFocus = () => {
    setIsSearching(true);
    setSearchTerm(''); // Clear to show all or let user type
    onChange('locationId', ''); // Clear current selection
  };

  return (
    <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 relative">
      <div className="grid grid-cols-12 gap-3">
        {/* Searchable Location Input */}
        <div className="col-span-12 relative">
