                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}

      {/* Recent List */}
      <div>
        <h3 className="text-lg font-bold text-slate-800 mb-3">Historia</h3>
        <div className="space-y-3">
          {days.length === 0 ? (
            <div className="text-center p-8 text-slate-400">Brak wpisów. Dodaj pierwszy dzień!</div>
          ) : (
            days.map(day => (
              <div 
                key={day.id} 
                onClick={() => onEditDay(day.id)}
                className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 active:scale-[0.98] transition-transform cursor-pointer"
              >
                <div className="flex justify-between items-start mb-2">
                  <div className="flex items-center gap-2">
                    <div className={`p-2 rounded-lg ${
                      day.type === DayType.WORK ? 'bg-blue-50 text-primary' : 
                      day.type === DayType.VACATION ? 'bg-yellow-50 text-yellow-600' : 
                      'bg-slate-100 text-slate-500'
                    }`}>
                      {day.type === DayType.WORK ? <Briefcase size={18}/> : <Calendar size={18}/>}
                    </div>
                    <div>
                      <div className="font-bold text-slate-700">
                        {format(parseISO(day.date), 'd MMMM yyyy', { locale: pl })}
                      </div>
                      <div className="text-xs text-slate-400">
                        {day.type === DayType.WORK ? `${day.startTime} - ${day.endTime}` : day.type}
                      </div>
                    </div>
                  </div>
                  <div className="text-right">
                    {day.type === DayType.WORK ? (
                      <>
                        <div className="font-bold text-green-600">
                          +{(day.totalAmount + day.totalBonus + (day.totalHourlyBonus || 0) + (day.totalWorkshop || 0)).toFixed(2)} zł
                        </div>
                        <div className="text-xs text-slate-400">{day.trips.length} kursy</div>
                      </>
                    ) : (
                      <div className="text-xs font-medium px-2 py-1 bg-slate-100 rounded text-slate-500">
                        {day.type}
                      </div>
                    )}
                  </div>
                </div>

                {/* Mini preview of trips + workshop if work day */}
                {day.type === DayType.WORK && (
                  <div className="mt-3 pt-3 border-t border-slate-50 text-xs text-slate-500 truncate flex gap-2">
                    {day.totalWorkshop && day.totalWorkshop > 0 ? (
                        <span className="flex items-center gap-1 text-orange-500 font-semibold"><Wrench size={12}/> Warsztat</span>
                    ) : null}
                    <span>{day.trips.map(t => t.locationName).join(', ')}</span>
                  </div>
                )}

                <div className="mt-2 flex justify-end gap-3 opacity-0 hover:opacity-100 transition-opacity">
                   <button onClick={(e) => handleDelete(day.id, e)} className="text-danger p-1"><Trash2 size={16}/></button>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { format, parseISO, startOfMonth, endOfMonth, isWithinInterval } from 'date-fns';
import { pl } from 'date-fns/locale';
import { Truck, Clock, Calculator, Wallet, Calendar, ChevronDown } from 'lucide-react';
import { WorkDay, DayType } from '../types';
import * as StorageService from '../services/storage';

const MonthlySummary: React.FC = () => {
  const [days, setDays] = useState<WorkDay[]>([]);
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [stats, setStats] = useState({
    baseEarnings: 0,
    fuelBonus: 0,
    hourlyBonus: 0,
    totalEarnings: 0,
    totalTons: 0,
    totalTrips: 0,
    daysWorked: 0
  });
  const [locationStats, setLocationStats] = useState<any[]>([]);

  useEffect(() => {
    const allDays = StorageService.getWorkDays();
    setDays(allDays);
  }, []);

  useEffect(() => {
    if (days.length === 0) return;

    // Filter days for selected month
    const [year, month] = selectedMonth.split('-').map(Number);
    const filteredDays = days.filter(d => {
      const date = new Date(d.date);
      return date.getMonth() === month - 1 && date.getFullYear() === year;
    });

    // 1. Calculate Global Stats
    let baseEarnings = 0;
    let fuelBonus = 0;
    let hourlyBonus = 0;
    let workshopBonus = 0;
    let totalTons = 0;
    let totalTrips = 0;
    let daysWorked = 0;

    filteredDays.forEach(day => {
      // Sum totals regardless of day type (Urlop adds to earnings too)
      baseEarnings += day.totalAmount; 
      fuelBonus += day.totalBonus;
      hourlyBonus += (day.totalHourlyBonus || 0);
      workshopBonus += (day.totalWorkshop || 0);
      totalTons += day.totalWeight;

      if (day.type === DayType.WORK) {
        totalTrips += day.trips.length;
        daysWorked++;
      }
    });

    setStats({
      baseEarnings,
      fuelBonus,
      hourlyBonus,
      totalEarnings: baseEarnings + fuelBonus + hourlyBonus + workshopBonus,
      totalTons,
      totalTrips,
      daysWorked
    });

    // 2. Group by Location (for printout comparison)
    const grouped: Record<string, { count: number, tons: number, amount: number, name: string }> = {};

    filteredDays.forEach(day => {
      if (day.type === DayType.WORK) {
        day.trips.forEach(trip => {
          const key = trip.locationName;
          if (!grouped[key]) {
            grouped[key] = { name: key, count: 0, tons: 0, amount: 0 };
          }
          grouped[key].count += 1;
          grouped[key].tons += trip.weight;
          grouped[key].amount += trip.amount;
        });
      }
    });

    // Convert to array and sort by name
    const groupedArray = Object.values(grouped).sort((a, b) => a.name.localeCompare(b.name));
    setLocationStats(groupedArray);

  }, [days, selectedMonth]);

  return (
    <div className="flex flex-col h-full bg-slate-50">

      {/* 1. COMPACT HEADER: Date + Total */}
      <div className="bg-white p-4 border-b border-slate-200 flex justify-between items-center shadow-sm z-10 flex-none">
        <div className="flex flex-col">
            <span className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 flex items-center gap-1">
                <Calendar size={12}/> Miesiąc
            </span>
            <input 
                type="month" 
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(e.target.value)}
                className="font-bold text-slate-800 bg-transparent outline-none cursor-pointer text-lg"
            />
        </div>
        <div className="text-right">
             <span className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center justify-end gap-1">
                <Wallet size={12}/> Razem
             </span>
             <div className="text-3xl font-black text-green-600 leading-none mt-1">
                {stats.totalEarnings.toFixed(0)} <span className="text-sm font-medium text-green-500">zł</span>
             </div>
        </div>
      </div>

      {/* 2. BREAKDOWN ROW (Compact) */}
      <div className="grid grid-cols-3 divide-x divide-slate-200 bg-white border-b border-slate-200 shadow-sm text-center py-3 z-10 flex-none">
         <div className="px-2">
            <div className="text-[10px] font-bold text-slate-400 uppercase tracking-wide">Kursy</div>
            <div className="font-bold text-slate-700 text-sm mt-0.5">{stats.baseEarnings.toFixed(0)} zł</div>
         </div>
         <div className="px-2">
            <div className="text-[10px] font-bold text-slate-400 uppercase tracking-wide">Premia</div>
            <div className="font-bold text-blue-600 text-sm mt-0.5">{stats.fuelBonus.toFixed(0)} zł</div>
         </div>
         <div className="px-2">
            <div className="text-[10px] font-bold text-slate-400 uppercase tracking-wide">Godziny+Inne</div>
            <div className="font-bold text-orange-600 text-sm mt-0.5">{(stats.totalEarnings - stats.baseEarnings - stats.fuelBonus).toFixed(0)} zł</div>
         </div>
      </div>

      {/* 3. THE LIST (Fills rest of screen) */}
      <div className="flex-1 overflow-hidden relative bg-slate-50 flex flex-col">
          {/* List Header */}
          <div className="grid grid-cols-12 bg-slate-100 text-[10px] font-bold text-slate-500 uppercase py-2 px-4 border-b border-slate-200 sticky top-0 z-10">
             <div className="col-span-6">Miejscowość / Tony</div>
             <div className="col-span-2 text-center">Ilość</div>
             <div className="col-span-4 text-right">Zarobek</div>
          </div>

          {/* Scrollable Content */}
          <div className="flex-1 overflow-y-auto pb-24"> 
            {locationStats.length === 0 ? (
                 <div className="p-10 text-center text-slate-400 flex flex-col items-center justify-center h-64">
                    <Truck size={48} className="mb-4 opacity-20" />
                    <p>Brak danych w tym miesiącu</p>
                 </div>
            ) : (
                <div className="divide-y divide-slate-100 bg-white">
                    {locationStats.map((loc, idx) => (
                        <div key={idx} className="grid grid-cols-12 py-3 px-4 items-center hover:bg-blue-50 transition-colors">
                            <div className="col-span-6 pr-2">
                                <div className="font-bold text-slate-800 text-sm leading-tight mb-1">{loc.name}</div>
                                <div className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-medium bg-slate-100 text-slate-500">
                                   {loc.tons.toFixed(1)} t
                                </div>
                            </div>
                            <div className="col-span-2 text-center">
                                <span className="bg-blue-100 text-blue-700 text-xs font-bold px-2.5 py-1 rounded-full">
                                    {loc.count}
                                </span>
                            </div>
                            <div className="col-span-4 text-right">
                                <div className="font-bold text-green-700 text-base">{loc.amount.toFixed(2)} zł</div>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {/* Footer Summary in list */}
            {locationStats.length > 0 && (
                <div className="p-6 bg-slate-50 text-center text-xs text-slate-400 border-t border-slate-200">
                    Łącznie wykonano: {stats.totalTrips} kursów
                </div>
            )}
          </div>
      </div>

    </div>
  );
};

export default MonthlySummary;

export interface LocationRate {
  id: string;
  name: string;
  rate: number; // Stawka za tonę (Przelicznik)
}

export interface Trip {
  id: string;
  locationId: string;
  locationName: string; // Kopia nazwy na wypadek usunięcia z bazy
  weight: number; // Tony
  rate: number; // Przelicznik użyty w tym kursie
  amount: number; // Kwota (Tony * Przelicznik)
  bonus: number; // Premia 20%
}

export enum DayType {
  WORK = 'WORK',
  VACATION = 'URLOP'
}

export interface WorkDay {
  id: string;
  date: string; // YYYY-MM-DD
  type: DayType;
  startTime: string; // HH:MM
  endTime: string; // HH:MM
  // restTime removed
  trips: Trip[];
  totalAmount: number; // Suma kwot z kursów
  totalBonus: number; // Suma premii paliwowej 20%
  totalHourlyBonus: number; // Premia godzinowa (4.5 zł/h)

  workshopHours?: number; // Ilość godzin na warsztacie
  totalWorkshop?: number; // Zarobek z warsztatu (h * 10)

  waitingHours?: number; // Ilość godzin oczekiwania
  waitingNote?: string; // Miejsce postoju
  totalWaiting?: number; // Zarobek z oczekiwania (h * 8)

  totalWeight: number; // Suma ton
  note: string;
}

export interface MonthlyStats {
  month: string; // YYYY-MM
  totalEarned: number;
  totalTons: number;
  daysWorked: number;
}

