    StorageService.saveDay(day);
    onClose();
  };

  const toggleWorkshop = () => {
    if (day.workshopHours && day.workshopHours > 0) {
      setDay({ ...day, workshopHours: 0 });
    } else {
      setDay({ ...day, workshopHours: 1 });
