import React, { useEffect, useState } from 'react';
import { format, parseISO } from 'date-fns';
import { pl } from 'date-fns/locale';
import { Edit2, Trash2, TrendingUp, Calendar, Briefcase, Truck, Wrench, Hourglass, Plus } from 'lucide-react';
import { WorkDay, DayType } from '../types';
import * as StorageService from '../services/storage';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, LabelList } from 'recharts';

interface DashboardProps {
  onEditDay: (id: string) => void;
  refreshTrigger: number;
}

const Dashboard: React.FC<DashboardProps> = ({ onEditDay, refreshTrigger }) => {
  const [days, setDays] = useState<WorkDay[]>([]);
  const [monthStats, setMonthStats] = useState({ earned: 0, tons: 0, count: 0 });

  useEffect(() => {
    const data = StorageService.getWorkDays();
    setDays(data);

    // Calculate current month stats
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const currentMonthDays = data.filter(d => {
      const date = new Date(d.date);
      return date.getMonth() === currentMonth && date.getFullYear() === currentYear;
    });

    const earned = currentMonthDays.reduce((acc, d) => {
      // Sum: Trips + Fuel Bonus + Hourly Bonus + Workshop + Waiting
      return acc + d.totalAmount + d.totalBonus + (d.totalHourlyBonus || 0) + (d.totalWorkshop || 0) + (d.totalWaiting || 0);
    }, 0);

    const tons = currentMonthDays.reduce((acc, d) => acc + d.totalWeight, 0);

    setMonthStats({
      earned,
      tons,
      count: currentMonthDays.filter(d => d.type === DayType.WORK).length
    });

  }, [refreshTrigger]);

  const handleDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm('Czy usunąć ten dzień?')) {
      StorageService.deleteDay(id);
      setDays(StorageService.getWorkDays());
    }
  };

  // Prepare chart data (Last 7 entries)
  const chartData = [...days].reverse().slice(-7).map(d => ({
    name: format(parseISO(d.date), 'dd.MM'),
    zarobek: Math.round(d.totalAmount + d.totalBonus + (d.totalHourlyBonus || 0) + (d.totalWorkshop || 0) + (d.totalWaiting || 0))
  }));

  return (
    <div className="p-4 space-y-6 pb-24">
      {/* Header Stats */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-gradient-to-br from-blue-600 to-blue-700 rounded-2xl p-4 text-white shadow-lg shadow-blue-200">
          <div className="flex items-center gap-2 text-blue-100 mb-1 text-xs uppercase tracking-wide font-bold">
            <TrendingUp size={14} /> Ten miesiąc
          </div>
          <div className="text-2xl font-bold">{monthStats.earned.toFixed(0)} zł</div>
          <div className="text-xs text-blue-200 mt-1">Suma zarobków</div>
        </div>
        <div className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
           <div className="flex items-center gap-2 text-slate-400 mb-1 text-xs uppercase tracking-wide font-bold">
            <Truck size={14} /> Przewiezione
          </div>
          <div className="text-2xl font-bold text-slate-700">{monthStats.tons.toFixed(0)} t</div>
          <div className="text-xs text-slate-400 mt-1">{monthStats.count} dni pracy</div>
        </div>
      </div>

      {/* Chart */}
      {days.length > 0 && (
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 h-72 flex flex-col">
          <h3 className="text-sm font-bold text-slate-500 mb-4 flex-none">Ostatnie dni</h3>
          <div className="flex-1 w-full min-h-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} margin={{ top: 20, right: 0, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" fontSize={12} tickLine={false} axisLine={false} dy={10} />
                <Tooltip 
                  cursor={{fill: '#f1f5f9'}}
                  contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} 
                />
                <Bar dataKey="zarobek" fill="#2563eb" radius={[4, 4, 0, 0]} barSize={20}>
                  <LabelList dataKey="zarobek" position="top" fill="#64748b" fontSize={12} formatter={(val: number) => `${val}`} />
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}

      {/* Recent List */}
      <div>
        <h3 className="text-lg font-bold text-slate-800 mb-3">Historia</h3>
        <div className="space-y-3">
          {days.length === 0 ? (
            <div className="text-center p-8 text-slate-400">Brak wpisów. Dodaj pierwszy dzień!</div>
          ) : (
            days.map(day => (
              <div 
                key={day.id} 
                onClick={() => onEditDay(day.id)}
                className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 active:scale-[0.98] transition-transform cursor-pointer relative"
              >
                <div className="flex justify-between items-start mb-2">
                  <div className="flex items-center gap-2">
                    <div className={`p-2 rounded-lg ${
                      day.type === DayType.WORK ? 'bg-blue-50 text-primary' : 
                      day.type === DayType.VACATION ? 'bg-yellow-50 text-yellow-600' : 
                      'bg-slate-100 text-slate-500'
                    }`}>
                      {day.type === DayType.WORK ? <Briefcase size={18}/> : <Calendar size={18}/>}
                    </div>
                    <div>
                      <div className="font-bold text-slate-700">
                        {format(parseISO(day.date), 'd MMMM yyyy', { locale: pl })}
                      </div>
                      <div className="text-xs text-slate-400">
                        {day.type === DayType.WORK ? `${day.startTime} - ${day.endTime}` : day.type}
                      </div>
                    </div>
                  </div>
                  <div className="text-right">
                    {day.type === DayType.WORK ? (
                      <>
                        <div className="font-bold text-green-600">
                          +{(day.totalAmount + day.totalBonus + (day.totalHourlyBonus || 0) + (day.totalWorkshop || 0) + (day.totalWaiting || 0)).toFixed(2)} zł
                        </div>
                        <div className="text-xs text-slate-400">{day.trips.length} kursy</div>
                      </>
                    ) : (
                      <div className="text-xs font-medium px-2 py-1 bg-slate-100 rounded text-slate-500">
                        {day.type}
                      </div>
                    )}
                  </div>
                </div>

                {/* Mini preview of trips + workshop if work day */}
                {day.type === DayType.WORK && (
                  <>
                  <div className="mt-2 pt-2 border-t border-slate-50 text-xs text-slate-500 truncate flex flex-wrap gap-2">
                    {day.totalWorkshop && day.totalWorkshop > 0 ? (
                        <span className="flex items-center gap-1 text-orange-500 font-semibold"><Wrench size={12}/> Warsztat</span>
                    ) : null}
                    {day.totalWaiting && day.totalWaiting > 0 ? (
                        <span className="flex items-center gap-1 text-yellow-500 font-semibold"><Hourglass size={12}/> Oczekiwanie</span>
                    ) : null}
                    <span>{day.trips.map(t => t.locationName).join(', ')}</span>
                  </div>

                  {/* Add Another Trip Button */}
                  <button 
                    onClick={(e) => {
                      e.stopPropagation();
                      onEditDay(day.id);
                    }}
                    className="w-full mt-3 py-2 bg-blue-50 text-blue-700 rounded-lg font-bold text-xs flex items-center justify-center gap-2 hover:bg-blue-100 transition-colors border border-blue-100"
                  >
                    <Plus size={14} />
                    Dodaj KOLEJNY kurs
                  </button>
                  </>
                )}

                {/* Delete button (positioned absolute top right for better access) */}
                <button 
                  onClick={(e) => handleDelete(day.id, e)} 
                  className="absolute top-2 right-2 p-2 text-slate-300 hover:text-danger hover:bg-red-50 rounded-full transition-colors z-10"
                >
                  <Trash2 size={16}/>
                </button>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { format, parseISO, startOfMonth, endOfMonth, isWithinInterval } from 'date-fns';
import { pl } from 'date-fns/locale';
import { Truck, Clock, Calculator, Wallet, Calendar, ChevronDown, Wrench, Hourglass, FileDown } from 'lucide-react';
import { WorkDay, DayType } from '../types';
import * as StorageService from '../services/storage';
import { jsPDF } from "jspdf";
import autoTable from 'jspdf-autotable';

// Utility to replace Polish chars for PDF (since standard fonts don't support UTF-8 chars well without custom font files)
const removeDiacritics = (str: string) => {
  return str
    .normalize('NFD').replace(/[\u0300-\u036f]/g, "")
    .replace(/ł/g, 'l').replace(/Ł/g, 'L');
};

const MonthlySummary: React.FC = () => {
  const [days, setDays] = useState<WorkDay[]>([]);
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [stats, setStats] = useState({
    baseEarnings: 0,
    fuelBonus: 0,
    hourlyBonus: 0, // 4.5 zł/h

    workshopHours: 0,
    workshopMoney: 0,

    waitingHours: 0,
    waitingMoney: 0,

    totalEarnings: 0,
    totalTons: 0,
    totalTrips: 0,
    daysWorked: 0
  });
  const [locationStats, setLocationStats] = useState<any[]>([]);

  useEffect(() => {
    const allDays = StorageService.getWorkDays();
    setDays(allDays);
  }, []);

  useEffect(() => {
    if (days.length === 0) return;

    // Filter days for selected month
    const [year, month] = selectedMonth.split('-').map(Number);
    const filteredDays = days.filter(d => {
      const date = new Date(d.date);
      return date.getMonth() === month - 1 && date.getFullYear() === year;
    });

    // 1. Calculate Global Stats
    let baseEarnings = 0;
    let fuelBonus = 0;
    let hourlyBonus = 0;

    let workshopHours = 0;
    let workshopMoney = 0;

    let waitingHours = 0;
    let waitingMoney = 0;

    let totalTons = 0;
    let totalTrips = 0;
    let daysWorked = 0;

    filteredDays.forEach(day => {
      // Sum totals regardless of day type (Urlop adds to earnings too)
      baseEarnings += day.totalAmount; 
      fuelBonus += day.totalBonus;
      hourlyBonus += (day.totalHourlyBonus || 0);

      // Detailed extras
      workshopHours += (day.workshopHours || 0);
      workshopMoney += (day.totalWorkshop || 0);

      waitingHours += (day.waitingHours || 0);
      waitingMoney += (day.totalWaiting || 0);

      totalTons += day.totalWeight;

      if (day.type === DayType.WORK) {
        totalTrips += day.trips.length;
        daysWorked++;
      }
    });

    setStats({
      baseEarnings,
      fuelBonus,
      hourlyBonus,
      workshopHours,
      workshopMoney,
      waitingHours,
      waitingMoney,
      totalEarnings: baseEarnings + fuelBonus + hourlyBonus + workshopMoney + waitingMoney,
      totalTons,
      totalTrips,
      daysWorked
    });

    // 2. Group by Location (for printout comparison)
    const grouped: Record<string, { count: number, tons: number, amount: number, name: string }> = {};

    filteredDays.forEach(day => {
      if (day.type === DayType.WORK) {
        day.trips.forEach(trip => {
          const key = trip.locationName;
          if (!grouped[key]) {
            grouped[key] = { name: key, count: 0, tons: 0, amount: 0 };
          }
          grouped[key].count += 1;
          grouped[key].tons += trip.weight;
          grouped[key].amount += trip.amount;
        });
      }
    });

    // Convert to array and sort by name
    const groupedArray = Object.values(grouped).sort((a, b) => a.name.localeCompare(b.name));
    setLocationStats(groupedArray);

  }, [days, selectedMonth]);

  const handleExportPDF = () => {
    const doc = new jsPDF();
    const [year, month] = selectedMonth.split('-');

    // Header
    doc.setFontSize(18);
    doc.text(removeDiacritics("TRANSKOM ZAROBKI - RAPORT"), 14, 20);

    doc.setFontSize(12);
    doc.text(removeDiacritics(`Miesiac: ${month}/${year}`), 14, 30);
    doc.text(removeDiacritics(`Wygenerowano: ${new Date().toLocaleDateString()}`), 14, 36);

    // Summary Section
    doc.setFontSize(14);
    doc.text(removeDiacritics("Podsumowanie Finansowe"), 14, 50);

    const summaryData = [
      ["Podstawa (Kursy/Urlop)", `${stats.baseEarnings.toFixed(2)} zl`],
      ["Premia Paliwowa (Prognozowane 20%)", `${stats.fuelBonus.toFixed(2)} zl`],
      ["Premia Godzinowa", `${stats.hourlyBonus.toFixed(2)} zl`],
      [`Warsztat (${stats.workshopHours}h)`, `${stats.workshopMoney.toFixed(2)} zl`],
      [`Postoj (${stats.waitingHours}h)`, `${stats.waitingMoney.toFixed(2)} zl`],
      ["-----------------", "----------"],
      ["RAZEM", `${stats.totalEarnings.toFixed(2)} zl`]
    ];

    autoTable(doc, {
      startY: 55,
      head: [[removeDiacritics('Kategoria'), removeDiacritics('Kwota')]],
      body: summaryData.map(row => [removeDiacritics(row[0]), row[1]]),
      theme: 'striped',
      headStyles: { fillColor: [37, 99, 235] }, // Blue
      columnStyles: { 0: { cellWidth: 100 }, 1: { cellWidth: 50, halign: 'right' } }
    });

    // Locations Table
    const finalY = (doc as any).lastAutoTable.finalY || 100;

    doc.setFontSize(14);
    doc.text(removeDiacritics("Szczegoly Miejscowosci"), 14, finalY + 15);

    const tableRows = locationStats.map(loc => [
      removeDiacritics(loc.name),
      loc.count,
      loc.tons.toFixed(1),
      `${loc.amount.toFixed(2)} zl`
    ]);

    autoTable(doc, {
      startY: finalY + 20,
      head: [[removeDiacritics('Miejscowosc'), removeDiacritics('Ilosc'), removeDiacritics('Tony'), removeDiacritics('Kwota')]],
      body: tableRows,
      theme: 'grid',
      headStyles: { fillColor: [71, 85, 105] }, // Slate
      columnStyles: { 
        0: { cellWidth: 'auto' }, 
        1: { halign: 'center' }, 
        2: { halign: 'right' },
        3: { halign: 'right' }
      }
    });

    // Footer Stats
    const finalY2 = (doc as any).lastAutoTable.finalY || 150;
    doc.setFontSize(10);
    doc.text(removeDiacritics(`Lacznie kursow: ${stats.totalTrips}`), 14, finalY2 + 10);
    doc.text(removeDiacritics(`Przewiezione tony: ${stats.totalTons.toFixed(2)}`), 14, finalY2 + 16);
    doc.text(removeDiacritics(`Dni pracujace: ${stats.daysWorked}`), 14, finalY2 + 22);

    doc.save(`Raport_Transkom_${year}_${month}.pdf`);
  };

  return (
    <div className="flex flex-col h-full bg-slate-50">

      {/* 1. COMPACT HEADER: Date + Total */}
      <div className="bg-white p-4 border-b border-slate-200 flex justify-between items-center shadow-sm z-10 flex-none">
        <div className="flex flex-col">
            <span className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 flex items-center gap-1">
                <Calendar size={12}/> Miesiąc
            </span>
            <input 
                type="month" 
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(e.target.value)}
                className="font-bold text-slate-800 bg-transparent outline-none cursor-pointer text-lg"
            />
        </div>

        {/* Export PDF Button */}
        <div className="flex items-center gap-3">
            <button 
              onClick={handleExportPDF} 
              className="flex items-center gap-2 bg-red-50 text-red-600 px-3 py-2 rounded-lg text-xs font-bold border border-red-100 active:scale-95 transition"
            >
              <FileDown size={16} /> PDF
            </button>
            <div className="text-right">
                 <span className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center justify-end gap-1">
                    <Wallet size={12}/> Razem
                 </span>
                 <div className="text-3xl font-black text-green-600 leading-none mt-1">
                    {stats.totalEarnings.toFixed(0)} <span className="text-sm font-medium text-green-500">zł</span>
                 </div>
            </div>
        </div>
      </div>

      {/* 2. DETAILED BREAKDOWN (Replaces simple row) */}
      <div className="bg-white border-b border-slate-200 shadow-sm p-3 z-10 flex-none space-y-3">

         {/* Main Income */}
         <div className="grid grid-cols-2 gap-3">
             <div className="bg-slate-50 p-2 rounded-lg border border-slate-100">
                <div className="text-[10px] font-bold text-slate-400 uppercase tracking-wide">Kursy (Tony)</div>
                <div className="font-bold text-slate-700 text-lg">{stats.baseEarnings.toFixed(0)} zł</div>
             </div>
             <div className="bg-blue-50 p-2 rounded-lg border border-blue-100">
                <div className="text-[10px] font-bold text-blue-400 uppercase tracking-wide">Premia Paliwowa (Prognozowane 20%)</div>
                <div className="font-bold text-blue-700 text-lg">{stats.fuelBonus.toFixed(0)} zł</div>
             </div>
         </div>

         {/* Hourly & Extras */}
         <div className="grid grid-cols-3 gap-2">
            <div className="bg-orange-50 p-2 rounded-lg border border-orange-100 text-center">
                <div className="text-[10px] font-bold text-orange-400 uppercase tracking-wide mb-1">Premia Godzinowa</div>
                <div className="font-bold text-orange-700">{stats.hourlyBonus.toFixed(0)} zł</div>
            </div>

            <div className={`p-2 rounded-lg border text-center ${stats.workshopMoney > 0 ? 'bg-purple-50 border-purple-100' : 'bg-slate-50 border-slate-100 opacity-50'}`}>
                <div className={`text-[10px] font-bold uppercase tracking-wide mb-1 flex items-center justify-center gap-1 ${stats.workshopMoney > 0 ? 'text-purple-400' : 'text-slate-400'}`}>
                   <Wrench size={10}/> Warsztat
                </div>
                <div className={`font-bold ${stats.workshopMoney > 0 ? 'text-purple-700' : 'text-slate-400'}`}>
                    {stats.workshopMoney > 0 ? `${stats.workshopMoney.toFixed(0)} zł` : '-'}
                </div>
                {stats.workshopHours > 0 && <div className="text-[10px] text-purple-500 font-medium">{stats.workshopHours} h</div>}
