import React, { useEffect, useState } from 'react';
import { format, parseISO } from 'date-fns';
import { pl } from 'date-fns/locale';
import { Edit2, Trash2, TrendingUp, Calendar, Briefcase, Truck, Wrench, Hourglass, Plus, PlusCircle } from 'lucide-react';
import { WorkDay, DayType } from '../types';
import * as StorageService from '../services/storage';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, LabelList } from 'recharts';

interface DashboardProps {
  onEditDay: (id: string) => void;
  refreshTrigger: number;
}

const Dashboard: React.FC<DashboardProps> = ({ onEditDay, refreshTrigger }) => {
  const [days, setDays] = useState<WorkDay[]>([]);
  const [monthStats, setMonthStats] = useState({ earned: 0, tons: 0, count: 0 });

  useEffect(() => {
    const data = StorageService.getWorkDays();
    setDays(data);

    // Calculate current month stats
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const currentMonthDays = data.filter(d => {
      const date = new Date(d.date);
      return date.getMonth() === currentMonth && date.getFullYear() === currentYear;
    });

    const earned = currentMonthDays.reduce((acc, d) => {
      // Sum: Trips + Fuel Bonus + Hourly Bonus + Workshop + Waiting
      return acc + d.totalAmount + d.totalBonus + (d.totalHourlyBonus || 0) + (d.totalWorkshop || 0) + (d.totalWaiting || 0);
    }, 0);

    const tons = currentMonthDays.reduce((acc, d) => acc + d.totalWeight, 0);

    setMonthStats({
      earned,
      tons,
      count: currentMonthDays.filter(d => d.type === DayType.WORK).length
    });

  }, [refreshTrigger]);

  const handleDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm('Czy usunąć ten dzień?')) {
      StorageService.deleteDay(id);
      setDays(StorageService.getWorkDays());
    }
  };

  // Prepare chart data (Last 7 entries)
  const chartData = [...days].reverse().slice(-7).map(d => ({
    name: format(parseISO(d.date), 'dd.MM'),
    zarobek: Math.round(d.totalAmount + d.totalBonus + (d.totalHourlyBonus || 0) + (d.totalWorkshop || 0) + (d.totalWaiting || 0))
  }));

  return (
    <div className="p-4 space-y-6 pb-24">
      {/* Header Stats */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-gradient-to-br from-blue-600 to-blue-700 rounded-2xl p-4 text-white shadow-lg shadow-blue-200">
          <div className="flex items-center gap-2 text-blue-100 mb-1 text-xs uppercase tracking-wide font-bold">
            <TrendingUp size={14} /> Ten miesiąc
          </div>
          <div className="text-2xl font-bold">{monthStats.earned.toFixed(0)} zł</div>
          <div className="text-xs text-blue-200 mt-1">Suma zarobków</div>
        </div>
        <div className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
           <div className="flex items-center gap-2 text-slate-400 mb-1 text-xs uppercase tracking-wide font-bold">
            <Truck size={14} /> Przewiezione
          </div>
          <div className="text-2xl font-bold text-slate-700">{monthStats.tons.toFixed(0)} t</div>
          <div className="text-xs text-slate-400 mt-1">{monthStats.count} dni pracy</div>
        </div>
      </div>

      {/* Chart */}
      {days.length > 0 && (
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 h-72 flex flex-col">
          <h3 className="text-sm font-bold text-slate-500 mb-4 flex-none">Ostatnie dni</h3>
          <div className="flex-1 w-full min-h-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} margin={{ top: 20, right: 0, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" fontSize={12} tickLine={false} axisLine={false} dy={10} />
                <Tooltip 
                  cursor={{fill: '#f1f5f9'}}
                  contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} 
                />
                <Bar dataKey="zarobek" fill="#2563eb" radius={[4, 4, 0, 0]} barSize={20}>
                  <LabelList dataKey="zarobek" position="top" fill="#64748b" fontSize={12} formatter={(val: number) => `${val}`} />
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}

      {/* NEW DAY BUTTON - CENTERED */}
      <button 
        onClick={() => onEditDay('')}
        className="w-full py-4 bg-primary text-white rounded-xl shadow-lg shadow-blue-200 flex flex-col items-center justify-center active:scale-98 transition-transform group"
      >
        <div className="flex items-center gap-2 mb-1">
            <PlusCircle size={28} className="group-hover:scale-110 transition-transform"/>
            <span className="text-lg font-bold uppercase tracking-wide">Dodaj NOWY dzień</span>
        </div>
        <span className="text-xs text-blue-100 opacity-80">Rozpocznij nowy wpis pracy lub urlopu</span>
      </button>

      {/* Recent List */}
      <div>
        <h3 className="text-lg font-bold text-slate-800 mb-3">Historia</h3>
        <div className="space-y-3">
          {days.length === 0 ? (
            <div className="text-center p-8 text-slate-400">Brak wpisów. Kliknij przycisk powyżej, aby dodać!</div>
          ) : (
            days.map(day => (
              <div 
                key={day.id} 
                onClick={() => onEditDay(day.id)}
                className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 active:scale-[0.98] transition-transform cursor-pointer relative"
              >
                <div className="flex justify-between items-start mb-2">
                  <div className="flex items-center gap-2">
                    <div className={`p-2 rounded-lg ${
                      day.type === DayType.WORK ? 'bg-blue-50 text-primary' : 
                      day.type === DayType.VACATION ? 'bg-yellow-50 text-yellow-600' : 
                      'bg-slate-100 text-slate-500'
                    }`}>
                      {day.type === DayType.WORK ? <Briefcase size={18}/> : <Calendar size={18}/>}
                    </div>
                    <div>
                      <div className="font-bold text-slate-700">
                        {format(parseISO(day.date), 'd MMMM yyyy', { locale: pl })}
                      </div>
                      <div className="text-xs text-slate-400">
                        {day.type === DayType.WORK ? `${day.startTime} - ${day.endTime}` : day.type}
                      </div>
                    </div>
                  </div>
                  <div className="text-right">
                    {day.type === DayType.WORK ? (
                      <>
                        <div className="font-bold text-green-600">
                          +{(day.totalAmount + day.totalBonus + (day.totalHourlyBonus || 0) + (day.totalWorkshop || 0) + (day.totalWaiting || 0)).toFixed(2)} zł
                        </div>
                        <div className="text-xs text-slate-400">{day.trips.length} kursy</div>
                      </>
                    ) : (
                      <div className="text-xs font-medium px-2 py-1 bg-slate-100 rounded text-slate-500">
                        {day.type}
                      </div>
                    )}
                  </div>
                </div>

                {/* Mini preview of trips + workshop if work day */}
                {day.type === DayType.WORK && (
                  <>
                  <div className="mt-2 pt-2 border-t border-slate-50 text-xs text-slate-500 truncate flex flex-wrap gap-2">
                    {day.totalWorkshop && day.totalWorkshop > 0 ? (
                        <span className="flex items-center gap-1 text-orange-500 font-semibold"><Wrench size={12}/> Warsztat</span>
                    ) : null}
                    {day.totalWaiting && day.totalWaiting > 0 ? (
                        <span className="flex items-center gap-1 text-yellow-500 font-semibold"><Hourglass size={12}/> Oczekiwanie</span>
                    ) : null}
                    <span>{day.trips.map(t => t.locationName).join(', ')}</span>
                  </div>

                  {/* Add Another Trip Button */}
                  <button 
                    onClick={(e) => {
                      e.stopPropagation();
                      onEditDay(day.id);
                    }}
                    className="w-full mt-3 py-2 bg-blue-50 text-blue-700 rounded-lg font-bold text-xs flex items-center justify-center gap-2 hover:bg-blue-100 transition-colors border border-blue-100"
                  >
                    <Plus size={14} />
                    Dodaj KOLEJNY kurs
                  </button>
                  </>
                )}

                {/* Delete button (positioned absolute top right for better access) */}
                <button 
                  onClick={(e) => handleDelete(day.id, e)} 
                  className="absolute top-2 right-2 p-2 text-slate-300 hover:text-danger hover:bg-red-50 rounded-full transition-colors z-10"
                >
                  <Trash2 size={16}/>
                </button>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Home, PlusCircle, Settings, MapPin, FileText } from 'lucide-react';
import Dashboard from './components/Dashboard';
import DayEditor from './components/DayEditor';
import LocationsManager from './components/LocationsManager';
import MonthlySummary from './components/MonthlySummary';

enum View {
  DASHBOARD = 'DASHBOARD',
  EDITOR = 'EDITOR',
  LOCATIONS = 'LOCATIONS',
  SUMMARY = 'SUMMARY'
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [editingDayId, setEditingDayId] = useState<string | null>(null);
  const [refreshTrigger, setRefreshTrigger] = useState(0);

  const handleOpenEditor = (dayId?: string) => {
    setEditingDayId(dayId || null);
    setCurrentView(View.EDITOR);
  };

  const handleCloseEditor = () => {
    setCurrentView(View.DASHBOARD);
    setEditingDayId(null);
    setRefreshTrigger(prev => prev + 1);
  };

  return (
    <div className="h-[100dvh] w-full flex flex-col bg-slate-50 text-slate-900 font-sans overflow-hidden">
      <main className="flex-1 overflow-hidden relative flex flex-col min-h-0">
        {currentView === View.DASHBOARD && (
          <div className="flex-1 overflow-y-auto min-h-0">
            <Dashboard onEditDay={handleOpenEditor} refreshTrigger={refreshTrigger} />
          </div>
        )}
        {currentView === View.EDITOR && (
          <div className="absolute inset-0 z-50 bg-white">
            <DayEditor dayId={editingDayId} onClose={handleCloseEditor} />
          </div>
        )}
        {currentView === View.LOCATIONS && (
          <LocationsManager />
        )}
        {currentView === View.SUMMARY && (
          <MonthlySummary />
        )}
      </main>

      {/* Bottom Navigation */}
      {currentView !== View.EDITOR && (
        <nav className="h-20 bg-white border-t border-slate-200 flex justify-around items-center px-2 pb-2 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-40 flex-none">
          <button 
            onClick={() => setCurrentView(View.DASHBOARD)}
            className={`flex flex-col items-center p-2 rounded-xl transition ${currentView === View.DASHBOARD ? 'text-primary bg-blue-50' : 'text-slate-400'}`}
          >
            <Home size={24} />
            <span className="text-[10px] font-medium mt-1">Start</span>
          </button>

          <button 
             onClick={() => setCurrentView(View.SUMMARY)}
             className={`flex flex-col items-center p-2 rounded-xl transition ${currentView === View.SUMMARY ? 'text-primary bg-blue-50' : 'text-slate-400'}`}
          >
            <FileText size={24} />
            <span className="text-[10px] font-medium mt-1">Raport</span>
          </button>

          <button 
            onClick={() => handleOpenEditor()}
            className="flex flex-col items-center justify-center -mt-8 bg-primary text-white rounded-full w-14 h-14 shadow-lg shadow-blue-300 active:scale-95 transition-transform"
          >
            <PlusCircle size={32} />
          </button>

          <button 
            onClick={() => setCurrentView(View.LOCATIONS)}
            className={`flex flex-col items-center p-2 rounded-xl transition ${currentView === View.LOCATIONS ? 'text-primary bg-blue-50' : 'text-slate-400'}`}
          >
            <MapPin size={24} />
            <span className="text-[10px] font-medium mt-1">Baza</span>
          </button>
        </nav>
      )}
    </div>
  );
};

export default App;

export interface LocationRate {
  id: string;
  name: string;
  rate: number; // Stawka za tonę (Przelicznik)
}

export interface Trip {
  id: string;
  locationId: string;
  locationName: string; // Kopia nazwy na wypadek usunięcia z bazy
  weight: number; // Tony
  rate: number; // Przelicznik użyty w tym kursie
  amount: number; // Kwota (Tony * Przelicznik)
  bonus: number; // Premia 20%
}

export enum DayType {
  WORK = 'WORK',
  VACATION = 'URLOP',
  SICK_LEAVE = 'L4'
}

export interface AppSettings {
  vacationRate: number; // Stawka za urlop (domyślnie 210)
  sickLeaveRate: number; // Stawka za L4 (domyślnie 150)
  hourlyRate: number; // Stawka godzinowa (domyślnie 4.5)
  workshopRate: number; // Stawka za warsztat (domyślnie 10)
  waitingRate: number; // Stawka za postój (domyślnie 8)
}

export interface WorkDay {
  id: string;
  date: string; // YYYY-MM-DD
  type: DayType;
  startTime: string; // HH:MM
  endTime: string; // HH:MM
  // restTime removed
  trips: Trip[];
  totalAmount: number; // Suma kwot z kursów
  totalBonus: number; // Suma premii paliwowej 20%
  totalHourlyBonus: number; // Premia godzinowa (4.5 zł/h)

  workshopHours?: number; // Ilość godzin na warsztacie
  totalWorkshop?: number; // Zarobek z warsztatu (h * 10)

  waitingHours?: number; // Ilość godzin oczekiwania
  waitingNote?: string; // Miejsce postoju
  totalWaiting?: number; // Zarobek z oczekiwania (h * 8)

  totalWeight: number; // Suma ton
  note: string;
}

export interface MonthlyStats {
  month: string; // YYYY-MM
  totalEarned: number;
  totalTons: number;
  daysWorked: number;
}

