        {/* Trips Section */}
        {day.type === DayType.WORK && (
          <section className="space-y-4 animate-fade-in">
            <div className="flex justify-between items-center px-1">
              <h3 className="text-sm font-semibold text-slate-700 uppercase tracking-wider">Lista Kursów</h3>
            </div>

            {day.trips.map((trip) => (
              <TripCard 
                key={trip.id} 
                trip={trip} 
                locations={locations}
                onChange={(field, val) => handleTripChange(trip.id, field, val)}
                onRemove={() => removeTrip(trip.id)}
              />
            ))}

             {/* Big Add Button */}
             <button 
                onClick={addTrip}
                className="w-full py-4 rounded-xl bg-primary text-white text-lg font-bold shadow-md shadow-blue-200 flex items-center justify-center gap-2 active:scale-[0.98] transition-transform"
              >
                <Plus size={24} /> Dodaj kurs
              </button>
          </section>
        )}

        {/* Note */}
        <div className="bg-white p-4 rounded-xl shadow-sm">
           <label className="block text-xs font-medium text-slate-500 mb-1">Notatki / Tankowanie</label>
           <textarea 
             className="w-full p-2 border border-slate-300 rounded-lg bg-gray-50"
             rows={3}
             value={day.note}
             onChange={e => setDay({...day, note: e.target.value})}
             placeholder="Wpisz dodatkowe informacje..."
           />
        </div>

      </div>

      {/* Live Summary Footer - Fixed Block at bottom (not floating) */}
      <div className="bg-slate-800 text-white p-4 shadow-lg space-y-2 flex-none z-20">
           {day.type === DayType.WORK && (
             <>
             <div className="flex justify-between text-sm text-slate-300">
                <span>Tony: {totals.totalWeight.toFixed(2)} t</span>
                <span>Premia Paliwo (20%): {totals.totalBonus.toFixed(2)} zł</span>
             </div>
             <div className="flex justify-between text-sm text-slate-300">
                <span>Godziny: {(totals.totalHourlyBonus / settings.hourlyRate).toFixed(1)} h (+ {totals.totalHourlyBonus.toFixed(2)} zł)</span>
                {/* Simplified Extras display */}
                <div className="text-right">
                    {showWorkshop && totals.totalWorkshop > 0 ? (
                        <span className="block text-orange-300 text-xs">Warsztat: {totals.totalWorkshop.toFixed(2)} zł</span>
                    ) : null}
                    {showWaiting && totals.totalWaiting > 0 ? (
                        <span className="block text-yellow-300 text-xs">Oczekiwanie: {totals.totalWaiting.toFixed(2)} zł</span>
                    ) : null}
                </div>
             </div>
             </>
           )}
           <div className="flex justify-between items-end border-t border-slate-600 pt-2">
              <span className="text-slate-300">Zarobek całkowity:</span>
              <span className="text-2xl font-bold text-green-400">
                {(totals.totalAmount + totals.totalBonus + (totals.totalHourlyBonus || 0) + (totals.totalWorkshop || 0) + (totals.totalWaiting || 0)).toFixed(2)} zł
              </span>
           </div>
      </div>
    </div>
  );
};

// Sub-component for Trip Card to handle Search State efficiently
const TripCard: React.FC<{
  trip: Trip;
  locations: LocationRate[];
  onChange: (field: keyof Trip, value: any) => void;
  onRemove: () => void;
}> = ({ trip, locations, onChange, onRemove }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  // Initialize search term if trip has location
  useEffect(() => {
    if (trip.locationName && !isSearching) {
      setSearchTerm(trip.locationName);
    }
  }, [trip.locationName, isSearching]);

  const filteredLocations = locations.filter(l => 
    l.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelectLocation = (loc: LocationRate) => {
    setSearchTerm(loc.name);
    setIsSearching(false);
    onChange('locationId', loc.id);
  };

  const handleSearchFocus = () => {
    setIsSearching(true);
    setSearchTerm(''); // Clear to show all or let user type
    onChange('locationId', ''); // Clear current selection
  };

  return (
    <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 relative">
      <div className="grid grid-cols-12 gap-3">
        {/* Searchable Location Input */}
        <div className="col-span-12 relative">
          <label className="block text-xs font-medium text-slate-500 mb-1">Miejscowość</label>
          <div className="relative">
             <div className="absolute left-3 top-3 text-slate-400">
               <Search size={18} />
             </div>
             <input
              ref={inputRef}
              type="text"
              value={searchTerm}
              onFocus={() => setIsSearching(true)}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Szukaj miejscowości..."
              className="w-full p-2 pl-10 border border-slate-300 rounded-lg bg-gray-50 focus:ring-2 focus:ring-blue-500 outline-none"
             />
             {isSearching && (
               <button 
                onClick={() => { setIsSearching(false); setSearchTerm(trip.locationName); }} 
                className="absolute right-2 top-2 p-1 text-slate-400"
               >
                 <X size={18}/>
               </button>
             )}
          </div>

          {/* Dropdown List */}
          {isSearching && (
            <div className="absolute z-50 left-0 right-0 top-full mt-1 bg-white border border-slate-200 rounded-lg shadow-xl max-h-60 overflow-y-auto">
              {filteredLocations.length === 0 ? (
                 <div className="p-3 text-sm text-slate-400 text-center">Brak wyników</div>
              ) : (
                filteredLocations.map(loc => (
                  <button
                    key={loc.id}
                    onClick={() => handleSelectLocation(loc)}
                    className="w-full text-left p-3 hover:bg-blue-50 border-b border-slate-50 last:border-0 flex justify-between items-center"
                  >
                    <span className="font-medium text-slate-700">{loc.name}</span>
                    <span className="text-xs font-mono text-slate-400 bg-slate-100 px-2 py-1 rounded">{loc.rate} zł</span>
                  </button>
                ))
              )}
            </div>
          )}
        </div>

        <div className="col-span-4">
          <label className="block text-xs font-medium text-slate-500 mb-1">Tony / Ilość</label>
          <input 
            type="number" 
            step="0.1"
            value={trip.weight || ''}
            onChange={(e) => onChange('weight', parseFloat(e.target.value) || 0)}
            className="w-full p-2 border border-slate-300 rounded-lg font-mono bg-gray-50"
            placeholder="0"
          />
        </div>
        <div className="col-span-4">
          <label className="block text-xs font-medium text-slate-500 mb-1">Stawka</label>
          <input 
            type="number" 
            disabled
            value={trip.rate}
            className="w-full p-2 bg-slate-100 border border-slate-200 rounded-lg text-slate-500"
          />
        </div>
        <div className="col-span-4">
          <label className="block text-xs font-medium text-slate-500 mb-1">Suma</label>
          <div className="w-full p-2 bg-slate-50 border border-slate-200 rounded-lg font-bold text-slate-700 text-right">
            {trip.amount.toFixed(2)}
          </div>
        </div>
      </div>

      <button 
        onClick={onRemove}
        className="absolute -top-2 -right-2 bg-white text-danger border border-slate-200 p-1.5 rounded-full shadow-sm"
      >
        <Trash2 size={16} />
      </button>
    </div>
  );
};

export default DayEditor;

import React, { useState, useEffect } from 'react';
import { format, parseISO, startOfMonth, endOfMonth, isWithinInterval } from 'date-fns';
import { pl } from 'date-fns/locale';
import { Truck, Clock, Calculator, Wallet, Calendar, ChevronDown, Wrench, Hourglass, FileDown, Info } from 'lucide-react';
import { WorkDay, DayType } from '../types';
import * as StorageService from '../services/storage';
import { jsPDF } from "jspdf";
import autoTable from 'jspdf-autotable';

// Utility to replace Polish chars for PDF (since standard fonts don't support UTF-8 chars well without custom font files)
const removeDiacritics = (str: string) => {
  return str
    .normalize('NFD').replace(/[\u0300-\u036f]/g, "")
    .replace(/ł/g, 'l').replace(/Ł/g, 'L');
};

interface ExtraEvent {
  date: string;
  type: 'WARSZTAT' | 'POSTÓJ';
  note: string;
  hours: number;
  amount: number;
}

const MonthlySummary: React.FC = () => {
  const [days, setDays] = useState<WorkDay[]>([]);
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [stats, setStats] = useState({
    baseEarnings: 0,
    fuelBonus: 0,
    hourlyBonus: 0, // 4.5 zł/h

    workshopHours: 0,
    workshopMoney: 0,

    waitingHours: 0,
    waitingMoney: 0,

    totalEarnings: 0,
    totalTons: 0,
    totalTrips: 0,
    daysWorked: 0
  });
  const [locationStats, setLocationStats] = useState<any[]>([]);
  const [extraEvents, setExtraEvents] = useState<ExtraEvent[]>([]);

  useEffect(() => {
    const allDays = StorageService.getWorkDays();
    setDays(allDays);
  }, []);

  useEffect(() => {
    if (days.length === 0) return;

    // Filter days for selected month
    const [year, month] = selectedMonth.split('-').map(Number);
    const filteredDays = days.filter(d => {
      const date = new Date(d.date);
      return date.getMonth() === month - 1 && date.getFullYear() === year;
    });

    // 1. Calculate Global Stats
    let baseEarnings = 0;
    let fuelBonus = 0;
    let hourlyBonus = 0;

    let workshopHours = 0;
    let workshopMoney = 0;

    let waitingHours = 0;
    let waitingMoney = 0;

    let totalTons = 0;
    let totalTrips = 0;
    let daysWorked = 0;

    // For Extra Events List
    const extras: ExtraEvent[] = [];

    filteredDays.forEach(day => {
      // Sum totals regardless of day type (Urlop adds to earnings too)
      baseEarnings += day.totalAmount; 
      fuelBonus += day.totalBonus;
      hourlyBonus += (day.totalHourlyBonus || 0);

      // Detailed extras
      if (day.workshopHours && day.workshopHours > 0) {
        workshopHours += day.workshopHours;
        const amount = day.totalWorkshop || 0;
        workshopMoney += amount;
        extras.push({
            date: day.date,
            type: 'WARSZTAT',
            note: 'Naprawa / Serwis',
            hours: day.workshopHours,
            amount: amount
        });
      }

      if (day.waitingHours && day.waitingHours > 0) {
        waitingHours += day.waitingHours;
        const amount = day.totalWaiting || 0;
        waitingMoney += amount;
        extras.push({
            date: day.date,
            type: 'POSTÓJ',
            note: day.waitingNote || 'Brak opisu',
            hours: day.waitingHours,
            amount: amount
        });
      }

      totalTons += day.totalWeight;

      if (day.type === DayType.WORK) {
        totalTrips += day.trips.length;
        daysWorked++;
      }
    });

    // Sort extras by date descending
    extras.sort((a, b) => b.date.localeCompare(a.date));
    setExtraEvents(extras);

    setStats({
      baseEarnings,
      fuelBonus,
      hourlyBonus,
      workshopHours,
      workshopMoney,
      waitingHours,
      waitingMoney,
      totalEarnings: baseEarnings + fuelBonus + hourlyBonus + workshopMoney + waitingMoney,
      totalTons,
      totalTrips,
      daysWorked
    });

    // 2. Group by Location (for printout comparison)
    const grouped: Record<string, { count: number, tons: number, amount: number, name: string }> = {};

    filteredDays.forEach(day => {
      if (day.type === DayType.WORK) {
        day.trips.forEach(trip => {
          const key = trip.locationName;
          if (!grouped[key]) {
            grouped[key] = { name: key, count: 0, tons: 0, amount: 0 };
          }
          grouped[key].count += 1;
          grouped[key].tons += trip.weight;
          grouped[key].amount += trip.amount;
        });
      }
    });

    // Convert to array and sort by name
    const groupedArray = Object.values(grouped).sort((a, b) => a.name.localeCompare(b.name));
    setLocationStats(groupedArray);

  }, [days, selectedMonth]);

  const handleExportPDF = () => {
    const doc = new jsPDF();
    const [year, month] = selectedMonth.split('-');

    // Header
    doc.setFontSize(18);
    doc.text(removeDiacritics("TRANSKOM ZAROBKI - RAPORT"), 14, 20);

    doc.setFontSize(12);
    doc.text(removeDiacritics(`Miesiac: ${month}/${year}`), 14, 30);
    doc.text(removeDiacritics(`Wygenerowano: ${new Date().toLocaleDateString()}`), 14, 36);

    // Summary Section
    doc.setFontSize(14);
    doc.text(removeDiacritics("Podsumowanie Finansowe"), 14, 50);

    const summaryData = [
      ["Podstawa (Kursy/Urlop)", `${stats.baseEarnings.toFixed(2)} zl`],
      ["Premia Paliwowa (Prognozowane 20%)", `${stats.fuelBonus.toFixed(2)} zl`],
      ["Premia Godzinowa", `${stats.hourlyBonus.toFixed(2)} zl`],
      [`Warsztat (${stats.workshopHours}h)`, `${stats.workshopMoney.toFixed(2)} zl`],
      [`Postoj (${stats.waitingHours}h)`, `${stats.waitingMoney.toFixed(2)} zl`],
      ["-----------------", "----------"],
      ["RAZEM", `${stats.totalEarnings.toFixed(2)} zl`]
    ];

    autoTable(doc, {
      startY: 55,
      head: [[removeDiacritics('Kategoria'), removeDiacritics('Kwota')]],
      body: summaryData.map(row => [removeDiacritics(row[0]), row[1]]),
      theme: 'striped',
      headStyles: { fillColor: [37, 99, 235] }, // Blue
      columnStyles: { 0: { cellWidth: 100 }, 1: { cellWidth: 50, halign: 'right' } }
    });

    // Locations Table
    let finalY = (doc as any).lastAutoTable.finalY || 100;

    doc.setFontSize(14);
    doc.text(removeDiacritics("Miejscowosci (Kursy)"), 14, finalY + 15);

    const tableRows = locationStats.map(loc => [
      removeDiacritics(loc.name),
      loc.count,
      loc.tons.toFixed(1),
      `${loc.amount.toFixed(2)} zl`
    ]);

    autoTable(doc, {
      startY: finalY + 20,
      head: [[removeDiacritics('Miejscowosc'), removeDiacritics('Ilosc'), removeDiacritics('Tony'), removeDiacritics('Kwota')]],
      body: tableRows,
      theme: 'grid',
      headStyles: { fillColor: [71, 85, 105] }, // Slate
      columnStyles: { 
        0: { cellWidth: 'auto' }, 
        1: { halign: 'center' }, 
        2: { halign: 'right' },
        3: { halign: 'right' }
      }
    });

    // Extra Events Table (Workshop/Waiting)
    if (extraEvents.length > 0) {
        finalY = (doc as any).lastAutoTable.finalY || 100;
        doc.setFontSize(14);
        doc.text(removeDiacritics("Szczegoly: Warsztat i Postoj"), 14, finalY + 15);

        const extraRows = extraEvents.map(ev => [
            ev.date,
            removeDiacritics(ev.type),
            removeDiacritics(ev.note),
            `${ev.hours}h`,
            `${ev.amount.toFixed(2)} zl`
        ]);

        autoTable(doc, {
            startY: finalY + 20,
            head: [[removeDiacritics('Data'), removeDiacritics('Typ'), removeDiacritics('Opis'), removeDiacritics('Czas'), removeDiacritics('Kwota')]],
            body: extraRows,
            theme: 'grid',
            headStyles: { fillColor: [234, 179, 8] }, // Yellow-ish
            columnStyles: { 
                0: { cellWidth: 25 }, 
                1: { cellWidth: 25 }, 
                2: { cellWidth: 'auto' },
                3: { cellWidth: 20, halign: 'center' },
                4: { cellWidth: 30, halign: 'right' }
            }
        });
    }

    // Footer Stats
    const finalY2 = (doc as any).lastAutoTable.finalY || 150;
    doc.setFontSize(10);
    doc.text(removeDiacritics(`Lacznie kursow: ${stats.totalTrips}`), 14, finalY2 + 10);
    doc.text(removeDiacritics(`Przewiezione tony: ${stats.totalTons.toFixed(2)}`), 14, finalY2 + 16);
    doc.text(removeDiacritics(`Dni pracujace: ${stats.daysWorked}`), 14, finalY2 + 22);

    doc.save(`Raport_Transkom_${year}_${month}.pdf`);
  };

  return (
    <div className="flex flex-col h-full bg-slate-50">

      {/* 1. COMPACT HEADER: Date + Total */}
      <div className="bg-white p-4 border-b border-slate-200 flex justify-between items-center shadow-sm z-10 flex-none">
        <div className="flex flex-col">
            <span className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 flex items-center gap-1">
                <Calendar size={12}/> Miesiąc
            </span>
            <input 
                type="month" 
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(e.target.value)}
                className="font-bold text-slate-800 bg-transparent outline-none cursor-pointer text-lg"
            />
        </div>

        {/* Export PDF Button */}
        <div className="flex items-center gap-3">
            <button 
              onClick={handleExportPDF} 
              className="flex items-center gap-2 bg-red-50 text-red-600 px-3 py-2 rounded-lg text-xs font-bold border border-red-100 active:scale-95 transition"
            >
              <FileDown size={16} /> PDF
            </button>
            <div className="text-right">
                 <span className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center justify-end gap-1">
                    <Wallet size={12}/> Razem
                 </span>
                 <div className="text-3xl font-black text-green-600 leading-none mt-1">
                    {stats.totalEarnings.toFixed(0)} <span className="text-sm font-medium text-green-500">zł</span>
                 </div>
            </div>
        </div>
      </div>

      {/* 2. DETAILED BREAKDOWN (Replaces simple row) */}
      <div className="bg-white border-b border-slate-200 shadow-sm p-3 z-10 flex-none space-y-3">

         {/* Main Income */}
         <div className="grid grid-cols-2 gap-3">
             <div className="bg-slate-50 p-2 rounded-lg border border-slate-100">
                <div className="text-[10px] font-bold text-slate-400 uppercase tracking-wide">Kursy (Tony)</div>
                <div className="font-bold text-slate-700 text-lg">{stats.baseEarnings.toFixed(0)} zł</div>
             </div>
             <div className="bg-blue-50 p-2 rounded-lg border border-blue-100">
                <div className="text-[10px] font-bold text-blue-400 uppercase tracking-wide">Premia Paliwowa (Prognozowane 20%)</div>
                <div className="font-bold text-blue-700 text-lg">{stats.fuelBonus.toFixed(0)} zł</div>
             </div>
         </div>

         {/* Hourly & Extras */}
         <div className="grid grid-cols-3 gap-2">
            <div className="bg-orange-50 p-2 rounded-lg border border-orange-100 text-center">
                <div className="text-[10px] font-bold text-orange-400 uppercase tracking-wide mb-1">Premia Godzinowa</div>
                <div className="font-bold text-orange-700">{stats.hourlyBonus.toFixed(0)} zł</div>
            </div>

            <div className={`p-2 rounded-lg border text-center ${stats.workshopMoney > 0 ? 'bg-purple-50 border-purple-100' : 'bg-slate-50 border-slate-100 opacity-50'}`}>
                <div className={`text-[10px] font-bold uppercase tracking-wide mb-1 flex items-center justify-center gap-1 ${stats.workshopMoney > 0 ? 'text-purple-400' : 'text-slate-400'}`}>
                   <Wrench size={10}/> Warsztat
                </div>
                <div className={`font-bold ${stats.workshopMoney > 0 ? 'text-purple-700' : 'text-slate-400'}`}>
                    {stats.workshopMoney > 0 ? `${stats.workshopMoney.toFixed(0)} zł` : '-'}
                </div>
                {stats.workshopHours > 0 && <div className="text-[10px] text-purple-500 font-medium">{stats.workshopHours} h</div>}
            </div>

            <div className={`p-2 rounded-lg border text-center ${stats.waitingMoney > 0 ? 'bg-yellow-50 border-yellow-100' : 'bg-slate-50 border-slate-100 opacity-50'}`}>
                <div className={`text-[10px] font-bold uppercase tracking-wide mb-1 flex items-center justify-center gap-1 ${stats.waitingMoney > 0 ? 'text-yellow-600' : 'text-slate-400'}`}>
                   <Hourglass size={10}/> Postój
                </div>
                <div className={`font-bold ${stats.waitingMoney > 0 ? 'text-yellow-700' : 'text-slate-400'}`}>
                     {stats.waitingMoney > 0 ? `${stats.waitingMoney.toFixed(0)} zł` : '-'}
                </div>
                 {stats.waitingHours > 0 && <div className="text-[10px] text-yellow-600 font-medium">{stats.waitingHours} h</div>}
            </div>
         </div>

      </div>

      {/* 3. THE LIST (Fills rest of screen) */}
      <div className="flex-1 overflow-y-auto bg-slate-50 pb-24">

          {/* A. Locations Section */}
          <div>
            <div className="grid grid-cols-12 bg-slate-100 text-[10px] font-bold text-slate-500 uppercase py-2 px-4 border-b border-slate-200 sticky top-0 z-10">
                <div className="col-span-6">Miejscowość / Tony</div>
                <div className="col-span-2 text-center">Ilość</div>
                <div className="col-span-4 text-right">Zarobek</div>
            </div>

            {locationStats.length === 0 && extraEvents.length === 0 ? (
                    <div className="p-10 text-center text-slate-400 flex flex-col items-center justify-center h-64">
                        <Truck size={48} className="mb-4 opacity-20" />
                        <p>Brak danych w tym miesiącu</p>
                    </div>
            ) : (
                <div className="divide-y divide-slate-100 bg-white">
                    {locationStats.map((loc, idx) => (
                        <div key={idx} className="grid grid-cols-12 py-3 px-4 items-center hover:bg-blue-50 transition-colors">
                            <div className="col-span-6 pr-2">
                                <div className="font-bold text-slate-800 text-sm leading-tight mb-1">{loc.name}</div>
                                <div className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-medium bg-slate-100 text-slate-500">
                                   {loc.tons.toFixed(1)} t
                                </div>
                            </div>
                            <div className="col-span-2 text-center">
                                <span className="bg-blue-100 text-blue-700 text-xs font-bold px-2.5 py-1 rounded-full">
                                    {loc.count}
                                </span>
                            </div>
                            <div className="col-span-4 text-right">
                                <div className="font-bold text-green-700 text-base">{loc.amount.toFixed(2)} zł</div>
                            </div>
                        </div>
                    ))}
                </div>
            )}
          </div>

          {/* B. Extra Events Section (Warsztat / Postój) */}
          {extraEvents.length > 0 && (
            <div className="mt-6 border-t border-slate-200">
                 <div className="bg-yellow-50 text-[10px] font-bold text-yellow-700 uppercase py-2 px-4 border-b border-yellow-100 sticky top-0 z-10 flex items-center gap-2">
                    <Info size={14}/> Szczegóły: Warsztat i Postój
                 </div>
                 <div className="divide-y divide-slate-100 bg-white">
                    {extraEvents.map((ev, idx) => (
                        <div key={idx} className="p-4 hover:bg-yellow-50 transition-colors">
                             <div className="flex justify-between items-start mb-1">
                                <div className="flex items-center gap-2">
                                    <span className="text-xs font-mono font-bold text-slate-400">{format(parseISO(ev.date), 'dd.MM')}</span>
                                    <span className={`text-xs font-bold px-2 py-0.5 rounded ${ev.type === 'WARSZTAT' ? 'bg-purple-100 text-purple-700' : 'bg-yellow-100 text-yellow-700'}`}>
                                        {ev.type}
                                    </span>
                                </div>
                                <div className="text-right">
                                    <span className="font-bold text-slate-700">{ev.amount.toFixed(2)} zł</span>
                                </div>
                             </div>
                             <div className="flex justify-between items-end">
                                <div className="text-sm text-slate-600 leading-snug max-w-[75%]">
                                    {ev.note}
                                </div>
                                <div className="text-xs font-bold text-slate-400 bg-slate-100 px-2 py-1 rounded">
                                    {ev.hours} h
                                </div>
                             </div>
                        </div>
                    ))}
                 </div>
            </div>
          )}

          {/* Footer Summary in list */}
          {(locationStats.length > 0 || extraEvents.length > 0) && (
              <div className="p-6 bg-slate-50 text-center text-xs text-slate-400 border-t border-slate-200">
                  Łącznie wykonano: {stats.totalTrips} kursów
              </div>
          )}
      </div>

    </div>
  );
};

export default MonthlySummary;

export interface LocationRate {
  id: string;
  name: string;
  rate: number; // Stawka za tonę (Przelicznik)
}

export interface Trip {
  id: string;
  locationId: string;
  locationName: string; // Kopia nazwy na wypadek usunięcia z bazy
  weight: number; // Tony
  rate: number; // Przelicznik użyty w tym kursie
  amount: number; // Kwota (Tony * Przelicznik)
  bonus: number; // Premia 20%
}

export enum DayType {
  WORK = 'WORK',
  VACATION = 'URLOP',
  SICK_LEAVE = 'L4'
}

export interface AppSettings {
  vacationRate: number; // Stawka za urlop (domyślnie 210)
  sickLeaveRate: number; // Stawka za L4 (domyślnie 150)
  hourlyRate: number; // Stawka godzinowa (domyślnie 4.5)
  workshopRate: number; // Stawka za warsztat (domyślnie 10)
  waitingRate: number; // Stawka za postój (domyślnie 8)
  vacationDaysLimit: number; // Limit dni urlopowych na rok (domyślnie 26)
}

export interface WorkDay {
  id: string;
  date: string; // YYYY-MM-DD
  type: DayType;
  startTime: string; // HH:MM
  endTime: string; // HH:MM
  // restTime removed
  trips: Trip[];
  totalAmount: number; // Suma kwot z kursów
  totalBonus: number; // Suma premii paliwowej 20%
  totalHourlyBonus: number; // Premia godzinowa (4.5 zł/h)

  workshopHours?: number; // Ilość godzin na warsztacie
  totalWorkshop?: number; // Zarobek z warsztatu (h * 10)

  waitingHours?: number; // Ilość godzin oczekiwania
  waitingNote?: string; // Miejsce postoju
  totalWaiting?: number; // Zarobek z oczekiwania (h * 8)

  totalWeight: number; // Suma ton
  note: string;
}

export interface MonthlyStats {
  month: string; // YYYY-MM
  totalEarned: number;
  totalTons: number;
  daysWorked: number;
}

