  const [message, setMessage] = useState('');

  const handleSave = () => {
    StorageService.saveSettings(settings);
    // Trigger a recalculation of existing vacation days in case rates changed
    // We can do this by just calling saveDay with the last day, but let's just re-save the days list
    // A cleaner way in this app structure: get days, run recalculate logic.
    // For now, we assume user edits trigger logic, but strictly speaking, changing rate here should update past records.
    // Let's force update.
    const allDays = StorageService.getWorkDays();
    if (allDays.length > 0) {
        // Just triggering save on the first day triggers the global recalculate logic in storage service
        StorageService.saveDay(allDays[0]);
    }

    setMessage('Ustawienia zapisane i przeliczone!');
    setTimeout(() => setMessage(''), 3000);
  };

  const handleChange = (key: keyof AppSettings, value: string) => {
    const numValue = parseFloat(value);
    setSettings(prev => ({
      ...prev,
      [key]: isNaN(numValue) ? 0 : numValue
    }));
  };

  const oldVacationDays = Math.max(0, settings.totalVacationDays - settings.vacationDaysLimit);

