import { AppSettings, LocationRate, WorkDay } from '../types';
import * as StorageService from './storage';

// Ten URL należy uzupełnić po wdrożeniu skryptu Google, 
// ale lepiej trzymać go w Settings użytkownika, aby nie hardcodować.
const getScriptUrl = () => {
    return StorageService.getSettings().googleScriptUrl || '';
};

interface ApiResponse {
    status: 'success' | 'error';
    data?: any;
    message?: string;
}

export const syncDriverData = async (driverId: string, days: WorkDay[]) => {
    const url = getScriptUrl();
    if (!url || !driverId) return;

    // Prosta konwersja danych do formatu przesyłu (możemy wysyłać tylko zmienione, 
    // ale dla uproszczenia przy małej skali wysyłamy całość jako JSON)
    const payload = {
        action: 'SAVE_DRIVER_DATA',
        driverId: driverId,
        days: JSON.stringify(days)
    };

    try {
        await fetch(url, {
            method: 'POST',
            body: JSON.stringify(payload)
        });
    } catch (e) {
        console.error("Sync error", e);
    }
};

export const fetchDriverData = async (driverId: string): Promise<WorkDay[] | null> => {
    const url = getScriptUrl();
    if (!url || !driverId) return null;

    try {
        const response = await fetch(`${url}?action=GET_DRIVER_DATA&driverId=${driverId}`);
        const json = await response.json();
        if (json.status === 'success' && json.data) {
            return JSON.parse(json.data);
        }
    } catch (e) {
        console.error("Fetch error", e);
    }
    return null;
};

export const syncLocations = async (locations: LocationRate[]) => {
    const url = getScriptUrl();
    if (!url) return;

    const payload = {
        action: 'UPDATE_LOCATIONS',
        locations: JSON.stringify(locations)
    };

    try {
        await fetch(url, {
            method: 'POST',
            body: JSON.stringify(payload)
        });
    } catch (e) {
        console.error("Locations sync error", e);
    }
};

export const fetchLocations = async (): Promise<LocationRate[] | null> => {
    const url = getScriptUrl();
    if (!url) return null;

    try {
        const response = await fetch(`${url}?action=GET_LOCATIONS`);
        const json = await response.json();
        if (json.status === 'success' && json.data) {
            return JSON.parse(json.data);
        }
    } catch (e) {
        console.error("Fetch locations error", e);
    }
    return null;
};

