import React, { useState, useEffect } from 'react';
import { Home, PlusCircle, Settings as SettingsIcon, MapPin, FileText } from 'lucide-react';
import Dashboard from './components/Dashboard';
import DayEditor from './components/DayEditor';
import LocationsManager from './components/LocationsManager';
import MonthlySummary from './components/MonthlySummary';
import Settings from './components/Settings';
import Login from './components/Login';
import AdminPanel from './components/AdminPanel';
import * as StorageService from './services/storage';
import * as ApiService from './services/api';

enum View {
  DASHBOARD = 'DASHBOARD',
  EDITOR = 'EDITOR',
  LOCATIONS = 'LOCATIONS',
  SUMMARY = 'SUMMARY',
  SETTINGS = 'SETTINGS'
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [editingDayId, setEditingDayId] = useState<string | null>(null);
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [showAdmin, setShowAdmin] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    // Check login status
    const settings = StorageService.getSettings();
    if (settings.driverId) {
      setIsLoggedIn(true);
      initializeData(settings.driverId);
    }
  }, []);

  const initializeData = async (driverId: string) => {
    setIsLoading(true);
    // 1. Fetch Locations (Global)
    const locations = await ApiService.fetchLocations();
    if (locations) {
        StorageService.saveLocations(locations);
    }
    // 2. Fetch Driver Data
    const days = await ApiService.fetchDriverData(driverId);
    if (days) {
        StorageService.saveWorkDays(days);
        setRefreshTrigger(prev => prev + 1);
    }
    setIsLoading(false);
  };

  const handleLogin = () => {
    const settings = StorageService.getSettings();
    setIsLoggedIn(true);
    if (settings.driverId) {
        initializeData(settings.driverId);
    }
  };

  const handleLogout = () => {
    if (confirm("Czy na pewno chcesz się wylogować?")) {
        const settings = StorageService.getSettings();
        settings.driverId = undefined;
        StorageService.saveSettings(settings);
        setIsLoggedIn(false);
    }
  };

  const handleOpenEditor = (dayId?: string) => {
    setEditingDayId(dayId || null);
    setCurrentView(View.EDITOR);
  };

  const handleCloseEditor = () => {
    setCurrentView(View.DASHBOARD);
    setEditingDayId(null);
    setRefreshTrigger(prev => prev + 1);
  };

  if (!isLoggedIn) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="h-[100dvh] w-full flex flex-col bg-slate-50 text-slate-900 font-sans overflow-hidden relative">

      {/* Loading Overlay */}
      {isLoading && (
        <div className="absolute inset-0 z-[60] bg-white/80 backdrop-blur-sm flex items-center justify-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
        </div>
      )}

      {/* Admin Panel Overlay */}
      {showAdmin && (
          <AdminPanel onClose={() => setShowAdmin(false)} />
      )}

      <main className="flex-1 overflow-hidden relative flex flex-col min-h-0">
        {currentView === View.DASHBOARD && (
          <div className="flex-1 overflow-y-auto min-h-0">
            <Dashboard onEditDay={handleOpenEditor} refreshTrigger={refreshTrigger} />
          </div>
        )}
        {currentView === View.EDITOR && (
          <div className="absolute inset-0 z-50 bg-white">
            <DayEditor dayId={editingDayId} onClose={handleCloseEditor} />
          </div>
        )}
        {currentView === View.LOCATIONS && (
          // View-Only Locations List (Admin manages it via Settings)
          <div className="flex-1 overflow-y-auto p-4">
              <div className="bg-white p-4 shadow-sm border-b border-slate-200 z-10 sticky top-0 mb-4">
                 <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                   <MapPin size={20} className="text-primary"/> Baza Miejscowości
                 </h2>
                 <p className="text-xs text-slate-500">Tylko do odczytu. Edycja w panelu Administratora.</p>
              </div>
              <ul className="bg-white rounded-xl shadow-sm border border-slate-100 divide-y divide-slate-100">
                  {StorageService.getLocations().map(loc => (
                      <li key={loc.id} className="p-3 pl-4 flex justify-between items-center">
                          <span className="font-semibold text-slate-800 text-sm">{loc.name}</span>
                          <span className="font-mono font-bold text-blue-600 bg-blue-50 px-1.5 py-0.5 rounded text-xs">{loc.rate.toFixed(2)} zł</span>
                      </li>
                  ))}
              </ul>
          </div>
        )}
        {currentView === View.SUMMARY && (
          <MonthlySummary />
        )}
        {currentView === View.SETTINGS && (
          <Settings onOpenAdmin={() => setShowAdmin(true)} onLogout={handleLogout} />
        )}
      </main>

      {/* Bottom Navigation */}
      {currentView !== View.EDITOR && (
        <nav className="h-20 bg-white border-t border-slate-200 flex justify-around items-center px-2 pb-2 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-40 flex-none">
          <button 
            onClick={() => setCurrentView(View.DASHBOARD)}
            className={`flex flex-col items-center p-2 rounded-xl transition ${currentView === View.DASHBOARD ? 'text-primary bg-blue-50' : 'text-slate-400'}`}
          >
            <Home size={24} />
            <span className="text-[10px] font-medium mt-1">Start</span>
          </button>

          <button 
             onClick={() => setCurrentView(View.SUMMARY)}
             className={`flex flex-col items-center p-2 rounded-xl transition ${currentView === View.SUMMARY ? 'text-primary bg-blue-50' : 'text-slate-400'}`}
          >
            <FileText size={24} />
            <span className="text-[10px] font-medium mt-1">Raport</span>
          </button>

          <button 
            onClick={() => setCurrentView(View.LOCATIONS)}
            className={`flex flex-col items-center p-2 rounded-xl transition ${currentView === View.LOCATIONS ? 'text-primary bg-blue-50' : 'text-slate-400'}`}
          >
            <MapPin size={24} />
            <span className="text-[10px] font-medium mt-1">Baza</span>
          </button>

          <button 
            onClick={() => setCurrentView(View.SETTINGS)}
            className={`flex flex-col items-center p-2 rounded-xl transition ${currentView === View.SETTINGS ? 'text-primary bg-blue-50' : 'text-slate-400'}`}
          >
            <SettingsIcon size={24} />
            <span className="text-[10px] font-medium mt-1">Opcje</span>
          </button>
        </nav>
      )}
    </div>
  );
};

export default App;

import { WorkDay, LocationRate, Trip, DayType, AppSettings } from '../types';
import * as ApiService from './api'; // Import API service
import { v4 as uuidv4 } from 'uuid';

const STORAGE_KEYS = {
  DAYS: 'kierowcapro_days',
  LOCATIONS: 'kierowcapro_locations',
  SETTINGS: 'kierowcapro_settings',
};

// --- Initial Data from Excel ---
const INITIAL_LOCATIONS: LocationRate[] = [
  { id: '1', name: 'Siemianowice DOMBUD', rate: 2.85 },
  // ... (reszta skrócona dla czytelności kodu, ale w produkcji powinna zostać zachowana lub pobrana z chmury)
  { id: 'extra3', name: 'MATERIAŁ FREZY', rate: 9 },
];

const DEFAULT_SETTINGS: AppSettings = {
  vacationRateOld: 210,
  vacationRateNew: 230,
  sickLeaveRate: 150,
  hourlyRate: 4.5,
  workshopRate: 10,
  waitingRate: 8,

  totalVacationDays: 30, // Łącznie z zaległym
  vacationDaysLimit: 26  // Limit bieżącego roku
};

// --- Settings Logic ---

export const getSettings = (): AppSettings => {
  const data = localStorage.getItem(STORAGE_KEYS.SETTINGS);
  return data ? JSON.parse(data) : DEFAULT_SETTINGS;
};

export const saveSettings = (settings: AppSettings) => {
  localStorage.setItem(STORAGE_KEYS.SETTINGS, JSON.stringify(settings));
};

// --- Locations Logic ---

export const getLocations = (): LocationRate[] => {
  const data = localStorage.getItem(STORAGE_KEYS.LOCATIONS);
  if (data) {
    return JSON.parse(data);
  } else {
    // Seed initial data if empty
    saveLocations(INITIAL_LOCATIONS, false); // Don't sync init seed to avoid overwrite cloud empty state
    return INITIAL_LOCATIONS;
  }
};

export const saveLocations = (locations: LocationRate[], sync = true) => {
  localStorage.setItem(STORAGE_KEYS.LOCATIONS, JSON.stringify(locations));
  if (sync) {
      ApiService.syncLocations(locations);
  }
};

// --- Work Days Logic ---

export const getWorkDays = (): WorkDay[] => {
  const data = localStorage.getItem(STORAGE_KEYS.DAYS);
  return data ? JSON.parse(data) : [];
};

export const saveWorkDays = (days: WorkDay[]) => {
  localStorage.setItem(STORAGE_KEYS.DAYS, JSON.stringify(days));
  // Trigger Sync
  const settings = getSettings();
  if (settings.driverId) {
    ApiService.syncDriverData(settings.driverId, days);
  }
};

export const getDayById = (id: string): WorkDay | undefined => {
  const days = getWorkDays();
  return days.find((d) => d.id === id);
};

// Helper: Recalculate vacation rates based on pool usage
const recalculateVacations = (allDays: WorkDay[]): WorkDay[] => {
    const settings = getSettings();
    const oldVacationPool = Math.max(0, settings.totalVacationDays - settings.vacationDaysLimit);

    // Process each year separately to be safe, although usually user cares about current year
    const years = Array.from(new Set(allDays.map(d => new Date(d.date).getFullYear())));

    let updatedDays = [...allDays];

    years.forEach(year => {
        // Filter vacation days for this year
        const vacationDays = updatedDays
            .filter(d => d.type === DayType.VACATION && new Date(d.date).getFullYear() === year)
            .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

        // Apply rates: First X days get OLD rate, rest get NEW rate
        vacationDays.forEach((day, index) => {
            const isOldRate = index < oldVacationPool;
            day.totalAmount = isOldRate ? settings.vacationRateOld : settings.vacationRateNew;
        });

        // Update the main array
        updatedDays = updatedDays.map(d => {
            const updatedVacation = vacationDays.find(vd => vd.id === d.id);
            return updatedVacation || d;
        });
    });

    return updatedDays;
};

export const saveDay = (day: WorkDay) => {
  let days = getWorkDays();
  const index = days.findIndex((d) => d.id === day.id);

  // Calculate specific day totals first (standard calculation)
  const calculatedDay = calculateDayTotals(day);

  if (index >= 0) {
    days[index] = calculatedDay;
  } else {
    days.push(calculatedDay);
  }

  // RECALCULATE VACATIONS GLOBALLY
  // This ensures that if we added a vacation day in the past, rates shift correctly
  if (calculatedDay.type === DayType.VACATION || days.some(d => d.type === DayType.VACATION)) {
      days = recalculateVacations(days);
  }

  // Sort by date desc
  days.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  saveWorkDays(days);
};

export const deleteDay = (id: string) => {
  let days = getWorkDays().filter((d) => d.id !== id);

  // Recalculate vacations in case we deleted one, shifting the pool
  days = recalculateVacations(days);

  saveWorkDays(days);
};

// --- Calculation Logic ---

export const calculateTrip = (weight: number, rate: number): { amount: number; bonus: number } => {
  const amount = weight * rate;
  const bonus = amount * 0.20; // 20% fuel bonus
  return { amount, bonus };
};

const calculateDurationHours = (start: string, end: string): number => {
  if (!start || !end) return 0;
  const [startH, startM] = start.split(':').map(Number);
  const [endH, endM] = end.split(':').map(Number);

  let diff = (endH * 60 + endM) - (startH * 60 + startM);
  if (diff < 0) diff += 24 * 60; // Handle overnight

  return diff / 60;
};

export const calculateDayTotals = (day: WorkDay): WorkDay => {
  const settings = getSettings();
  const zeros = {
    totalBonus: 0,
    totalHourlyBonus: 0,
    totalWeight: 0,
    workshopHours: 0,
    totalWorkshop: 0,
    waitingHours: 0,
    totalWaiting: 0,
    trips: []
  };

  // 1. URLOP
  if (day.type === DayType.VACATION) {
    // Note: The specific rate (old vs new) is handled in saveDay -> recalculateVacations
    // For live preview, we fallback to New Rate or keep existing if editing
    return {
      ...day,
      totalAmount: day.totalAmount || settings.vacationRateNew, 
      ...zeros
    };
  }

  // 2. L4 (SICK LEAVE)
  if (day.type === DayType.SICK_LEAVE) {
    return {
      ...day,
      totalAmount: settings.sickLeaveRate,
      ...zeros
    };
  }

  // 3. WORK - Calculate Trips AND Hourly Bonus AND Workshop
  let totalAmount = 0;
  let totalBonus = 0;
  let totalWeight = 0;
  let totalHourlyBonus = 0;

  // Hourly Bonus: Hours * Rate
  if (day.startTime && day.endTime) {
     const hours = calculateDurationHours(day.startTime, day.endTime);
     totalHourlyBonus = hours * settings.hourlyRate;
  }

  // Workshop Bonus
  const workshopHours = day.workshopHours || 0;
  const totalWorkshop = workshopHours * settings.workshopRate;

  // Waiting Bonus
  const waitingHours = day.waitingHours || 0;
  const totalWaiting = waitingHours * settings.waitingRate;

  const recalculatedTrips = day.trips.map(trip => {
    const { amount, bonus } = calculateTrip(trip.weight, trip.rate);
    totalAmount += amount;
    totalBonus += bonus;
    totalWeight += trip.weight;
    return { ...trip, amount, bonus };
  });

  return {
    ...day,
    trips: recalculatedTrips,
    totalAmount,
    totalBonus,
    totalHourlyBonus,
    totalWorkshop,
    totalWaiting,
    totalWeight
  };
};

// --- Import/Export ---

export const exportData = () => {
  const data = {
    settings: getSettings(),
    locations: getLocations(),
    days: getWorkDays(),
    exportDate: new Date().toISOString(),
  };
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `kierowcapro_backup_${new Date().toISOString().slice(0, 10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
};

export const importData = async (file: File): Promise<boolean> => {
  try {
    const text = await file.text();
    const data = JSON.parse(text);
    if (data.settings) {
      saveSettings(data.settings);
    }
    if (data.locations && Array.isArray(data.locations)) {
      saveLocations(data.locations, true); // Sync after import
    }
    if (data.days && Array.isArray(data.days)) {
      saveWorkDays(data.days);
    }
    return true;
  } catch (e) {
    console.error("Import failed", e);
    return false;
  }
};

