    const [error, setError] = useState('');
    const [isLoading, setIsLoading] = useState(false);

    useEffect(() => {
        const storedDrivers = StorageService.getDrivers();
        setDrivers(storedDrivers);

        const settings = StorageService.getSettings();
        if (settings.googleScriptUrl) {
            setScriptUrl(settings.googleScriptUrl);
            if (storedDrivers.length === 0) {
                // Auto fetch if URL exists but list empty
                handleSync(false);
            }
        } else {
            // First time logic
            setShowConfig(true); 
        }
    }, []);

    const handleSync = async (manual = true) => {
        setIsLoading(true);
        const fetched = await ApiService.fetchDrivers();
        if (fetched) {
            StorageService.saveDrivers(fetched, false); // No need to sync back
            setDrivers(fetched);
            if (manual) setError('');
        } else {
            if (manual) setError('Nie udało się pobrać listy kierowców. Sprawdź URL.');
        }
        setIsLoading(false);
    };

    const handleLogin = () => {
        if (!selectedDriverId) {
            setError('Wybierz kierowcę z listy');
            return;
        }

        const settings = StorageService.getSettings();
        if (showConfig && scriptUrl) {
            settings.googleScriptUrl = scriptUrl;
        }

        settings.driverId = selectedDriverId;
        StorageService.saveSettings(settings);
        onLogin();
    };

    return (
        <div className="flex flex-col items-center justify-center h-full p-6 bg-slate-50">
            <div className="bg-white p-8 rounded-2xl shadow-xl w-full max-w-sm space-y-6">
                <div className="text-center space-y-2">
                    <div className="bg-blue-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto text-primary mb-4">
                        <Truck size={32} />
                    </div>
                    <h1 className="text-2xl font-black text-slate-800">KierowcaPRO</h1>
                    <p className="text-slate-500 text-sm">Zaloguj się do systemu</p>
                </div>

                <div className="space-y-4">
                    {drivers.length > 0 ? (
                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Wybierz Kierowcę</label>
                            <select 
                                value={selectedDriverId}
                                onChange={(e) => setSelectedDriverId(e.target.value)}
                                className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl font-bold text-lg focus:ring-2 focus:ring-blue-500 outline-none text-slate-700"
                            >
                                <option value="">-- Wybierz z listy --</option>
                                {drivers.map(d => (
                                    <option key={d.id} value={d.id}>{d.name}</option>
                                ))}
                            </select>

                            <div className="text-right mt-1">
                                <button onClick={() => handleSync()} className="text-[10px] text-blue-500 font-bold flex items-center justify-end gap-1">
                                    <RefreshCw size={10} className={isLoading ? 'animate-spin' : ''}/> Odśwież listę
                                </button>
                            </div>
                        </div>
                    ) : (
                        <div className="text-center p-4 bg-yellow-50 text-yellow-800 text-sm rounded-xl">
                            <p className="font-bold mb-1">Brak listy kierowców.</p>
                            <p className="text-xs">Skonfiguruj połączenie poniżej i kliknij "Pobierz listę".</p>
                        </div>
                    )}

                    {error && <p className="text-red-500 text-sm text-center font-medium">{error}</p>}

                    <button 
                        onClick={handleLogin}
                        disabled={drivers.length === 0}
                        className="w-full bg-primary text-white py-4 rounded-xl font-bold shadow-lg shadow-blue-200 flex items-center justify-center gap-2 active:scale-[0.98] transition-transform disabled:opacity-50 disabled:scale-100"
                    >
                        <LogIn size={20} /> Zaloguj się
                    </button>
                </div>

                <div className="pt-4 border-t border-slate-100 text-center">
                    <button 
                        onClick={() => setShowConfig(!showConfig)}
                        className="text-xs text-slate-400 hover:text-slate-600 flex items-center justify-center gap-1 mx-auto"
                    >
                        <Link size={12} /> {showConfig ? 'Ukryj konfigurację' : 'Konfiguracja połączenia'}
                    </button>

                    {showConfig && (
                        <div className="mt-4 text-left animate-fade-in space-y-3">
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Google Script URL</label>
                                <input 
                                    type="text" 
                                    value={scriptUrl}
                                    onChange={(e) => setScriptUrl(e.target.value)}
                                    placeholder="https://script.google.com/..."
                                    className="w-full p-2 text-xs bg-slate-50 border border-slate-200 rounded-lg"
                                />
                            </div>
                            <button 
                                onClick={() => {
                                    const settings = StorageService.getSettings();
                                    settings.googleScriptUrl = scriptUrl;
                                    StorageService.saveSettings(settings);
                                    handleSync(true);
                                }}
                                className="w-full py-2 bg-slate-100 text-slate-600 text-xs font-bold rounded-lg hover:bg-slate-200"
                            >
                                Zapisz URL i Pobierz Listę
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default Login;

