### 2. Instrukcja: Google Apps Script & Arkusze (KROK PO KROKU)

Aby nowy system kodów i automatycznego tworzenia arkuszy zadziałał, wykonaj dokładnie te kroki:

#### KROK A: Przygotowanie Arkusza

1.  Otwórz swój Google Sheet.
2.  Upewnij się, że masz zakładkę o nazwie **`MIEJSCOWOŚCI`** (Nagłówki w A1: `ID`, B1: `Nazwa`, C1: `Stawka`).
3.  Stwórz nową zakładkę (kliknij plus na dole) i nazwij ją dokładnie: **`KIEROWCY`**.
4.  W zakładce `KIEROWCY` wpisz nagłówki w pierwszym wierszu:
    *   **A1**: `ID`
    *   **B1**: `Imie Nazwisko`
    *   **C1**: `Kod`

#### KROK B: Aktualizacja Skryptu

1.  W arkuszu wejdź w **Rozszerzenia** -> **Apps Script**.
2.  Skasuj cały obecny kod i wklej ten nowy (obsługuje kody logowania):

```javascript
function doGet(e) {
  const action = e.parameter.action;

  if (action === 'GET_LOCATIONS') {
    return getLocations();
  } else if (action === 'GET_DRIVER_DATA') {
    return getDriverData(e.parameter.driverId);
  } else if (action === 'GET_DRIVERS') {
    return getDriversList();
  }

  return response({status: 'error', message: 'Invalid action'});
}

function doPost(e) {
  let data;
  try {
    data = JSON.parse(e.postData.contents);
  } catch(err) {
    return response({status: 'error', message: 'Invalid JSON'});
  }

  const action = data.action;

  if (action === 'SAVE_DRIVER_DATA') {
    return saveDriverData(data.driverId, data.days);
  } else if (action === 'UPDATE_LOCATIONS') {
    return updateLocations(data.locations);
  } else if (action === 'UPDATE_DRIVERS') {
    return updateDrivers(data.drivers);
  }

  return response({status: 'error', message: 'Invalid action'});
}

// --- Logic ---

function response(obj) {
  return ContentService.createTextOutput(JSON.stringify(obj)).setMimeType(ContentService.MimeType.JSON);
}

function getDriversList() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName('KIEROWCY');
  if (!sheet) return response({status: 'success', data: '[]'});

  const data = sheet.getDataRange().getValues();
  const drivers = [];
  // Skip header, read columns A (ID), B (Name), C (Code)
  for (let i = 1; i < data.length; i++) {
    if (data[i][0]) { 
        drivers.push({
            id: data[i][0],
            name: data[i][1],
            code: data[i][2] ? String(data[i][2]) : ''
        });
    }
  }
  return response({status: 'success', data: JSON.stringify(drivers)});
}

function updateDrivers(driversJson) {
  const drivers = JSON.parse(driversJson);
  let sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName('KIEROWCY');
  if (!sheet) {
    sheet = SpreadsheetApp.getActiveSpreadsheet().insertSheet('KIEROWCY');
    sheet.appendRow(['ID', 'Imie Nazwisko', 'Kod']);
  }

  // Clear old data
  if (sheet.getLastRow() > 1) {
    sheet.getRange(2, 1, sheet.getLastRow() - 1, 3).clearContent();
  }

  // Save ID, Name, Code
  const rows = drivers.map(d => [d.id, d.name, d.code]);
  if (rows.length > 0) {
    sheet.getRange(2, 1, rows.length, 3).setValues(rows);
  }

  return response({status: 'success'});
}

function getLocations() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName('MIEJSCOWOŚCI');
  if (!sheet) return response({status: 'error', message: 'Sheet MIEJSCOWOŚCI missing'});

  const data = sheet.getDataRange().getValues();
  const locations = [];
  for (let i = 1; i < data.length; i++) {
    locations.push({
      id: data[i][0],
      name: data[i][1],
      rate: Number(data[i][2])
    });
  }
  return response({status: 'success', data: JSON.stringify(locations)});
}

function updateLocations(locationsJson) {
  const locations = JSON.parse(locationsJson);
  let sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName('MIEJSCOWOŚCI');
  if (!sheet) {
    sheet = SpreadsheetApp.getActiveSpreadsheet().insertSheet('MIEJSCOWOŚCI');
    sheet.appendRow(['ID', 'Nazwa', 'Stawka']);
  }

  if (sheet.getLastRow() > 1) {
    sheet.getRange(2, 1, sheet.getLastRow() - 1, 3).clearContent();
  }

  const rows = locations.map(l => [l.id, l.name, l.rate]);
  if (rows.length > 0) {
    sheet.getRange(2, 1, rows.length, 3).setValues(rows);
  }
  return response({status: 'success'});
}

function getDriverData(driverId) {
  if (!driverId) return response({status: 'error', message: 'No ID'});

  const sheetName = 'DRIVER_' + driverId.toUpperCase();
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName(sheetName);

  if (!sheet) return response({status: 'success', data: '[]'}); 

  const data = sheet.getDataRange().getValues();
  const days = [];
  for (let i = 1; i < data.length; i++) {
    try {
      days.push(JSON.parse(data[i][2]));
    } catch (e) {}
  }
  return response({status: 'success', data: JSON.stringify(days)});
}

function saveDriverData(driverId, daysJson) {
  if (!driverId) return response({status: 'error', message: 'No ID'});
  const days = JSON.parse(daysJson);

  const sheetName = 'DRIVER_' + driverId.toUpperCase();
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName(sheetName);

  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
    sheet.appendRow(['DayID', 'Date', 'Full_JSON_Data']);
  }

  if (sheet.getLastRow() > 1) {
    sheet.getRange(2, 1, sheet.getLastRow() - 1, 3).clearContent();
  }

  const rows = days.map(d => [d.id, d.date, JSON.stringify(d)]);
  if (rows.length > 0) {
    sheet.getRange(2, 1, rows.length, 3).setValues(rows);
  }

  return response({status: 'success'});
}
```

3.  Kliknij **Wdróż** (Deploy) -> **Nowe wdrożenie**.
