    if (!url || !driverId || url.includes('...')) return;

    const payload = {
        action: 'SAVE_DRIVER_DATA',
        driverId: driverId,
        days: JSON.stringify(days)
    };

    try {
        await fetch(url, {
            method: 'POST',
            body: JSON.stringify(payload)
        });
    } catch (e) {
        console.error("Sync error", e);
    }
