import React, { useState, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { Trash2, Plus, Download, Upload, Save, X, Edit2, Database, Lock } from 'lucide-react';
import { LocationRate } from '../types';
import * as StorageService from '../services/storage';

interface LocationsManagerProps {
    mode?: 'ADMIN' | 'DRIVER';
}

const LocationsManager: React.FC<LocationsManagerProps> = ({ mode = 'ADMIN' }) => {
  const [locations, setLocations] = useState<LocationRate[]>([]);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({ name: '', rate: '' });
  const [message, setMessage] = useState('');

  useEffect(() => {
    setLocations(StorageService.getLocations());
  }, []);

  const openAddForm = () => {
    setEditingId(null);
    setFormData({ name: '', rate: '' });
    setIsFormOpen(true);
  };

  const openEditForm = (loc: LocationRate) => {
    // Security check
    if (mode !== 'ADMIN') return;

    setEditingId(loc.id);
    setFormData({ name: loc.name, rate: loc.rate.toString() });
    setIsFormOpen(true);
  };

  const closeForm = () => {
    setIsFormOpen(false);
    setEditingId(null);
    setFormData({ name: '', rate: '' });
  };

  const handleSave = () => {
    if (!formData.name || !formData.rate) return;
    const rate = parseFloat(formData.rate.replace(',', '.'));
    if (isNaN(rate)) return;

    let updatedLocations: LocationRate[];

    if (editingId) {
      // Update existing (Admin only logic effectively, as edit form won't open for driver)
      updatedLocations = locations.map(loc => 
        loc.id === editingId ? { ...loc, name: formData.name, rate } : loc
      );
      setMessage('Zaktualizowano miejscowość');
    } else {
      // Add new
      updatedLocations = [...locations, { id: uuidv4(), name: formData.name, rate }];
      setMessage('Dodano nową miejscowość do bazy Google');
    }

    StorageService.saveLocations(updatedLocations);
    setLocations(updatedLocations);
    closeForm();
    setTimeout(() => setMessage(''), 3000);
  };

  const handleDelete = (id: string) => {
    if (mode !== 'ADMIN') return;

    if (confirm('Czy na pewno usunąć tę miejscowość?')) {
      const updated = locations.filter(l => l.id !== id);
      StorageService.saveLocations(updated);
      setLocations(updated);
    }
  };

  const handleExport = () => {
    StorageService.exportData();
    setMessage('Baza została zapisana do pliku!');
    setTimeout(() => setMessage(''), 3000);
  };

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const success = await StorageService.importData(e.target.files[0]);
      if (success) {
        setLocations(StorageService.getLocations());
        setMessage('Baza wczytana pomyślnie!');
      } else {
        setMessage('Błąd importu pliku!');
      }
      setTimeout(() => setMessage(''), 3000);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50">

      {/* 1. FIXED HEADER */}
      <div className="bg-white p-4 shadow-sm border-b border-slate-200 z-10 flex-none">
        <div className="flex justify-between items-center">
          <div>
            <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
              <Database size={20} className="text-primary"/> Baza Miejscowości
            </h2>
            <p className="text-xs text-slate-500">Ilość pozycji: {locations.length}</p>
          </div>

          <button 
            onClick={openAddForm}
            className="bg-primary text-white px-3 py-2 rounded-lg flex items-center gap-1.5 shadow-sm hover:bg-blue-700 transition active:scale-95 text-sm font-medium"
          >
            <Plus size={16} /> Dodaj Nowy
          </button>
        </div>
      </div>

      {/* Message Toast */}
      {message && (
        <div className="absolute top-20 left-4 right-4 z-50 p-3 bg-green-100 text-green-800 border border-green-200 rounded-lg text-center text-sm font-bold shadow-md animate-fade-in">
          {message}
        </div>
      )}

      {/* 2. SCROLLABLE LIST AREA */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 min-h-0">

        {/* Add/Edit Form (Inline in scroll area) */}
        {isFormOpen && (
          <div className="bg-white p-4 rounded-xl border-2 border-blue-100 shadow-md animate-fade-in mb-4">
            <div className="flex justify-between items-center mb-3 border-b border-slate-100 pb-2">
              <h3 className="text-sm font-bold text-blue-800">
                {editingId ? 'Edytuj wpis' : 'Nowy wpis do bazy'}
              </h3>
              <button onClick={closeForm} className="text-slate-400 hover:text-slate-600">
                <X size={18} />
              </button>
            </div>

            <div className="space-y-3">
              <div>
                <label className="block text-xs font-semibold text-slate-500 mb-1">Nazwa miejscowości</label>
                <input 
                  type="text" 
                  autoFocus
                  placeholder="Np. Katowice Centrum" 
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  className="w-full p-3 rounded-lg border border-slate-300 focus:ring-2 focus:ring-blue-500 outline-none bg-slate-50"
                />
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-500 mb-1">Stawka (zł/t)</label>
                <input 
                  type="number" 
                  step="0.01"
                  placeholder="0.00" 
                  value={formData.rate}
                  onChange={e => setFormData({...formData, rate: e.target.value})}
                  className="w-full p-3 rounded-lg border border-slate-300 focus:ring-2 focus:ring-blue-500 outline-none font-mono bg-slate-50"
                />
              </div>
              <div className="flex gap-2 justify-end pt-2">
                <button 
                  onClick={handleSave} 
                  className="bg-blue-600 text-white w-full py-3 rounded-lg flex items-center justify-center gap-2 font-bold hover:bg-blue-700 active:scale-95 transition-transform shadow-sm"
                >
                  <Save size={18} /> Zapisz w Bazie
                </button>
              </div>
            </div>
          </div>
        )}

        {/* The List */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
          {locations.length === 0 ? (
            <div className="p-10 text-center text-slate-400">Brak dodanych miejscowości.</div>
          ) : (
            <ul className="divide-y divide-slate-100">
              {locations.map(loc => (
                <li key={loc.id} className="p-3 pl-4 flex justify-between items-center hover:bg-slate-50 transition-colors">
                  <div className="flex-1 pr-2">
                    <div className="font-semibold text-slate-800 text-sm leading-tight">{loc.name}</div>
                    <div className="text-xs text-slate-400 mt-1">
                      Stawka: <span className="font-mono font-bold text-blue-600 bg-blue-50 px-1.5 py-0.5 rounded">{loc.rate.toFixed(2)} zł</span>
                    </div>
                  </div>

                  {/* Buttons visible ONLY for Admin */}
                  {mode === 'ADMIN' ? (
                      <div className="flex items-center gap-1">
                        <button 
                          onClick={() => openEditForm(loc)} 
                          className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition"
                        >
                          <Edit2 size={18} />
                        </button>
                        <button 
                          onClick={() => handleDelete(loc.id)} 
                          className="p-2 text-slate-400 hover:text-danger hover:bg-red-50 rounded-lg transition"
                        >
                          <Trash2 size={18} />
                        </button>
                      </div>
                  ) : (
                      // Driver View: Read Only Icon or nothing
                      <div className="p-2 text-slate-300">
                          <Lock size={14} />
                      </div>
                  )}
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>

      {/* 3. FIXED FOOTER (Import/Export) - ONLY FOR ADMIN */}
      {mode === 'ADMIN' && (
        <div className="bg-white p-3 border-t border-slate-200 z-10 flex-none shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
            <h3 className="text-[10px] font-bold text-slate-400 uppercase mb-2 tracking-wider text-center">Kopia Zapasowa (Import / Export)</h3>
            <div className="grid grid-cols-2 gap-3">
            <button onClick={handleExport} className="flex items-center justify-center gap-2 p-3 bg-slate-50 border border-slate-200 rounded-lg hover:bg-slate-100 active:bg-slate-200 transition text-slate-700">
                <Download size={18} className="text-slate-500" />
                <span className="text-sm font-bold">Zapisz Bazę</span>
            </button>

            <label className="flex items-center justify-center gap-2 p-3 bg-slate-50 border border-slate-200 rounded-lg hover:bg-slate-100 active:bg-slate-200 transition cursor-pointer text-slate-700">
                <Upload size={18} className="text-slate-500" />
                <span className="text-sm font-bold">Wczytaj Bazę</span>
                <input type="file" accept=".json" onChange={handleImport} className="hidden" />
            </label>
            </div>
        </div>
      )}

    </div>
  );
};

export default LocationsManager;

import React, { useState, useEffect } from 'react';
import { Home, PlusCircle, Settings as SettingsIcon, MapPin, FileText } from 'lucide-react';
import Dashboard from './components/Dashboard';
import DayEditor from './components/DayEditor';
import LocationsManager from './components/LocationsManager';
import MonthlySummary from './components/MonthlySummary';
import Settings from './components/Settings';
import Login from './components/Login';
import AdminPanel from './components/AdminPanel';
import InstallPrompt from './components/InstallPrompt';
import * as StorageService from './services/storage';
import * as ApiService from './services/api';

enum View {
  DASHBOARD = 'DASHBOARD',
  EDITOR = 'EDITOR',
  LOCATIONS = 'LOCATIONS',
  SUMMARY = 'SUMMARY',
  SETTINGS = 'SETTINGS'
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [editingDayId, setEditingDayId] = useState<string | null>(null);
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [showAdmin, setShowAdmin] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    // Check login status
    const settings = StorageService.getSettings();
    if (settings.driverId) {
      setIsLoggedIn(true);
      initializeData(settings.driverId);
    }
  }, []);

  const initializeData = async (driverId: string) => {
    setIsLoading(true);
    // 1. Fetch Locations (Global)
    const locations = await ApiService.fetchLocations();
    if (locations) {
        StorageService.saveLocations(locations);
    }
    // 2. Fetch Driver Data
    const days = await ApiService.fetchDriverData(driverId);
    if (days) {
        StorageService.saveWorkDays(days);
        setRefreshTrigger(prev => prev + 1);
    }
    setIsLoading(false);
  };

  const handleLogin = () => {
    const settings = StorageService.getSettings();
    setIsLoggedIn(true);
    if (settings.driverId) {
        initializeData(settings.driverId);
    }
  };

  const handleLogout = () => {
    if (confirm("Czy na pewno chcesz się wylogować?")) {
        const settings = StorageService.getSettings();
        settings.driverId = undefined;
        StorageService.saveSettings(settings);
        setIsLoggedIn(false);
    }
  };

  const handleOpenEditor = (dayId?: string) => {
    setEditingDayId(dayId || null);
    setCurrentView(View.EDITOR);
  };

  const handleCloseEditor = () => {
    setCurrentView(View.DASHBOARD);
    setEditingDayId(null);
    setRefreshTrigger(prev => prev + 1);
  };

  if (!isLoggedIn) {
    return (
        <>
            <Login onLogin={handleLogin} />
            <InstallPrompt />
        </>
    );
  }

  return (
    <div className="h-[100dvh] w-full flex flex-col bg-slate-50 text-slate-900 font-sans overflow-hidden relative">

      {/* Install Prompt (Shows only if criteria met) */}
      <InstallPrompt />

      {/* Loading Overlay */}
      {isLoading && (
        <div className="absolute inset-0 z-[60] bg-white/80 backdrop-blur-sm flex items-center justify-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
        </div>
      )}

      {/* Admin Panel Overlay */}
      {showAdmin && (
          <AdminPanel onClose={() => setShowAdmin(false)} />
      )}

      <main className="flex-1 overflow-hidden relative flex flex-col min-h-0">
        {currentView === View.DASHBOARD && (
          <div className="flex-1 overflow-y-auto min-h-0">
            <Dashboard onEditDay={handleOpenEditor} refreshTrigger={refreshTrigger} />
          </div>
        )}
        {currentView === View.EDITOR && (
          <div className="absolute inset-0 z-50 bg-white">
            <DayEditor dayId={editingDayId} onClose={handleCloseEditor} />
          </div>
        )}
        {currentView === View.LOCATIONS && (
          // Driver View: Can ADD but NOT Edit
          <div className="flex-1 overflow-hidden">
             <LocationsManager mode="DRIVER" />
          </div>
        )}
        {currentView === View.SUMMARY && (
          <MonthlySummary />
        )}
        {currentView === View.SETTINGS && (
          <Settings onOpenAdmin={() => setShowAdmin(true)} onLogout={handleLogout} />
        )}
      </main>

      {/* Bottom Navigation */}
      {currentView !== View.EDITOR && (
        <nav className="h-20 bg-white border-t border-slate-200 flex justify-around items-center px-2 pb-2 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-40 flex-none">
          <button 
            onClick={() => setCurrentView(View.DASHBOARD)}
            className={`flex flex-col items-center p-2 rounded-xl transition ${currentView === View.DASHBOARD ? 'text-primary bg-blue-50' : 'text-slate-400'}`}
          >
            <Home size={24} />
            <span className="text-[10px] font-medium mt-1">Start</span>
          </button>

          <button 
             onClick={() => setCurrentView(View.SUMMARY)}
             className={`flex flex-col items-center p-2 rounded-xl transition ${currentView === View.SUMMARY ? 'text-primary bg-blue-50' : 'text-slate-400'}`}
          >
            <FileText size={24} />
            <span className="text-[10px] font-medium mt-1">Raport</span>
          </button>

          <button 
            onClick={() => setCurrentView(View.LOCATIONS)}
            className={`flex flex-col items-center p-2 rounded-xl transition ${currentView === View.LOCATIONS ? 'text-primary bg-blue-50' : 'text-slate-400'}`}
          >
            <MapPin size={24} />
            <span className="text-[10px] font-medium mt-1">Baza</span>
          </button>

          <button 
            onClick={() => setCurrentView(View.SETTINGS)}
            className={`flex flex-col items-center p-2 rounded-xl transition ${currentView === View.SETTINGS ? 'text-primary bg-blue-50' : 'text-slate-400'}`}
          >
            <SettingsIcon size={24} />
            <span className="text-[10px] font-medium mt-1">Opcje</span>
          </button>
        </nav>
      )}
    </div>
  );
};

export default App;

