             </div>
             </>
           )}
           <div className="flex justify-between items-end border-t border-slate-600 pt-2">
              <span className="text-slate-300">Zarobek całkowity:</span>
              <span className="text-2xl font-bold text-green-400">
                {(totals.totalAmount + totals.totalBonus + (totals.totalHourlyBonus || 0) + (totals.totalWorkshop || 0) + (totals.totalWaiting || 0)).toFixed(2)} zł
              </span>
           </div>
      </div>
    </div>
  );
};

// Sub-component for Trip Card to handle Search State efficiently
const TripCard: React.FC<{
  trip: Trip;
  locations: LocationRate[];
  onChange: (field: keyof Trip, value: any) => void;
  onRemove: () => void;
}> = ({ trip, locations, onChange, onRemove }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  // Initialize search term if trip has location
  useEffect(() => {
    if (trip.locationName && !isSearching) {
      setSearchTerm(trip.locationName);
    }
  }, [trip.locationName, isSearching]);

  const filteredLocations = locations.filter(l => 
    l.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelectLocation = (loc: LocationRate) => {
    setSearchTerm(loc.name);
    setIsSearching(false);
    onChange('locationId', loc.id);
  };

  const handleSearchFocus = () => {
    setIsSearching(true);
    setSearchTerm(''); // Clear to show all or let user type
    onChange('locationId', ''); // Clear current selection
  };

  // Check if fixed rate (lump sum)
  const isFixedRate = trip.rate > 10;

  return (
    <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 relative">
      <div className="grid grid-cols-12 gap-3">
        {/* Searchable Location Input */}
        <div className="col-span-12 relative">
          <label className="block text-xs font-medium text-slate-500 mb-1">Miejscowość</label>
          <div className="relative">
             <div className="absolute left-3 top-3 text-slate-400">
               <Search size={18} />
             </div>
             <input
              ref={inputRef}
              type="text"
              value={searchTerm}
              onFocus={() => setIsSearching(true)}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Szukaj miejscowości..."
              className="w-full p-2 pl-10 border border-slate-300 rounded-lg bg-gray-50 focus:ring-2 focus:ring-blue-500 outline-none"
             />
             {isSearching && (
               <button 
                onClick={() => { setIsSearching(false); setSearchTerm(trip.locationName); }} 
                className="absolute right-2 top-2 p-1 text-slate-400"
               >
                 <X size={18}/>
               </button>
             )}
          </div>

          {/* Dropdown List */}
          {isSearching && (
            <div className="absolute z-50 left-0 right-0 top-full mt-1 bg-white border border-slate-200 rounded-lg shadow-xl max-h-60 overflow-y-auto">
              {filteredLocations.length === 0 ? (
                 <div className="p-3 text-sm text-slate-400 text-center">Brak wyników</div>
              ) : (
                filteredLocations.map(loc => (
                  <button
                    key={loc.id}
                    onClick={() => handleSelectLocation(loc)}
                    className="w-full text-left p-3 hover:bg-blue-50 border-b border-slate-50 last:border-0 flex justify-between items-center"
                  >
                    <span className="font-medium text-slate-700">{loc.name}</span>
                    <span className="text-xs font-mono text-slate-400 bg-slate-100 px-2 py-1 rounded">{loc.rate} zł</span>
                  </button>
                ))
              )}
            </div>
          )}
        </div>

        <div className="col-span-4">
          <label className="block text-xs font-medium text-slate-500 mb-1">
             {isFixedRate ? 'Ryczałt' : 'Tony'}
          </label>
          <input 
            type="number" 
            step="0.1"
            value={trip.weight || ''}
            onChange={(e) => onChange('weight', parseFloat(e.target.value) || 0)}
            disabled={isFixedRate}
            className={`w-full p-2 border border-slate-300 rounded-lg font-mono ${isFixedRate ? 'bg-slate-200 text-slate-500 cursor-not-allowed' : 'bg-gray-50'}`}
            placeholder="0"
          />
        </div>
        <div className="col-span-4">
          <label className="block text-xs font-medium text-slate-500 mb-1">Stawka</label>
          <input 
            type="number" 
            disabled
            value={trip.rate}
            className="w-full p-2 bg-slate-100 border border-slate-200 rounded-lg text-slate-500"
          />
        </div>
        <div className="col-span-4">
          <label className="block text-xs font-medium text-slate-500 mb-1">Suma</label>
          <div className="w-full p-2 bg-slate-50 border border-slate-200 rounded-lg font-bold text-slate-700 text-right">
            {trip.amount.toFixed(2)}
          </div>
        </div>
      </div>

      <button 
        onClick={onRemove}
        className="absolute -top-2 -right-2 bg-white text-danger border border-slate-200 p-1.5 rounded-full shadow-sm"
      >
        <Trash2 size={16} />
      </button>
    </div>
  );
};

export default DayEditor;

import React, { useEffect, useState, useRef } from 'react';
import { format, parseISO } from 'date-fns';
import { pl } from 'date-fns/locale';
import { TrendingUp, Calendar, Briefcase, Truck, Wrench, Hourglass, Plus, PlusCircle, Thermometer, Palmtree, Trash2 } from 'lucide-react';
import { WorkDay, DayType } from '../types';
import * as StorageService from '../services/storage';
import { BarChart, Bar, XAxis, YAxis, ResponsiveContainer, CartesianGrid, Cell, LabelList } from 'recharts';

interface DashboardProps {
  onEditDay: (id: string) => void;
  refreshTrigger: number;
}

const Dashboard: React.FC<DashboardProps> = ({ onEditDay, refreshTrigger }) => {
  const [days, setDays] = useState<WorkDay[]>([]);
  const [monthStats, setMonthStats] = useState({ earned: 0, tons: 0, count: 0 });
  const [vacationStats, setVacationStats] = useState({ used: 0, remaining: 0 });

  // 0 = Current Month, 1 = Previous Month
  const [historyOffset, setHistoryOffset] = useState(0); 
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const data = StorageService.getWorkDays();
    const settings = StorageService.getSettings();
    setDays(data);

    // Calculate stats based on Selected Month (via historyOffset)
    const targetDate = new Date();
    targetDate.setMonth(targetDate.getMonth() - historyOffset);

    const targetMonth = targetDate.getMonth();
    const targetYear = targetDate.getFullYear();

    const selectedMonthDays = data.filter(d => {
      const date = new Date(d.date);
      return date.getMonth() === targetMonth && date.getFullYear() === targetYear;
    });

    const earned = selectedMonthDays.reduce((acc, d) => {
      // Sum: Trips + Fuel Bonus + Hourly Bonus + Workshop + Waiting
      return acc + d.totalAmount + d.totalBonus + (d.totalHourlyBonus || 0) + (d.totalWorkshop || 0) + (d.totalWaiting || 0);
    }, 0);

    const tons = selectedMonthDays.reduce((acc, d) => acc + d.totalWeight, 0);

    // Vacation is usually calculated Annually, keeping it based on Current Year for "Remaining" logic
    const currentYear = new Date().getFullYear();
    const usedVacation = data.filter(d => 
        d.type === DayType.VACATION && 
        new Date(d.date).getFullYear() === currentYear
    ).length;

    setMonthStats({
      earned,
      tons,
      count: selectedMonthDays.filter(d => d.type === DayType.WORK).length
    });

    setVacationStats({
        used: usedVacation,
        remaining: settings.totalVacationDays - usedVacation
    });

    // Auto-scroll to end if it's current month (to see today) or reset to start
    if (scrollContainerRef.current) {
        setTimeout(() => {
            if (scrollContainerRef.current) {
                 if (historyOffset === 0) {
                    scrollContainerRef.current.scrollLeft = scrollContainerRef.current.scrollWidth;
                 } else {
                    scrollContainerRef.current.scrollLeft = 0;
                 }
            }
        }, 100);
    }

  }, [refreshTrigger, historyOffset]);

  const handleDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm('Czy usunąć ten dzień?')) {
      StorageService.deleteDay(id);
      setDays(StorageService.getWorkDays());
    }
  };

  // --- PREPARE CHART DATA (Full Selected Month) ---
  const targetDate = new Date();
  targetDate.setMonth(targetDate.getMonth() - historyOffset);
  const year = targetDate.getFullYear();
  const month = targetDate.getMonth();

  // Get number of days in the selected month
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  const chartData = Array.from({ length: daysInMonth }, (_, i) => {
      const dayNum = i + 1;
      // Construct date string YYYY-MM-DD manually to avoid timezone issues
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(dayNum).padStart(2, '0')}`;

      const day = days.find(d => d.date === dateStr);

      // Check if it's "Today" for highlighting
      const today = new Date();
      const isToday = today.getDate() === dayNum && today.getMonth() === month && today.getFullYear() === year;

      return {
        name: `${String(dayNum).padStart(2, '0')}.${String(month + 1).padStart(2, '0')}`, // dd.MM
        fullDate: dateStr,
        zarobek: day ? Math.round(day.totalAmount + day.totalBonus + (day.totalHourlyBonus || 0) + (day.totalWorkshop || 0) + (day.totalWaiting || 0)) : 0,
        type: day?.type,
        isToday
      };
  });

  // Calculate dynamic width: e.g. 45px per day. Min width 100% of container.
  const chartWidth = Math.max(300, daysInMonth * 45);

  const getBarColor = (type?: DayType, isToday?: boolean) => {
      if (isToday) return '#f59e0b'; // Amber for Today
      if (type === DayType.VACATION) return '#16a34a'; // green-600
      if (type === DayType.SICK_LEAVE) return '#dc2626'; // red-600
      if (type === DayType.WORK) return '#2563eb'; // blue-600
      return '#e2e8f0'; // slate-200 (empty days)
  };

  // Filter History List based on toggle
  const getHistoryDays = () => {
    return days.filter(d => {
        const dDate = parseISO(d.date);
        return dDate.getMonth() === month && dDate.getFullYear() === year;
    });
  };

  const filteredHistory = getHistoryDays();

  const displayedMonthName = format(targetDate, 'LLLL yyyy', { locale: pl });
  const isCurrentMonth = historyOffset === 0;

  return (
    <div className="p-4 space-y-6 pb-24">

      {/* Top Toggle */}
      <div className="flex items-center justify-between">
         <h2 className="text-xl font-bold text-slate-800 capitalize">{displayedMonthName}</h2>
         <div className="bg-white p-1 rounded-xl shadow-sm border border-slate-200 flex text-xs font-bold">
             <button
                onClick={() => setHistoryOffset(0)}
                className={`px-3 py-1.5 rounded-lg transition ${historyOffset === 0 ? 'bg-blue-100 text-primary' : 'text-slate-400 hover:text-slate-600'}`}
             >
                Bieżący
             </button>
             <button
                onClick={() => setHistoryOffset(1)}
                className={`px-3 py-1.5 rounded-lg transition ${historyOffset === 1 ? 'bg-blue-100 text-primary' : 'text-slate-400 hover:text-slate-600'}`}
             >
                Poprzedni
             </button>
        </div>
      </div>

      {/* Header Stats */}
      <div className="grid grid-cols-2 gap-3">
        {/* Money Tile */}
        <div className={`col-span-2 rounded-2xl p-4 text-white shadow-lg transition-colors ${isCurrentMonth ? 'bg-gradient-to-br from-blue-600 to-blue-700 shadow-blue-200' : 'bg-gradient-to-br from-slate-600 to-slate-700 shadow-slate-200'}`}>
          <div className={`flex items-center gap-2 mb-1 text-xs uppercase tracking-wide font-bold ${isCurrentMonth ? 'text-blue-100' : 'text-slate-200'}`}>
            <TrendingUp size={14} /> {isCurrentMonth ? 'Ten miesiąc' : 'Poprzedni miesiąc'}
          </div>
          <div className="text-3xl font-bold">{monthStats.earned.toFixed(0)} zł</div>
          <div className={`text-xs mt-1 ${isCurrentMonth ? 'text-blue-200' : 'text-slate-300'}`}>Suma zarobków</div>
        </div>

        {/* Tons Tile */}
        <div className="bg-white rounded-2xl p-3 shadow-sm border border-slate-100">
           <div className="flex items-center gap-2 text-slate-400 mb-1 text-[10px] uppercase tracking-wide font-bold">
            <Truck size={12} /> Przewiezione
          </div>
          <div className="text-xl font-bold text-slate-700">{monthStats.tons.toFixed(0)} t</div>
          <div className="text-[10px] text-slate-400 mt-1">{monthStats.count} dni pracy</div>
        </div>

        {/* Vacation Tile - Always Annual Remaining */}
        <div className="bg-white rounded-2xl p-3 shadow-sm border border-slate-100">
           <div className="flex items-center gap-2 text-slate-400 mb-1 text-[10px] uppercase tracking-wide font-bold">
            <Palmtree size={12} /> Urlop (Rok)
          </div>
          <div className={`text-xl font-bold ${vacationStats.remaining < 5 ? 'text-orange-500' : 'text-slate-700'}`}>
             {vacationStats.remaining} dni
          </div>
          <div className="text-[10px] text-slate-400 mt-1">Pozostało w tym roku</div>
        </div>
      </div>

      {/* Scrollable Chart */}
      <div className="bg-white p-4 pb-2 rounded-xl shadow-sm border border-slate-100 h-72 flex flex-col">
          <h3 className="text-sm font-bold text-slate-500 mb-4 flex-none uppercase tracking-wide text-center">
            Wykres: {displayedMonthName}
          </h3>
          <div 
            className="flex-1 w-full min-h-0 overflow-x-auto overflow-y-hidden relative custom-scrollbar" 
            ref={scrollContainerRef}
            style={{ WebkitOverflowScrolling: 'touch' }} // Smooth scroll on iOS
          >
             <div style={{ width: `${chartWidth}px`, height: '100%' }}>
                <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={chartData} margin={{ top: 25, right: 10, left: -25, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                    <XAxis 
                        dataKey="name" 
                        fontSize={10} 
                        tickLine={false} 
                        axisLine={false} 
                        dy={10}
                        interval={0} // Show all ticks
                    />
                    <YAxis 
                        fontSize={10} 
                        axisLine={false} 
                        tickLine={false}
                        tickFormatter={(value) => `${value}`}
                    />
                    <Bar dataKey="zarobek" radius={[4, 4, 0, 0]} barSize={32}>
                        <LabelList 
                            dataKey="zarobek" 
                            position="top" 
                            fontSize={11} 
                            fontWeight="bold"
                            fill="#64748b"
                            formatter={(value: number) => value > 0 ? value : ''}
                        />
                        {chartData.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={getBarColor(entry.type, entry.isToday)} />
                        ))}
                    </Bar>
                    </BarChart>
                </ResponsiveContainer>
             </div>
          </div>
          <div className="text-[10px] text-center text-slate-300 mt-2 font-medium">
             Przesuń palcem, aby zobaczyć więcej dni
          </div>
      </div>

      {/* NEW DAY BUTTON */}
      {isCurrentMonth && (
          <button 
            onClick={() => onEditDay('')}
            className="w-full py-4 bg-primary text-white rounded-xl shadow-lg shadow-blue-200 flex flex-col items-center justify-center active:scale-98 transition-transform group"
          >
            <div className="flex items-center gap-2 mb-1">
                <PlusCircle size={28} className="group-hover:scale-110 transition-transform"/>
                <span className="text-lg font-bold uppercase tracking-wide">Dodaj NOWY dzień</span>
            </div>
            <span className="text-xs text-blue-100 opacity-80">Rozpocznij nowy wpis pracy, urlopu lub L4</span>
          </button>
      )}

      {/* History List */}
      <div>
        <h3 className="text-lg font-bold text-slate-800 mb-3">Historia: {displayedMonthName}</h3>

        <div className="space-y-3">
          {filteredHistory.length === 0 ? (
            <div className="text-center p-8 text-slate-400 bg-white rounded-xl border border-dashed border-slate-200">
                Brak wpisów w wybranym miesiącu.
            </div>
          ) : (
            filteredHistory.map(day => (
              <div 
                key={day.id} 
                onClick={() => onEditDay(day.id)}
                className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 active:scale-[0.98] transition-transform cursor-pointer relative"
              >
                <div className="flex justify-between items-start mb-2">
                  <div className="flex items-center gap-2">
                    <div className={`p-2 rounded-lg ${
                      day.type === DayType.WORK ? 'bg-blue-50 text-primary' : 
                      day.type === DayType.VACATION ? 'bg-yellow-50 text-yellow-600' :
                      day.type === DayType.SICK_LEAVE ? 'bg-purple-50 text-purple-600' : 
                      'bg-slate-100 text-slate-500'
                    }`}>
                      {day.type === DayType.WORK && <Briefcase size={18}/>}
                      {day.type === DayType.VACATION && <Calendar size={18}/>}
                      {day.type === DayType.SICK_LEAVE && <Thermometer size={18}/>}
                    </div>
                    <div>
                      <div className="font-bold text-slate-700">
                        {format(parseISO(day.date), 'd MMMM', { locale: pl })}
                      </div>
                      <div className="text-xs text-slate-400">
                        {day.type === DayType.WORK ? `${day.startTime} - ${day.endTime}` : day.type}
                      </div>
                    </div>
                  </div>
                  <div className="text-right">
                    {day.type === DayType.WORK ? (
                      <>
                        <div className="font-bold text-green-600">
                          +{(day.totalAmount + day.totalBonus + (day.totalHourlyBonus || 0) + (day.totalWorkshop || 0) + (day.totalWaiting || 0)).toFixed(2)} zł
                        </div>
                        <div className="text-xs text-slate-400">{day.trips.length} kursy</div>
                      </>
                    ) : (
                      <div className="text-xs font-medium px-2 py-1 bg-slate-100 rounded text-slate-500">
                        {day.type} (+{day.totalAmount} zł)
                      </div>
                    )}
                  </div>
                </div>

                {/* Mini preview of trips + workshop if work day */}
                {day.type === DayType.WORK && (
                  <>
                  <div className="mt-2 pt-2 border-t border-slate-50 text-xs text-slate-500 truncate flex flex-wrap gap-2">
                    {day.totalWorkshop && day.totalWorkshop > 0 ? (
                        <span className="flex items-center gap-1 text-orange-500 font-semibold"><Wrench size={12}/> Warsztat</span>
                    ) : null}
                    {day.totalWaiting && day.totalWaiting > 0 ? (
                        <span className="flex items-center gap-1 text-yellow-500 font-semibold"><Hourglass size={12}/> Oczekiwanie</span>
                    ) : null}
                    <span>{day.trips.map(t => t.locationName).join(', ')}</span>
                  </div>

                  {/* Add Another Trip Button - Only show if it's CURRENT month/recent for simplicity */}
                  {isCurrentMonth && (
                    <button 
                        onClick={(e) => {
                        e.stopPropagation();
                        onEditDay(day.id);
                        }}
                        className="w-full mt-3 py-2 bg-blue-50 text-blue-700 rounded-lg font-bold text-xs flex items-center justify-center gap-2 hover:bg-blue-100 transition-colors border border-blue-100"
                    >
                        <Plus size={14} />
                        Dodaj KOLEJNY kurs
                    </button>
                  )}
                  </>
                )}

                {/* Delete button (positioned absolute top right for better access) */}
                <button 
                  onClick={(e) => handleDelete(day.id, e)} 
                  className="absolute top-2 right-2 p-2 text-slate-300 hover:text-danger hover:bg-red-50 rounded-full transition-colors z-10"
                >
                  <Trash2 size={16}/>
                </button>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { Plus, Trash2, Save, ArrowLeft, Clock, Search, X, Wrench, Hourglass, Thermometer } from 'lucide-react';
import { WorkDay, DayType, LocationRate, Trip, AppSettings } from '../types';
import * as StorageService from '../services/storage';

interface DayEditorProps {
  dayId?: string | null;
  onClose: () => void;
}

const DayEditor: React.FC<DayEditorProps> = ({ dayId, onClose }) => {
  const [locations, setLocations] = useState<LocationRate[]>([]);
  const [settings, setSettings] = useState<AppSettings>(StorageService.getSettings());

  // Local UI states to keep inputs visible even if value is 0 during typing
  const [showWorkshop, setShowWorkshop] = useState(false);
  const [showWaiting, setShowWaiting] = useState(false);

  const [day, setDay] = useState<WorkDay>({
    id: uuidv4(),
    date: new Date().toISOString().slice(0, 10),
    type: DayType.WORK,
    startTime: '04:00',
    endTime: '04:00',
    trips: [],
    workshopHours: 0,
    totalWorkshop: 0,
    waitingHours: 0,
    waitingNote: '',
    totalWaiting: 0,
    totalAmount: 0,
    totalBonus: 0,
    totalHourlyBonus: 0,
    totalWeight: 0,
    note: ''
  });

  useEffect(() => {
    setLocations(StorageService.getLocations());
    setSettings(StorageService.getSettings());
    if (dayId) {
      const existingDay = StorageService.getDayById(dayId);
      if (existingDay) {
        setDay(existingDay);
        // Initialize toggles based on existing data
        setShowWorkshop((existingDay.workshopHours || 0) > 0);
        setShowWaiting((existingDay.waitingHours || 0) > 0);
      }
    } else {
        // Reset toggles for new day
        setShowWorkshop(false);
        setShowWaiting(false);
    }
  }, [dayId]);

  const handleTripChange = (tripId: string, field: keyof Trip, value: any) => {
    const updatedTrips = day.trips.map(trip => {
      if (trip.id !== tripId) return trip;

      const newTrip = { ...trip, [field]: value };

      // Auto-update rate if location changes
      if (field === 'locationId') {
        const loc = locations.find(l => l.id === value);
        if (loc) {
          newTrip.locationName = loc.name;
          newTrip.rate = loc.rate;

          // LOGIC CHANGE: If rate > 10, assume it's a fixed price per trip, not per ton.
          // Force weight/quantity to 1.
          if (loc.rate > 10) {
            newTrip.weight = 1;
          }
        }
      }

      // Recalculate amounts
      const { amount, bonus } = StorageService.calculateTrip(newTrip.weight, newTrip.rate);
      newTrip.amount = amount;
      newTrip.bonus = bonus;

      return newTrip;
    });

    setDay({ ...day, trips: updatedTrips });
  };

  const addTrip = () => {
    setDay({
      ...day,
      trips: [
        ...day.trips,
        {
          id: uuidv4(),
          locationId: '',
          locationName: '',
          weight: 0,
          rate: 0,
          amount: 0,
          bonus: 0
        }
      ]
    });
  };

  const removeTrip = (id: string) => {
    setDay({ ...day, trips: day.trips.filter(t => t.id !== id) });
  };

  const handleSave = () => {
    // Clean up values before saving if toggles are off
    const dayToSave = { ...day };
    if (!showWorkshop) {
        dayToSave.workshopHours = 0;
        dayToSave.totalWorkshop = 0;
    }
    if (!showWaiting) {
        dayToSave.waitingHours = 0;
        dayToSave.totalWaiting = 0;
        dayToSave.waitingNote = '';
    }

    StorageService.saveDay(dayToSave);
    onClose();
  };

  const toggleWorkshop = () => {
    const newState = !showWorkshop;
    setShowWorkshop(newState);
    if (newState) {
      setDay({ ...day, workshopHours: 1 }); // Default to 1h when enabled
    } else {
      setDay({ ...day, workshopHours: 0 });
    }
  };

  const toggleWaiting = () => {
    const newState = !showWaiting;
    setShowWaiting(newState);
    if (newState) {
      setDay({ ...day, waitingHours: 1 }); // Default to 1h when enabled
    } else {
      setDay({ ...day, waitingHours: 0, waitingNote: '' });
    }
  };

  // Live calculation for preview
  const totals = StorageService.calculateDayTotals(day);

  return (
    <div className="flex flex-col h-full bg-slate-50">
      {/* Header - Fixed Top */}
      <div className="bg-white border-b border-slate-200 p-4 flex items-center justify-between sticky top-0 z-20 shadow-sm flex-none">
        <button onClick={onClose} className="p-2 text-slate-600 hover:bg-slate-100 rounded-full">
          <ArrowLeft size={24} />
        </button>
        <h2 className="text-lg font-bold text-slate-800">
          {dayId ? 'Edycja Dnia' : 'Nowy Dzień'}
        </h2>
        <button 
          onClick={handleSave} 
          className="flex items-center gap-2 bg-primary text-white px-4 py-2 rounded-lg font-medium shadow hover:bg-blue-700 transition"
        >
          <Save size={18} />
          <span>Zapisz</span>
        </button>
      </div>

      {/* Scrollable Content */}
      <div className="flex-1 overflow-y-auto p-4 space-y-6">

        {/* Basic Info */}
        <section className="bg-white p-4 rounded-xl shadow-sm space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium text-slate-500 mb-1">Data</label>
              <input 
                type="date" 
                value={day.date} 
                onChange={e => setDay({...day, date: e.target.value})}
                className="w-full p-3 border border-slate-300 rounded-lg bg-gray-50 text-lg"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-500 mb-1">Typ dnia</label>
              <select 
                value={day.type} 
                onChange={e => setDay({...day, type: e.target.value as DayType})}
                className="w-full p-3 border border-slate-300 rounded-lg bg-gray-50 font-medium text-slate-700"
              >
                <option value={DayType.WORK}>Praca (Kursy)</option>
                <option value={DayType.VACATION}>Urlop</option>
                <option value={DayType.SICK_LEAVE}>L4 ({settings.sickLeaveRate} zł)</option>
              </select>
            </div>
          </div>

          {(day.type === DayType.WORK) && (
            <div className="grid grid-cols-2 gap-3 animate-fade-in">
              <div>
                <label className="block text-xs font-medium text-slate-500 mb-1">Start</label>
                <input 
                  type="time" 
                  value={day.startTime}
                  onChange={e => setDay({...day, startTime: e.target.value})}
                  className="w-full p-3 border border-slate-300 rounded-lg text-center bg-gray-50 text-lg"
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-500 mb-1">Koniec</label>
                <input 
                  type="time" 
                  value={day.endTime}
                  onChange={e => setDay({...day, endTime: e.target.value})}
                  className="w-full p-3 border border-slate-300 rounded-lg text-center bg-gray-50 text-lg"
                />
              </div>
            </div>
          )}
        </section>

        {/* Info Box for specific day types */}
        {day.type === DayType.VACATION && (
          <div className="bg-yellow-50 border border-yellow-200 p-4 rounded-xl text-yellow-800 text-sm flex items-center gap-2">
            <Clock size={18} />
            Stawka za urlop zostanie przeliczona automatycznie wg puli (Stary/Nowy).
          </div>
        )}

        {day.type === DayType.SICK_LEAVE && (
          <div className="bg-purple-50 border border-purple-200 p-4 rounded-xl text-purple-800 text-sm flex items-center gap-2">
            <Thermometer size={18} />
            Dla L4 naliczana jest stała stawka <strong>{settings.sickLeaveRate} PLN</strong>.
          </div>
        )}

        {/* Extra Options: Workshop & Waiting */}
        {day.type === DayType.WORK && (
          <section className="bg-white p-4 rounded-xl shadow-sm space-y-4">
             {/* Workshop Toggle */}
             <div>
                <label className="flex items-center gap-3 cursor-pointer">
                    <input 
                    type="checkbox" 
                    checked={showWorkshop}
                    onChange={toggleWorkshop}
                    className="w-5 h-5 text-blue-600 rounded focus:ring-blue-500"
                    />
                    <div className="flex items-center gap-2 text-slate-700 font-medium">
                    <Wrench size={18} className="text-slate-500" />
                    Warsztat / Naprawa ({settings.workshopRate} zł/h)
                    </div>
                </label>

                {showWorkshop && (
                    <div className="mt-2 pl-8 animate-fade-in">
                        <div className="flex items-center gap-2">
                            <input 
                            type="number"
                            step="0.5"
                            value={day.workshopHours === 0 ? '' : day.workshopHours}
                            placeholder="0"
                            onChange={e => {
                                const val = parseFloat(e.target.value);
                                setDay({...day, workshopHours: isNaN(val) ? 0 : val});
                            }}
                            className="w-24 p-2 border border-slate-300 rounded-lg text-center font-bold"
                            />
                            <span className="text-slate-500 font-medium">h = </span>
                            <span className="text-green-600 font-bold">{((day.workshopHours || 0) * settings.workshopRate).toFixed(2)} zł</span>
                        </div>
                    </div>
                )}
             </div>

             <hr className="border-slate-100" />

             {/* Waiting Toggle */}
             <div>
                <label className="flex items-center gap-3 cursor-pointer">
                    <input 
                    type="checkbox" 
                    checked={showWaiting}
                    onChange={toggleWaiting}
                    className="w-5 h-5 text-blue-600 rounded focus:ring-blue-500"
                    />
                    <div className="flex items-center gap-2 text-slate-700 font-medium">
                    <Hourglass size={18} className="text-slate-500" />
                    Oczekiwanie na załad./rozład. ({settings.waitingRate} zł/h)
                    </div>
                </label>

                {showWaiting && (
                    <div className="mt-2 pl-8 space-y-2 animate-fade-in">
                        <div className="flex items-center gap-2">
                            <input 
                            type="number"
                            step="0.5"
                            value={day.waitingHours === 0 ? '' : day.waitingHours}
                            placeholder="0"
                            onChange={e => {
                                const val = parseFloat(e.target.value);
                                setDay({...day, waitingHours: isNaN(val) ? 0 : val});
                            }}
                            className="w-24 p-2 border border-slate-300 rounded-lg text-center font-bold"
                            />
                            <span className="text-slate-500 font-medium">h = </span>
                            <span className="text-green-600 font-bold">{((day.waitingHours || 0) * settings.waitingRate).toFixed(2)} zł</span>
                        </div>
                        <input 
                           type="text"
                           placeholder="Gdzie stałem?"
                           value={day.waitingNote || ''}
                           onChange={e => setDay({...day, waitingNote: e.target.value})}
                           className="w-full p-2 border border-slate-300 rounded-lg text-sm bg-gray-50"
                        />
                    </div>
                )}
             </div>
          </section>
        )}

        {/* Trips Section */}
        {day.type === DayType.WORK && (
          <section className="space-y-4 animate-fade-in">
            <div className="flex justify-between items-center px-1">
              <h3 className="text-sm font-semibold text-slate-700 uppercase tracking-wider">Lista Kursów</h3>
            </div>

            {day.trips.map((trip) => (
              <TripCard 
                key={trip.id} 
                trip={trip} 
                locations={locations}
                onChange={(field, val) => handleTripChange(trip.id, field, val)}
                onRemove={() => removeTrip(trip.id)}
              />
            ))}

             {/* Big Add Button */}
             <button 
                onClick={addTrip}
                className="w-full py-4 rounded-xl bg-primary text-white text-lg font-bold shadow-md shadow-blue-200 flex items-center justify-center gap-2 active:scale-[0.98] transition-transform"
              >
                <Plus size={24} /> Dodaj kurs
              </button>
          </section>
        )}

        {/* Note */}
        <div className="bg-white p-4 rounded-xl shadow-sm">
           <label className="block text-xs font-medium text-slate-500 mb-1">Notatki / Tankowanie</label>
           <textarea 
             className="w-full p-2 border border-slate-300 rounded-lg bg-gray-50"
             rows={3}
             value={day.note}
             onChange={e => setDay({...day, note: e.target.value})}
             placeholder="Wpisz dodatkowe informacje..."
           />
        </div>

      </div>

      {/* Live Summary Footer - Fixed Block at bottom (not floating) */}
      <div className="bg-slate-800 text-white p-4 shadow-lg space-y-2 flex-none z-20">
           {day.type === DayType.WORK && (
             <>
             <div className="flex justify-between text-sm text-slate-300">
                <span>Tony: {totals.totalWeight.toFixed(2)} t</span>
                <span>Premia Paliwo (20%): {totals.totalBonus.toFixed(2)} zł</span>
             </div>
             <div className="flex justify-between text-sm text-slate-300">
                <span>Godziny: {(totals.totalHourlyBonus / settings.hourlyRate).toFixed(1)} h (+ {totals.totalHourlyBonus.toFixed(2)} zł)</span>
                {/* Simplified Extras display */}
                <div className="text-right">
                    {showWorkshop && totals.totalWorkshop > 0 ? (
                        <span className="block text-orange-300 text-xs">Warsztat: {totals.totalWorkshop.toFixed(2)} zł</span>
                    ) : null}
                    {showWaiting && totals.totalWaiting > 0 ? (
                        <span className="block text-yellow-300 text-xs">Oczekiwanie: {totals.totalWaiting.toFixed(2)} zł</span>
                    ) : null}
                </div>
             </div>
             </>
           )}
           <div className="flex justify-between items-end border-t border-slate-600 pt-2">
              <span className="text-slate-300">Zarobek całkowity:</span>
              <span className="text-2xl font-bold text-green-400">
                {(totals.totalAmount + totals.totalBonus + (totals.totalHourlyBonus || 0) + (totals.totalWorkshop || 0) + (totals.totalWaiting || 0)).toFixed(2)} zł
              </span>
           </div>
      </div>
    </div>
  );
};

// Sub-component for Trip Card to handle Search State efficiently
const TripCard: React.FC<{
  trip: Trip;
  locations: LocationRate[];
  onChange: (field: keyof Trip, value: any) => void;
  onRemove: () => void;
}> = ({ trip, locations, onChange, onRemove }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  // Initialize search term if trip has location
  useEffect(() => {
    if (trip.locationName && !isSearching) {
      setSearchTerm(trip.locationName);
    }
  }, [trip.locationName, isSearching]);

  const filteredLocations = locations.filter(l => 
    l.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelectLocation = (loc: LocationRate) => {
    setSearchTerm(loc.name);
    setIsSearching(false);
    onChange('locationId', loc.id);
  };

  const handleSearchFocus = () => {
    setIsSearching(true);
    setSearchTerm(''); // Clear to show all or let user type
    onChange('locationId', ''); // Clear current selection
  };

  // Check if fixed rate (lump sum)
  const isFixedRate = trip.rate > 10;

  return (
    <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 relative">
      <div className="grid grid-cols-12 gap-3">
