import React, { useState, useEffect } from 'react';
import { Truck, LogIn, Lock, AlertCircle, RefreshCw } from 'lucide-react';
import * as StorageService from '../services/storage';
import * as ApiService from '../services/api';

interface LoginProps {
    onLogin: () => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
    const [accessCode, setAccessCode] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    // On mount, ALWAYS try to sync drivers.
    // This fixes the iOS PWA issue where standalone app has empty storage 
    // and doesn't know about drivers added in Safari.
    useEffect(() => {
        syncDrivers();
    }, []);

    const syncDrivers = async () => {
        setIsLoading(true);
        setError('');

        // 1. Try to fetch from Cloud
        const fetchedDrivers = await ApiService.fetchDrivers();

        if (fetchedDrivers) {
            // Success: Update local storage
            StorageService.saveDrivers(fetchedDrivers, false);
        } else {
            // Failure: Check if we have anything locally
            const localDrivers = StorageService.getDrivers();
            if (localDrivers.length === 0) {
                 // Only show error if we have ABSOLUTELY no data to work with
                 // If we have local data (offline mode), we just stay silent
                 setError('Błąd połączenia z bazą Google. Sprawdź URL w services/api.ts');
            }
        }
        setIsLoading(false);
    };

    const handleLogin = () => {
        if (!accessCode) return;

        // Reload from storage to ensure we have latest after sync
        const drivers = StorageService.getDrivers();
        const foundDriver = drivers.find(d => d.code === accessCode.trim());

        if (foundDriver) {
            // Save current driver
            const settings = StorageService.getSettings();
            settings.driverId = foundDriver.id;
            StorageService.saveSettings(settings);

            onLogin();
        } else {
            setError('Nieprawidłowy kod');
            setAccessCode('');
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter') {
            handleLogin();
        }
    };

    return (
        <div className="flex flex-col items-center justify-center h-full p-6 bg-slate-50">
            <div className="bg-white p-8 rounded-2xl shadow-xl w-full max-w-sm space-y-6">
                <div className="text-center space-y-2">
                    <div className="bg-blue-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto text-primary mb-4 shadow-lg shadow-blue-100">
                        <Truck size={32} />
                    </div>
                    <h1 className="text-2xl font-black text-slate-800">KierowcaPRO</h1>
                    <p className="text-slate-500 text-sm">Wprowadź swój kod dostępu</p>
                </div>

                <div className="space-y-4">
                    <div className="relative">
                        <div className="absolute left-4 top-4 text-slate-400">
                            <Lock size={20} />
                        </div>
                        <input 
                            type="password" 
                            inputMode="numeric"
                            value={accessCode}
                            onChange={(e) => {
                                setAccessCode(e.target.value);
                                setError('');
                            }}
                            onKeyDown={handleKeyDown}
                            placeholder="KOD KIEROWCY"
                            className="w-full p-4 pl-12 bg-slate-50 border border-slate-200 rounded-xl font-bold text-xl text-center focus:ring-2 focus:ring-blue-500 outline-none text-slate-800 tracking-widest"
                        />
                    </div>

                    {error && (
                        <div className="flex items-center justify-center gap-2 text-red-600 text-xs font-bold bg-red-50 p-3 rounded-lg animate-fade-in border border-red-100">
                            <AlertCircle size={16} className="shrink-0"/> {error}
                        </div>
                    )}

                    <button 
                        onClick={handleLogin}
                        disabled={isLoading}
                        className="w-full bg-primary text-white py-4 rounded-xl font-bold shadow-lg shadow-blue-200 flex items-center justify-center gap-2 active:scale-[0.98] transition-transform disabled:opacity-70 disabled:scale-100"
                    >
                       <LogIn size={20} /> 
                       {isLoading ? 'Sprawdzanie...' : 'Zaloguj się'}
                    </button>

                    {/* Manual Sync Button */}
                    <button 
                        onClick={syncDrivers}
                        disabled={isLoading}
                        className="w-full py-2 text-slate-400 hover:text-slate-600 text-xs font-bold flex items-center justify-center gap-1 transition"
                    >
                         <RefreshCw size={12} className={isLoading ? "animate-spin" : ""} /> 
                         {isLoading ? 'Pobieranie bazy...' : 'Odśwież kody kierowców'}
                    </button>
                </div>
            </div>

            <div className="mt-8 text-center opacity-30">
                <p className="text-[10px] uppercase font-bold text-slate-500">Transkom System</p>
            </div>
        </div>
    );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { Trash2, Plus, User, Users, Key, RefreshCw, AlertCircle } from 'lucide-react';
import { Driver } from '../types';
import * as StorageService from '../services/storage';
import * as ApiService from '../services/api';

const DriversManager: React.FC = () => {
  const [drivers, setDrivers] = useState<Driver[]>([]);
  const [newDriverName, setNewDriverName] = useState('');
  const [newDriverCode, setNewDriverCode] = useState('');
  const [message, setMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    // CRITICAL FIX: Always fetch latest drivers from cloud when opening manager.
    // This prevents the "Overwrite" bug where an empty local app sends an empty list + 1 new driver,
    // deleting everyone else from the cloud.
    refreshDrivers();
  }, []);

  const refreshDrivers = async () => {
      setIsLoading(true);
      // 1. Load what we have locally instantly
      setDrivers(StorageService.getDrivers());

      // 2. Fetch from cloud
      const cloudDrivers = await ApiService.fetchDrivers();
      if (cloudDrivers) {
          StorageService.saveDrivers(cloudDrivers, false); // Update local, don't sync back yet
          setDrivers(cloudDrivers);
      }
      setIsLoading(false);
  };

  const handleAdd = async () => {
    if (!newDriverName.trim() || !newDriverCode.trim()) {
        setMessage('Wpisz imię i kod!');
        setTimeout(() => setMessage(''), 3000);
        return;
    }

    // Refresh one last time to be safe before writing
    // (Optimization: In a real app we might skip this, but here safety is priority)
    const currentDrivers = drivers; 

    // Check if code exists
    if (currentDrivers.some(d => d.code === newDriverCode.trim())) {
        setMessage('Ten kod jest już zajęty!');
        setTimeout(() => setMessage(''), 3000);
        return;
    }

    // Create a safe ID from name
    const id = newDriverName.trim().toUpperCase().replace(/\s+/g, '_');

    // Check if ID exists
    if (currentDrivers.some(d => d.id === id)) {
        setMessage('Taki kierowca już istnieje!');
        setTimeout(() => setMessage(''), 3000);
        return;
    }

    const updated = [...currentDrivers, { 
        id, 
        name: newDriverName.trim(), 
        code: newDriverCode.trim() 
    }];

    // Optimistic UI update
    setDrivers(updated);
    setNewDriverName('');
    setNewDriverCode('');
    setMessage('Dodawanie...');
    setIsLoading(true);

    // Save and Sync
    StorageService.saveDrivers(updated); // Sync is true by default here

    // Small delay to simulate network feeling
    setTimeout(() => {
        setMessage('Dodano kierowcę i wysłano do bazy');
        setIsLoading(false);
        setTimeout(() => setMessage(''), 3000);
    }, 500);
  };

  const handleDelete = (id: string) => {
    if (confirm('Czy na pewno usunąć kierowcę z listy dostępu? (Jego dane historii pozostaną w arkuszu Google)')) {
      const updated = drivers.filter(d => d.id !== id);
      StorageService.saveDrivers(updated);
      setDrivers(updated);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50">

      {/* Header */}
      <div className="bg-white p-4 shadow-sm border-b border-slate-200 z-10 flex-none flex justify-between items-center">
        <div>
            <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
            <Users size={20} className="text-primary"/> Baza Kierowców
            </h2>
            <p className="text-xs text-slate-500">Dodaj osoby i nadaj im kody logowania.</p>
        </div>
        <button 
            onClick={refreshDrivers} 
            disabled={isLoading}
            className="p-2 bg-slate-100 rounded-full text-slate-500 hover:text-blue-600 active:scale-95 transition"
        >
            <RefreshCw size={18} className={isLoading ? "animate-spin" : ""} />
        </button>
      </div>

      {/* Message Toast */}
      {message && (
        <div className="absolute top-20 left-4 right-4 z-50 p-3 bg-green-100 text-green-800 border border-green-200 rounded-lg text-center text-sm font-bold shadow-md animate-fade-in">
          {message}
        </div>
      )}

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">

        {/* Warning about empty list */}
        {!isLoading && drivers.length === 0 && (
            <div className="bg-orange-50 p-3 rounded-lg border border-orange-200 text-orange-800 text-xs flex items-start gap-2">
                <AlertCircle size={16} className="shrink-0 mt-0.5" />
                <div>
                    <strong>Lista jest pusta.</strong> Jeśli w bazie Google są kierowcy, spróbuj odświeżyć przyciskiem u góry przed dodaniem nowego, aby uniknąć nadpisania bazy.
                </div>
            </div>
        )}

        {/* Add Form */}
        <div className="bg-white p-4 rounded-xl border-2 border-blue-100 shadow-md space-y-3 relative">
            {isLoading && <div className="absolute inset-0 bg-white/50 z-10" />}
            <div>
                <label className="block text-xs font-semibold text-slate-500 mb-1">Imię i Nazwisko</label>
                <input 
                  type="text" 
                  placeholder="Np. Jan Kowalski" 
                  value={newDriverName}
                  onChange={e => setNewDriverName(e.target.value)}
                  className="w-full p-3 rounded-lg border border-slate-300 focus:ring-2 focus:ring-blue-500 outline-none bg-slate-50"
                />
            </div>

            <div className="flex gap-2 items-end">
                <div className="flex-1">
                    <label className="block text-xs font-semibold text-slate-500 mb-1">Kod Logowania (PIN)</label>
                    <input 
                      type="text" 
                      placeholder="Np. 1234" 
                      value={newDriverCode}
                      onChange={e => setNewDriverCode(e.target.value)}
                      className="w-full p-3 rounded-lg border border-slate-300 focus:ring-2 focus:ring-blue-500 outline-none bg-slate-50 font-mono tracking-widest font-bold"
                    />
                </div>
                <button 
                  onClick={handleAdd}
                  disabled={isLoading}
                  className="bg-blue-600 text-white h-[50px] px-6 rounded-lg font-bold hover:bg-blue-700 transition flex items-center shadow-sm disabled:opacity-50"
                >
                  <Plus size={24} />
                </button>
            </div>
        </div>

        {/* List */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
          {drivers.length === 0 ? (
            <div className="p-10 text-center text-slate-400">
                {isLoading ? 'Pobieranie listy...' : 'Brak kierowców.'}
            </div>
          ) : (
            <ul className="divide-y divide-slate-100">
              {drivers.map(d => (
                <li key={d.id} className="p-3 pl-4 flex justify-between items-center hover:bg-slate-50 transition-colors">
                  <div className="flex items-center gap-3">
                    <div className="bg-slate-100 p-2 rounded-full text-slate-500">
                        <User size={18} />
                    </div>
                    <div>
                        <div className="font-semibold text-slate-800 text-sm">{d.name}</div>
                        <div className="flex items-center gap-1 text-[10px] text-slate-400 font-mono">
                            <Key size={10} /> Kod: <span className="font-bold text-slate-600 bg-slate-100 px-1 rounded">{d.code}</span>
                        </div>
                    </div>
                  </div>
                  <button 
                    onClick={() => handleDelete(d.id)} 
                    className="p-2 text-slate-300 hover:text-danger hover:bg-red-50 rounded-lg transition"
                  >
                    <Trash2 size={18} />
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </div>
  );
};

export default DriversManager;

import React, { useState, useEffect } from 'react';
import { X, Share, PlusSquare, Download, Phone } from 'lucide-react';

const InstallPrompt: React.FC = () => {
  const [showPrompt, setShowPrompt] = useState(false);
  const [isIOS, setIsIOS] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    // 1. Check if already installed (Standalone mode)
    const isStandalone = window.matchMedia('(display-mode: standalone)').matches || (window.navigator as any).standalone;
    if (isStandalone) {
        console.log("App is running in standalone mode (installed).");
        return;
    }

    // 2. Check if user dismissed it previously
    const hasSeenPrompt = localStorage.getItem('kierowcapro_install_seen');
    if (hasSeenPrompt) {
        console.log("User previously dismissed install prompt.");
        return;
    }

    // 3. Detect iOS (Improved for iPad)
    const userAgent = window.navigator.userAgent.toLowerCase();
    const isIosDevice = /iphone|ipad|ipod/.test(userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
    setIsIOS(isIosDevice);

    // 4. Capture native install event (Android/Desktop)
    window.addEventListener('beforeinstallprompt', (e) => {
      console.log("beforeinstallprompt event fired!");
      e.preventDefault();
      setDeferredPrompt(e);
      setShowPrompt(true);
    });

    // If iOS, show prompt immediately (since no beforeinstallprompt event exists there)
    if (isIosDevice) {
        console.log("iOS detected, scheduling prompt.");
        // Slight delay for better UX
        setTimeout(() => setShowPrompt(true), 2000);
    }
  }, []);

  const handleDismiss = () => {
    setShowPrompt(false);
    localStorage.setItem('kierowcapro_install_seen', 'true');
  };

  const handleInstallClick = async () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') {
        setDeferredPrompt(null);
        setShowPrompt(false);
      }
    }
  };

  if (!showPrompt) return null;

  return (
    <div className="fixed inset-0 z-[100] bg-slate-900/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-4 animate-fade-in">
      <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden relative animate-slide-up sm:animate-none">

        {/* Header */}
        <div className="bg-primary p-4 text-white flex justify-between items-start">
            <div className="flex items-center gap-3">
                <div className="bg-white/20 p-2 rounded-lg">
                    <Download size={24} />
                </div>
                <div>
                    <h3 className="font-bold text-lg">Zainstaluj aplikację</h3>
                    <p className="text-blue-100 text-xs">Działa offline i bez paska adresu</p>
                </div>
            </div>
            <button 
                onClick={handleDismiss}
                className="text-blue-200 hover:text-white p-1"
            >
                <X size={24} />
            </button>
        </div>

        {/* Content */}
        <div className="p-6 space-y-6">

            {isIOS ? (
                // iOS Instructions
                <div className="space-y-4">
                    <p className="text-slate-600 text-sm">
                        Aby zainstalować aplikację na iPhone/iPad, wykonaj te 2 proste kroki:
                    </p>

                    <div className="flex items-start gap-4 p-3 bg-slate-50 rounded-xl border border-slate-100">
                        <div className="text-blue-500 mt-1">
                            <Share size={24} />
                        </div>
                        <div>
                            <span className="block font-bold text-slate-800 text-sm mb-1">Krok 1</span>
                            <p className="text-xs text-slate-500">
                                Kliknij ikonę <span className="font-bold">Udostępnij</span> na dolnym pasku przeglądarki Safari.
                            </p>
                        </div>
                    </div>

                    <div className="flex items-start gap-4 p-3 bg-slate-50 rounded-xl border border-slate-100">
                        <div className="text-slate-700 mt-1">
                            <PlusSquare size={24} />
                        </div>
                        <div>
                            <span className="block font-bold text-slate-800 text-sm mb-1">Krok 2</span>
                            <p className="text-xs text-slate-500">
                                Przewiń listę w dół i wybierz opcję <span className="font-bold">Do ekranu początkowego</span>.
                            </p>
                        </div>
                    </div>
                </div>
            ) : (
                // Android / Other Instructions
                <div className="text-center space-y-4">
                    <p className="text-slate-600 text-sm">
                        Zainstaluj aplikację, aby mieć do niej szybki dostęp prosto z pulpitu i korzystać z niej nawet bez internetu.
                    </p>
                    <button 
                        onClick={handleInstallClick}
                        className="w-full bg-primary text-white py-3 rounded-xl font-bold shadow-lg shadow-blue-200 active:scale-95 transition-transform flex items-center justify-center gap-2"
                    >
                        <Download size={20} /> Zainstaluj teraz
                    </button>
                </div>
            )}

            <button 
                onClick={handleDismiss}
                className="w-full text-slate-400 text-xs font-medium hover:text-slate-600 py-2"
            >
                Nie teraz, będę używać w przeglądarce
            </button>
        </div>
      </div>
    </div>
  );
};

