    try {
        const locRef = doc(db, "config", "locations");
        const docSnap = await getDoc(locRef);
        if (docSnap.exists()) {
            return JSON.parse(docSnap.data().data);
        }
    } catch (e) {
        console.error("Błąd pobierania miejscowości z Firebase:", e);
    }
    return [];
};

// --- SYNCHRONIZACJA KIEROWCÓW ---
export const syncDrivers = async (drivers: Driver[]) => {
    if (!isFirebaseConfigured()) return;
    try {
        const driversRef = doc(db, "config", "drivers");
        await setDoc(driversRef, { 
            data: JSON.stringify(drivers),
            updatedAt: new Date().toISOString()
        });
    } catch (e) {
        console.error("Błąd zapisu kierowców w Firebase:", e);
    }
};

export const fetchDrivers = async (): Promise<Driver[]> => {
    if (!isFirebaseConfigured()) return [];
    try {
        const driversRef = doc(db, "config", "drivers");
        const docSnap = await getDoc(driversRef);
        if (docSnap.exists()) {
            return JSON.parse(docSnap.data().data);
        }
    } catch (e) {
        console.error("Błąd pobierania kierowców z Firebase:", e);
    }
    return [];
};

import { useState, useEffect } from 'react';
import { Truck, LogIn, Lock, AlertCircle, RefreshCw, Database } from 'lucide-react';
import * as StorageService from '../services/storage';
import * as ApiService from '../services/api';

interface LoginProps {
    onLogin: () => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
    const [accessCode, setAccessCode] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    useEffect(() => {
        syncDrivers();
    }, []);

    const syncDrivers = async () => {
        if (!ApiService.isFirebaseConfigured()) {
            setError('Błąd konfiguracji Firebase w pliku services/api.ts');
            return;
        }

        setIsLoading(true);
        setError('');

        try {
            const fetchedDrivers = await ApiService.fetchDrivers();
            if (fetchedDrivers && fetchedDrivers.length > 0) {
                StorageService.saveDrivers(fetchedDrivers, false);
            } else {
                // Jeśli baza jest pusta, sprawdź czy mamy kogoś lokalnie
                const localDrivers = StorageService.getDrivers();
                if (localDrivers.length === 0) {
                     setError('Baza kierowców jest pusta. Dodaj kierowców w Panelu Admina.');
                }
            }
        } catch (e) {
            setError('Błąd połączenia z bazą danych Firebase. Sprawdź internet.');
        } finally {
            setIsLoading(false);
        }
    };

    const handleLogin = () => {
        if (!accessCode) return;

        const drivers = StorageService.getDrivers();
        const foundDriver = drivers.find(d => d.code === accessCode.trim());

        if (foundDriver) {
            const settings = StorageService.getSettings();
            settings.driverId = foundDriver.id;
            StorageService.saveSettings(settings);
            onLogin();
        } else {
            setError('Nieprawidłowy kod kierowcy');
            setAccessCode('');
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter') {
            handleLogin();
        }
    };

    return (
        <div className="flex flex-col items-center justify-center h-full p-6 bg-slate-50">
            <div className="bg-white p-8 rounded-2xl shadow-xl w-full max-w-sm space-y-6">
                <div className="text-center space-y-2">
                    <div className="bg-blue-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto text-primary mb-4 shadow-lg shadow-blue-100">
                        <Truck size={32} />
                    </div>
                    <h1 className="text-2xl font-black text-slate-800">Transkom</h1>
                    <p className="text-slate-500 text-sm">Wprowadź kod kierowcy</p>
                </div>

                <div className="space-y-4">
                    <div className="relative">
                        <div className="absolute left-4 top-4 text-slate-400">
                            <Lock size={20} />
                        </div>
                        <input 
                            type="password" 
                            inputMode="numeric"
                            value={accessCode}
                            onChange={(e) => {
                                setAccessCode(e.target.value);
                                setError('');
                            }}
                            onKeyDown={handleKeyDown}
                            placeholder="KOD PIN"
                            className="w-full p-4 pl-12 bg-slate-50 border border-slate-200 rounded-xl font-bold text-xl text-center focus:ring-2 focus:ring-blue-500 outline-none text-slate-800 tracking-widest"
                        />
                    </div>

                    {error && (
                        <div className="flex items-center justify-center gap-2 text-red-600 text-[10px] font-bold bg-red-50 p-3 rounded-lg animate-fade-in border border-red-100 leading-tight">
                            <AlertCircle size={14} className="shrink-0"/> {error}
                        </div>
                    )}

                    <button 
                        onClick={handleLogin}
                        disabled={isLoading}
                        className="w-full bg-primary text-white py-4 rounded-xl font-bold shadow-lg shadow-blue-200 flex items-center justify-center gap-2 active:scale-[0.98] transition-transform disabled:opacity-70 disabled:scale-100"
                    >
                       <LogIn size={20} /> 
                       {isLoading ? 'Łączenie...' : 'Zaloguj się'}
                    </button>

                    <button 
                        onClick={syncDrivers}
                        disabled={isLoading}
                        className="w-full py-2 text-slate-400 hover:text-slate-600 text-[10px] font-bold flex items-center justify-center gap-1 transition uppercase tracking-wider"
                    >
                         <RefreshCw size={12} className={isLoading ? "animate-spin" : ""} /> 
                         {isLoading ? 'Pobieranie...' : 'Odśwież kody z chmury'}
                    </button>
                </div>
            </div>

            <div className="mt-8 text-center opacity-30 flex items-center gap-2">
                <Database size={12} />
                <p className="text-[10px] uppercase font-bold text-slate-500 tracking-widest">Firebase Cloud Storage</p>
            </div>
        </div>
    );
};

export default Login;

import { useState } from 'react';
import { Save, Settings as SettingsIcon, Lock, Cloud, LogOut, RefreshCw, Info } from 'lucide-react';
import * as StorageService from '../services/storage';
import * as ApiService from '../services/api';
import { AppSettings } from '../types';

interface SettingsProps {
    onOpenAdmin: () => void;
    onLogout: () => void;
}

const Settings: React.FC<SettingsProps> = ({ onOpenAdmin, onLogout }) => {
  const [settings, setSettings] = useState<AppSettings>(StorageService.getSettings());
  const [message, setMessage] = useState('');

  const handleSave = () => {
    StorageService.saveSettings(settings);
    setMessage('Ustawienia zapisane!');
    setTimeout(() => setMessage(''), 3000);
  };

  const handleChange = (key: keyof AppSettings, value: string) => {
    const numValue = parseFloat(value);
    setSettings(prev => ({
      ...prev,
      [key]: isNaN(numValue) ? 0 : numValue
    }));
  };

  const handleGlobalRateRefresh = () => {
    if (confirm("Zaktualizować stawki w kursach z 2 ostatnich miesięcy?")) {
        const count = StorageService.updateRecentHistoryRates();
        setMessage(count > 0 ? `Zaktualizowano ${count} dni!` : 'Kursy są już aktualne.');
        setTimeout(() => setMessage(''), 3000);
    }
  };

  const isConnected = ApiService.isFirebaseConfigured();
  const oldVacationDays = Math.max(0, settings.totalVacationDays - settings.vacationDaysLimit);

  return (
    <div className="flex flex-col h-full bg-slate-50">
      <div className="bg-white p-4 shadow-sm border-b border-slate-200 z-10 flex-none flex justify-between items-center">
         <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
           <SettingsIcon size={20} className="text-primary"/> Opcje i Stawki
         </h2>
         <button onClick={onOpenAdmin} className="p-2 text-slate-400 hover:text-slate-800 rounded-full transition">
            <Lock size={20} />
         </button>
      </div>

      {message && (
        <div className="absolute top-20 left-4 right-4 z-50 p-3 bg-green-100 text-green-800 border border-green-200 rounded-lg text-center text-sm font-bold shadow-md animate-fade-in">
          {message}
        </div>
      )}

      <div className="flex-1 overflow-y-auto p-4 space-y-6">

        {/* Connection Info */}
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
            <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-bold text-slate-400 uppercase">Status połączenia</span>
                {isConnected ? (
                    <span className="text-[10px] bg-green-100 text-green-700 px-2 py-0.5 rounded font-bold flex items-center gap-1">
                        <Cloud size={10} /> Chmura Aktywna
                    </span>
                ) : (
                    <span className="text-[10px] bg-red-100 text-red-700 px-2 py-0.5 rounded font-bold flex items-center gap-1">
                        <Cloud size={10} /> Brak Konfiguracji
                    </span>
                )}
            </div>
            <div className="flex items-center justify-between">
                <div className="font-bold text-lg text-slate-800">Kierowca: {settings.driverId || 'Niezalogowany'}</div>
                <button onClick={onLogout} className="text-red-500 p-2 rounded-lg hover:bg-red-50 transition">
                    <LogOut size={20} />
                </button>
            </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 space-y-4">
           <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest border-b border-slate-50 pb-2">Narzędzia</h3>
           <button onClick={handleGlobalRateRefresh} className="w-full flex items-center justify-between p-3 bg-indigo-50 rounded-xl border border-indigo-100 text-indigo-700 group">
               <div className="text-left">
                   <div className="font-bold text-sm">Synchronizuj Stawki</div>
                   <div className="text-[10px] opacity-70">Aktualizuje ceny w starych kursach</div>
               </div>
               <RefreshCw size={20} className="group-active:rotate-180 transition-transform duration-500" />
           </button>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 space-y-4">
           <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest border-b border-slate-50 pb-2">Urlopy</h3>
           <div className="bg-blue-50 p-3 rounded-lg text-[11px] text-blue-800 flex flex-col gap-1 border border-blue-100">
              <div className="font-bold flex items-center gap-2 uppercase tracking-tighter"><Info size={14}/> Twoja pula urlopowa:</div>
              <div>Z {settings.totalVacationDays} dni: <strong>{oldVacationDays} dni</strong> (stara stawka) i <strong>{settings.vacationDaysLimit} dni</strong> (nowa stawka).</div>
           </div>
           <div className="grid grid-cols-2 gap-4">
               <div className="col-span-2">
                    <label className="block text-xs font-medium text-slate-500 mb-1">Całkowite dni urlopu</label>
                    <input type="number" value={settings.totalVacationDays} onChange={(e) => handleChange('totalVacationDays', e.target.value)} className="w-full p-3 border border-slate-200 rounded-lg bg-slate-50 font-bold" />
               </div>
               <div>
                    <label className="block text-xs font-medium text-slate-500 mb-1">Stary Urlop (zł)</label>
                    <input type="number" value={settings.vacationRateOld} onChange={(e) => handleChange('vacationRateOld', e.target.value)} className="w-full p-3 border border-slate-200 rounded-lg bg-slate-50" />
               </div>
               <div>
                    <label className="block text-xs font-medium text-slate-500 mb-1">Nowy Urlop (zł)</label>
                    <input type="number" value={settings.vacationRateNew} onChange={(e) => handleChange('vacationRateNew', e.target.value)} className="w-full p-3 border border-slate-200 rounded-lg bg-slate-50" />
               </div>
           </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 space-y-4">
           <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest border-b border-slate-50 pb-2">Inne Stawki</h3>
           <div className="grid grid-cols-2 gap-4">
               <div>
                    <label className="block text-xs font-medium text-slate-500 mb-1">L4 (zł)</label>
                    <input type="number" value={settings.sickLeaveRate} onChange={(e) => handleChange('sickLeaveRate', e.target.value)} className="w-full p-3 border border-slate-200 rounded-lg bg-slate-50" />
               </div>
               <div>
                    <label className="block text-xs font-medium text-slate-500 mb-1">Godzinowa (zł/h)</label>
                    <input type="number" step="0.5" value={settings.hourlyRate} onChange={(e) => handleChange('hourlyRate', e.target.value)} className="w-full p-3 border border-slate-200 rounded-lg bg-slate-50" />
               </div>
               <div>
                    <label className="block text-xs font-medium text-slate-500 mb-1">Warsztat (zł/h)</label>
                    <input type="number" value={settings.workshopRate} onChange={(e) => handleChange('workshopRate', e.target.value)} className="w-full p-3 border border-slate-200 rounded-lg bg-slate-50" />
               </div>
               <div>
                    <label className="block text-xs font-medium text-slate-500 mb-1">Postój (zł/h)</label>
                    <input type="number" value={settings.waitingRate} onChange={(e) => handleChange('waitingRate', e.target.value)} className="w-full p-3 border border-slate-200 rounded-lg bg-slate-50" />
               </div>
           </div>
        </div>

        <button onClick={handleSave} className="w-full bg-primary text-white py-4 rounded-xl flex items-center justify-center gap-2 font-bold shadow-lg shadow-blue-100 active:scale-95 transition-transform">
            <Save size={20} /> Zapisz Ustawienia
        </button>

      </div>
    </div>
  );
};

export default Settings;

import { useState, useEffect } from 'react';
import { Home, PlusCircle, Settings as SettingsIcon, MapPin, FileText } from 'lucide-react';
import Dashboard from './components/Dashboard';
import DayEditor from './components/DayEditor';
import LocationsManager from './components/LocationsManager';
import MonthlySummary from './components/MonthlySummary';
import Settings from './components/Settings';
import Login from './components/Login';
import AdminPanel from './components/AdminPanel';
import InstallPrompt from './components/InstallPrompt';
import * as StorageService from './services/storage';
import * as ApiService from './services/api';

enum View {
  DASHBOARD = 'DASHBOARD',
  EDITOR = 'EDITOR',
  LOCATIONS = 'LOCATIONS',
  SUMMARY = 'SUMMARY',
  SETTINGS = 'SETTINGS'
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [editingDayId, setEditingDayId] = useState<string | null>(null);
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [showAdmin, setShowAdmin] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    const settings = StorageService.getSettings();
    if (settings.driverId) {
      setIsLoggedIn(true);
      initializeData(settings.driverId);
    }
  }, []);

  const initializeData = async (driverId: string) => {
    setIsLoading(true);
    try {
        // Pobierz lokalizacje z chmury
        const locations = await ApiService.fetchLocations();
        if (locations && locations.length > 0) {
            StorageService.saveLocations(locations, false);
        }

        // Pobierz dni pracy kierowcy
        const days = await ApiService.fetchDriverData(driverId);
        if (days && days.length > 0) {
            StorageService.saveWorkDays(days);
            setRefreshTrigger(prev => prev + 1);
        }
    } catch (e) {
        console.warn("Błąd inicjalizacji danych z chmury. Używam danych lokalnych.");
    } finally {
        setIsLoading(false);
    }
  };

  const handleLogin = () => {
    const settings = StorageService.getSettings();
    setIsLoggedIn(true);
    if (settings.driverId) {
        initializeData(settings.driverId);
    }
  };

  const handleLogout = () => {
    if (confirm("Czy na pewno chcesz się wylogować?")) {
        const settings = StorageService.getSettings();
        settings.driverId = undefined;
        StorageService.saveSettings(settings);
        setIsLoggedIn(false);
    }
  };

  const handleOpenEditor = (dayId?: string) => {
    setEditingDayId(dayId || null);
    setCurrentView(View.EDITOR);
  };

  const handleCloseEditor = () => {
    setCurrentView(View.DASHBOARD);
    setEditingDayId(null);
    setRefreshTrigger(prev => prev + 1);
  };

  if (!isLoggedIn) {
    return (
        <>
            <Login onLogin={handleLogin} />
            <InstallPrompt />
        </>
    );
  }

  return (
    <div className="h-[100dvh] w-full flex flex-col bg-slate-50 text-slate-900 font-sans overflow-hidden relative">
      <InstallPrompt />

      {isLoading && (
        <div className="absolute inset-0 z-[60] bg-white/80 backdrop-blur-sm flex items-center justify-center">
            <div className="flex flex-col items-center gap-4">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
                <p className="text-xs font-bold text-slate-500 animate-pulse uppercase tracking-widest">Synchronizacja z Firebase...</p>
            </div>
        </div>
      )}

      {showAdmin && (
          <AdminPanel onClose={() => setShowAdmin(false)} />
      )}

      <main className="flex-1 overflow-hidden relative flex flex-col min-h-0">
        {currentView === View.DASHBOARD && (
          <div className="flex-1 overflow-y-auto min-h-0">
            <Dashboard onEditDay={handleOpenEditor} refreshTrigger={refreshTrigger} />
          </div>
        )}
        {currentView === View.EDITOR && (
          <div className="absolute inset-0 z-50 bg-white">
            <DayEditor dayId={editingDayId} onClose={handleCloseEditor} />
          </div>
        )}
        {currentView === View.LOCATIONS && (
          <div className="flex-1 overflow-hidden">
             <LocationsManager mode="DRIVER" />
          </div>
        )}
        {currentView === View.SUMMARY && (
          <MonthlySummary />
        )}
        {currentView === View.SETTINGS && (
          <Settings onOpenAdmin={() => setShowAdmin(true)} onLogout={handleLogout} />
        )}
      </main>

      {currentView !== View.EDITOR && (
        <nav className="h-20 bg-white border-t border-slate-200 flex justify-around items-center px-2 pb-2 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-40 flex-none">
          <button 
            onClick={() => setCurrentView(View.DASHBOARD)}
            className={`flex flex-col items-center p-2 rounded-xl transition ${currentView === View.DASHBOARD ? 'text-primary bg-blue-50' : 'text-slate-400'}`}
          >
            <Home size={24} />
            <span className="text-[10px] font-medium mt-1">Start</span>
          </button>

          <button 
             onClick={() => setCurrentView(View.SUMMARY)}
             className={`flex flex-col items-center p-2 rounded-xl transition ${currentView === View.SUMMARY ? 'text-primary bg-blue-50' : 'text-slate-400'}`}
          >
            <FileText size={24} />
            <span className="text-[10px] font-medium mt-1">Raport</span>
          </button>

          <button 
            onClick={() => setCurrentView(View.LOCATIONS)}
            className={`flex flex-col items-center p-2 rounded-xl transition ${currentView === View.LOCATIONS ? 'text-primary bg-blue-50' : 'text-slate-400'}`}
          >
            <MapPin size={24} />
            <span className="text-[10px] font-medium mt-1">Baza</span>
          </button>

          <button 
            onClick={() => setCurrentView(View.SETTINGS)}
            className={`flex flex-col items-center p-2 rounded-xl transition ${currentView === View.SETTINGS ? 'text-primary bg-blue-50' : 'text-slate-400'}`}
          >
            <SettingsIcon size={24} />
            <span className="text-[10px] font-medium mt-1">Opcje</span>
          </button>
        </nav>
      )}
    </div>
  );
};

export default App;

