import { Truck, LogIn, Lock, AlertCircle, RefreshCw, Database } from 'lucide-react';
import * as StorageService from '../services/storage';
import * as ApiService from '../services/api';

interface LoginProps {
    onLogin: () => void;
    onOpenAdmin: () => void;
}

