// --- SYNCHRONIZACJA KURSÓW KIEROWCY ---
export const syncDriverData = async (driverId: string, days: WorkDay[]) => {
    if (!isFirebaseConfigured() || !driverId) return;

    try {
        console.log(`Firebase: Próba zapisu dla ${driverId}...`);
        const driverRef = doc(db, "driverData", driverId);

        // Czekamy na pełne zakończenie zapisu
        await setDoc(driverRef, { 
            days: JSON.stringify(days),
            lastSync: new Date().toISOString(),
            driverId: driverId
        }, { merge: true });

        console.log("Firebase: Zapis zakończony sukcesem.");
        return true;
    } catch (e) {
        console.error("Firebase: Błąd zapisu:", e);
        throw e;
    }
};

export const fetchDriverData = async (driverId: string): Promise<WorkDay[]> => {
    if (!isFirebaseConfigured() || !driverId) return [];

    try {
        console.log(`Firebase: Pobieranie danych dla ${driverId}...`);
        const driverRef = doc(db, "driverData", driverId);
        const docSnap = await getDoc(driverRef);

        if (docSnap.exists()) {
            const data = docSnap.data();
            return data.days ? JSON.parse(data.days) : [];
        }
        return [];
    } catch (e) {
        console.error("Firebase: Błąd pobierania:", e);
        throw e;
    }
};

