/**
 * Import data from a JSON file and update local storage.
 */
export const importData = async (file: File): Promise<boolean> => {
  try {
    const text = await file.text();
    const data = JSON.parse(text);

    // Update local storage without immediate cloud sync to avoid flooding
    if (data.days) saveWorkDays(data.days, false);
    if (data.locations) saveLocations(data.locations, false);
    if (data.drivers) saveDrivers(data.drivers, false);
    if (data.settings) saveSettings(data.settings);

    return true;
  } catch (error) {
    console.error("Import error:", error);
    return false;
  }
};

