  const getBarColor = (type?: DayType, isToday?: boolean) => {
      if (isToday) return '#f59e0b';
      if (type === DayType.VACATION) return '#16a34a';
      if (type === DayType.SICK_LEAVE) return '#dc2626';
      if (type === DayType.WORK) return '#2563eb';
      return '#e2e8f0';
