          <div className="overflow-x-auto pb-2 -mx-2 px-2">
            <div style={{ width: `${chartWidth}px`, height: '240px' }}>
                <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={chartData} margin={{ top: 20, right: 10, left: -25, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                    <XAxis dataKey="name" fontSize={11} tickLine={false} axisLine={false} dy={10} interval={0} />
                    <YAxis fontSize={10} axisLine={false} tickLine={false} />
                    <Bar dataKey="zarobek" radius={[6, 6, 0, 0]} barSize={36}>
