// --- SYNCHRONIZACJA KURSÓW KIEROWCY (INDYWIDUALNE DOKUMENTY) ---

/**
 * Zapisuje pojedynczy dzień do podkolekcji 'days'.
 */
export const syncSingleDay = async (driverId: string, day: WorkDay) => {
    if (!isFirebaseConfigured() || !driverId) return false;
    try {
        const dayRef = doc(db, "driverData", driverId, "days", day.id);
        await setDoc(dayRef, day, { merge: true });

        // Aktualizujemy też timestamp ostatniej zmiany w głównym dokumencie kierowcy
        const driverRef = doc(db, "driverData", driverId);
        await setDoc(driverRef, { lastSync: new Date().toISOString() }, { merge: true });

        return true;
    } catch (e) {
        console.error("Firebase: Błąd zapisu dnia:", e);
        throw e;
    }
};

/**
 * Usuwa pojedynczy dzień z podkolekcji 'days'.
 */
export const deleteRemoteDay = async (driverId: string, dayId: string) => {
    if (!isFirebaseConfigured() || !driverId) return false;
    try {
        const dayRef = doc(db, "driverData", driverId, "days", dayId);
        await deleteDoc(dayRef);
        return true;
    } catch (e) {
        console.error("Firebase: Błąd usuwania dnia:", e);
        throw e;
    }
};

/**
 * Masowa synchronizacja (używana przy imporcie lub pełnym odświeżeniu).
 * Firestore batch ma limit 500 operacji.
 */
export const syncDriverData = async (driverId: string, days: WorkDay[]) => {
    if (!isFirebaseConfigured() || !driverId) return false;

    try {
        console.log(`Firebase: Masowa synchronizacja ${days.length} dni dla ${driverId}...`);

        // Batch pozwala na wykonanie wielu operacji w jednym zapytaniu sieciowym
        const batch = writeBatch(db);

        days.forEach(day => {
            const dayRef = doc(db, "driverData", driverId, "days", day.id);
            batch.set(dayRef, day, { merge: true });
        });

        const driverRef = doc(db, "driverData", driverId);
        batch.set(driverRef, { lastSync: new Date().toISOString(), driverId }, { merge: true });

        await batch.commit();
        console.log("Firebase: Masowy zapis zakończony sukcesem.");
        return true;
    } catch (e) {
        console.error("Firebase: Błąd masowego zapisu:", e);
        throw e;
    }
};

/**
 * Pobiera wszystkie dni z podkolekcji 'days' i sortuje je po dacie.
 */
export const fetchDriverData = async (driverId: string): Promise<WorkDay[]> => {
    if (!isFirebaseConfigured() || !driverId) return [];

    try {
        console.log(`Firebase: Pobieranie kolekcji dni dla ${driverId}...`);
        const daysCol = collection(db, "driverData", driverId, "days");
        const q = query(daysCol, orderBy("date", "desc"));
        const snapshot = await getDocs(q);

        const days: WorkDay[] = [];
        snapshot.forEach(doc => {
            days.push(doc.data() as WorkDay);
        });

        console.log(`Firebase: Pobrano ${days.length} indywidualnych dokumentów dni.`);
        return days;
    } catch (e) {
        console.error("Firebase: Błąd pobierania kolekcji:", e);
        throw e;
    }
};

