import React, { useEffect, useState } from 'react';
import { format, parseISO } from 'date-fns';
import { pl } from 'date-fns/locale';
import { TrendingUp, Calendar, Briefcase, Truck, Wrench, Hourglass, Plus, PlusCircle, Thermometer, Palmtree, Trash2, Moon, RefreshCw, CloudCheck, CloudOff, User } from 'lucide-react';
import { WorkDay, DayType, Driver } from '../types';
import * as StorageService from '../services/storage';
import * as ApiService from '../services/api';
import { BarChart, Bar, XAxis, YAxis, ResponsiveContainer, CartesianGrid, Cell, LabelList } from 'recharts';

interface DashboardProps {
  onEditDay: (id: string) => void;
  refreshTrigger: number;
  onManualSync: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ onEditDay, refreshTrigger, onManualSync }) => {
  const [days, setDays] = useState<WorkDay[]>([]);
  const [currentDriver, setCurrentDriver] = useState<Driver | null>(null);
  const [monthStats, setMonthStats] = useState({ earned: 0, tons: 0, count: 0 });
  const [vacationStats, setVacationStats] = useState({ used: 0, remaining: 0 });
  const [lastSync, setLastSync] = useState<string | null>(null);
  const [syncStatus, setSyncStatus] = useState<'OK' | 'ERROR' | 'SYNCING'>('OK');

  const [historyOffset, setHistoryOffset] = useState(0); 

  useEffect(() => {
    updateLocalView();
  }, [refreshTrigger, historyOffset]);

  const updateLocalView = () => {
    const data = StorageService.getWorkDays();
    const settings = StorageService.getSettings();
    const syncTime = StorageService.getLastSyncTime();

    setDays(data);
    setLastSync(syncTime);
    setSyncStatus(StorageService.getSyncStatus());

    if (settings.driverId) {
        setCurrentDriver(StorageService.getDriverById(settings.driverId) || null);
    }

    const targetDate = new Date();
    targetDate.setMonth(targetDate.getMonth() - historyOffset);

    const targetMonth = targetDate.getMonth();
    const targetYear = targetDate.getFullYear();

    const selectedMonthDays = data.filter(d => {
      const date = new Date(d.date);
      return date.getMonth() === targetMonth && date.getFullYear() === targetYear;
    });

    const earned = selectedMonthDays.reduce((acc, d) => {
      return acc + d.totalAmount + d.totalBonus + (d.totalHourlyBonus || 0) + (d.totalWorkshop || 0) + (d.totalWaiting || 0);
    }, 0);

    const tons = selectedMonthDays.reduce((acc, d) => acc + d.totalWeight, 0);

    const currentYear = new Date().getFullYear();
    const usedVacation = data.filter(d => 
        d.type === DayType.VACATION && 
        new Date(d.date).getFullYear() === currentYear
    ).length;

    setMonthStats({
      earned,
      tons,
      count: selectedMonthDays.filter(d => d.type === DayType.WORK).length
    });

    setVacationStats({
        used: usedVacation,
        remaining: settings.totalVacationDays - usedVacation
    });
  };

  const handleManualSyncInternal = async () => {
      setSyncStatus('SYNCING');
      const settings = StorageService.getSettings();
      if (!settings.driverId) return;

      try {
          const localDays = StorageService.getWorkDays();
          await ApiService.syncDriverData(settings.driverId, localDays);
          onManualSync(); 
          setSyncStatus('OK');
      } catch (e) {
          setSyncStatus('ERROR');
      }
  };

  const handleDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm('Czy usunąć ten dzień?')) {
      StorageService.deleteDay(id);
      updateLocalView();
    }
  };

  const getRestTimeBadge = (currentDay: WorkDay) => {
    if (currentDay.type !== DayType.WORK) return null;
    const otherWorkDays = days
        .filter(d => d.type === DayType.WORK && d.id !== currentDay.id)
        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    const currentDayDate = new Date(currentDay.date);
    const prevDay = otherWorkDays.find(d => new Date(d.date) < currentDayDate);
    if (!prevDay) return null;

    let prevEndDate = new Date(`${prevDay.date}T${prevDay.endTime}`);
    const prevStartDate = new Date(`${prevDay.date}T${prevDay.startTime}`);
    if (prevEndDate <= prevStartDate) prevEndDate.setDate(prevEndDate.getDate() + 1);

    const currentStart = new Date(`${currentDay.date}T${currentDay.startTime}`);
    const diffMs = currentStart.getTime() - prevEndDate.getTime();
    if (diffMs < 0) return null;

    const diffMins = Math.floor(diffMs / 1000 / 60);
    const hours = Math.floor(diffMins / 60);
    const mins = diffMins % 60;

    let colorClass = "bg-green-100 text-green-700";
    if (hours < 9) colorClass = "bg-red-100 text-red-700";
    else if (hours < 11) colorClass = "bg-orange-100 text-orange-700";

    return (
        <span className={`flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-bold ${colorClass}`}>
            <Moon size={10} /> {hours}h {mins}m
        </span>
    );
  };

  const targetDate = new Date();
  targetDate.setMonth(targetDate.getMonth() - historyOffset);
  const year = targetDate.getFullYear();
  const month = targetDate.getMonth();
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  const chartData = Array.from({ length: daysInMonth }, (_, i) => {
      const dayNum = i + 1;
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(dayNum).padStart(2, '0')}`;
      const day = days.find(d => d.date === dateStr);
      const today = new Date();
      const isToday = today.getDate() === dayNum && today.getMonth() === month && today.getFullYear() === year;

      return {
        name: `${String(dayNum).padStart(2, '0')}.${String(month + 1).padStart(2, '0')}`,
        zarobek: day ? Math.round(day.totalAmount + day.totalBonus + (day.totalHourlyBonus || 0) + (day.totalWorkshop || 0) + (day.totalWaiting || 0)) : 0,
        type: day?.type,
        isToday
      };
  });

  const getBarColor = (type?: DayType, isToday?: boolean) => {
      if (isToday) return '#f59e0b';
      if (type === DayType.VACATION) return '#16a34a';
      if (type === DayType.SICK_LEAVE) return '#dc2626';
      if (type === DayType.WORK) return '#2563eb';
      return '#e2e8f0';
  };

  const chartWidth = Math.max(daysInMonth * 55, window.innerWidth - 40);
  const filteredHistory = days.filter(d => {
      const dDate = parseISO(d.date);
      return dDate.getMonth() === month && dDate.getFullYear() === year;
  });

  const displayedMonthName = format(targetDate, 'LLLL yyyy', { locale: pl });
  const isCurrentMonth = historyOffset === 0;
  const todayDateStr = new Date().toISOString().slice(0, 10);
  const todayEntry = days.find(d => d.date === todayDateStr && d.type === DayType.WORK);

  return (
    <div className="p-4 space-y-6 pb-24">

      {/* Header z przyciskiem synchro i Nazwą Kierowcy */}
      <div className="flex items-center justify-between">
         <div className="flex-1">
            <h2 className="text-xl font-bold text-slate-800 capitalize leading-tight">{displayedMonthName}</h2>
            <div className="flex flex-wrap items-center gap-x-3 gap-y-1 mt-1">
                <div className="flex items-center gap-1.5 text-xs font-bold text-slate-600 bg-white px-2 py-0.5 rounded-md border border-slate-100 shadow-sm">
                    <User size={12} className="text-primary"/> {currentDriver?.name || 'Kierowca'}
                </div>
                <div className="flex items-center gap-1.5">
                    {syncStatus === 'OK' && <CloudCheck size={12} className="text-green-500" />}
                    {syncStatus === 'SYNCING' && <RefreshCw size={12} className="text-blue-500 animate-spin" />}
                    {syncStatus === 'ERROR' && <CloudOff size={12} className="text-red-500" />}
                    <p className="text-[10px] text-slate-400 font-medium">
                        {lastSync ? format(parseISO(lastSync), 'HH:mm:ss') : 'Brak połączenia'}
                    </p>
                </div>
            </div>
         </div>
         <div className="flex items-center gap-2">
            <button 
                onClick={handleManualSyncInternal}
                className={`p-2.5 bg-white border border-slate-200 rounded-xl text-primary shadow-sm active:scale-95 transition-all ${syncStatus === 'ERROR' ? 'ring-2 ring-red-100 border-red-200' : ''}`}
                title="Synchronizuj z chmurą"
            >
                <RefreshCw size={20} className={syncStatus === 'SYNCING' ? 'animate-spin' : ''} />
            </button>
            <div className="bg-white p-1 rounded-xl shadow-sm border border-slate-200 flex text-xs font-bold">
                <button
                    onClick={() => setHistoryOffset(0)}
                    className={`px-3 py-1.5 rounded-lg transition ${historyOffset === 0 ? 'bg-blue-100 text-primary' : 'text-slate-400 hover:text-slate-600'}`}
                >
                    Bieżący
                </button>
                <button
                    onClick={() => setHistoryOffset(1)}
                    className={`px-3 py-1.5 rounded-lg transition ${historyOffset === 1 ? 'bg-blue-100 text-primary' : 'text-slate-400'}`}
                >
                    Poprzedni
                </button>
            </div>
         </div>
      </div>

      {/* Statystyki */}
      <div className="grid grid-cols-2 gap-3">
        <div className={`col-span-2 rounded-2xl p-4 text-white shadow-lg transition-colors ${isCurrentMonth ? 'bg-gradient-to-br from-blue-600 to-blue-700 shadow-blue-200' : 'bg-gradient-to-br from-slate-600 to-slate-700 shadow-slate-200'}`}>
          <div className="flex items-center justify-between mb-1">
            <div className={`flex items-center gap-2 text-xs uppercase tracking-wide font-bold ${isCurrentMonth ? 'text-blue-100' : 'text-slate-200'}`}>
                <TrendingUp size={14} /> {isCurrentMonth ? 'Ten miesiąc' : 'Poprzedni miesiąc'}
            </div>
          </div>
          <div className="text-3xl font-bold">{monthStats.earned.toFixed(0)} zł</div>
          <div className={`text-xs mt-1 ${isCurrentMonth ? 'text-blue-200' : 'text-slate-300'}`}>Suma zarobków</div>
        </div>

        <div className="bg-white rounded-2xl p-3 shadow-sm border border-slate-100">
           <div className="flex items-center gap-2 text-slate-400 mb-1 text-[10px] uppercase tracking-wide font-bold">
            <Truck size={12} /> Przewiezione
          </div>
          <div className="text-xl font-bold text-slate-700">{monthStats.tons.toFixed(0)} t</div>
          <div className="text-[10px] text-slate-400 mt-1">{monthStats.count} dni pracy</div>
        </div>

        <div className="bg-white rounded-2xl p-3 shadow-sm border border-slate-100">
           <div className="flex items-center gap-2 text-slate-400 mb-1 text-[10px] uppercase tracking-wide font-bold">
            <Palmtree size={12} /> Urlop (Rok)
          </div>
          <div className={`text-xl font-bold ${vacationStats.remaining < 5 ? 'text-orange-500' : 'text-slate-700'}`}>
             {vacationStats.remaining} dni
          </div>
          <div className="text-[10px] text-slate-400 mt-1">Pozostało w tym roku</div>
        </div>
      </div>

      {/* Wykres */}
      <div className="bg-white p-4 pb-2 rounded-xl shadow-sm border border-slate-100 flex flex-col">
          <h3 className="text-sm font-bold text-slate-500 mb-2 uppercase tracking-wide text-center">
            Zarobki dzienne (zł)
          </h3>
          <div className="overflow-x-auto pb-2 -mx-2 px-2">
            <div style={{ width: `${chartWidth}px`, height: '240px' }}>
                <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={chartData} margin={{ top: 20, right: 10, left: -25, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                    <XAxis dataKey="name" fontSize={11} tickLine={false} axisLine={false} dy={10} interval={0} />
                    <YAxis fontSize={10} axisLine={false} tickLine={false} />
                    <Bar dataKey="zarobek" radius={[6, 6, 0, 0]} barSize={36}>
                        <LabelList dataKey="zarobek" position="top" fontSize={10} fontWeight="bold" fill="#94a3b8" formatter={(v: number) => v > 0 ? v : ''} />
                        {chartData.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={getBarColor(entry.type, entry.isToday)} />
                        ))}
                    </Bar>
                    </BarChart>
                </ResponsiveContainer>
            </div>
          </div>
      </div>

      {/* Przycisk dzisiejszego kursu */}
      {isCurrentMonth && todayEntry && (
        <button
            onClick={() => onEditDay(todayEntry.id)}
            className="w-full py-5 bg-green-600 text-white rounded-2xl shadow-xl shadow-green-200/50 flex flex-col items-center justify-center gap-1 active:scale-95 transition-all transform border border-green-500 relative overflow-hidden group"
        >
            <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity" />
            <div className="flex items-center gap-2">
                <Plus size={32} strokeWidth={3} />
                <span className="text-xl font-black uppercase tracking-wide">Dodaj kolejny kurs</span>
            </div>
            <span className="text-sm font-medium text-green-100">Dzisiaj, {format(parseISO(todayEntry.date), 'd MMMM', { locale: pl })}</span>
        </button>
      )}

      {/* Przycisk nowego dnia */}
      {isCurrentMonth && (
          <button 
            onClick={() => onEditDay('')}
            className="w-full py-4 bg-white text-primary border-2 border-blue-100 rounded-xl shadow-sm flex items-center justify-center gap-3 active:scale-98 transition-transform group font-bold"
          >
            <PlusCircle size={24} />
            DODAJ NOWY DZIEŃ PRACY
          </button>
      )}

      {/* Lista historii */}
      <div>
        <h3 className="text-lg font-bold text-slate-800 mb-3 flex items-center justify-between">
            Historia wpisów
            <span className="text-xs font-medium text-slate-400">{filteredHistory.length} dni</span>
        </h3>
        <div className="space-y-3">
          {filteredHistory.length === 0 ? (
            <div className="text-center p-8 text-slate-400 bg-white rounded-xl border border-dashed border-slate-200">
                Brak wpisów w tym miesiącu.
            </div>
          ) : (
            filteredHistory.map(day => (
              <div 
                key={day.id} 
                onClick={() => onEditDay(day.id)}
                className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 active:scale-[0.98] transition-transform cursor-pointer"
              >
                <div className="flex justify-between items-start">
                  <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-lg ${
                      day.type === DayType.WORK ? 'bg-blue-50 text-primary' : 
                      day.type === DayType.VACATION ? 'bg-yellow-50 text-yellow-600' :
                      day.type === DayType.SICK_LEAVE ? 'bg-purple-50 text-purple-600' : 'bg-slate-100'
                    }`}>
                      {day.type === DayType.WORK && <Briefcase size={18}/>}
                      {day.type === DayType.VACATION && <Calendar size={18}/>}
                      {day.type === DayType.SICK_LEAVE && <Thermometer size={18}/>}
                    </div>
                    <div>
                      <div className="font-bold text-slate-700">
                        {format(parseISO(day.date), 'd MMMM', { locale: pl })}
                      </div>
                      <div className="text-xs text-slate-400 flex items-center gap-2 mt-0.5">
                        {day.type === DayType.WORK ? (
                            <>
                                <span>{day.startTime} - {day.endTime}</span>
                                {getRestTimeBadge(day)}
                            </>
                        ) : day.type}
                      </div>
                    </div>
                  </div>

                  <div className="flex flex-col items-end gap-1">
                    <div className="font-bold text-green-600">
                      +{(day.totalAmount + day.totalBonus + (day.totalHourlyBonus || 0) + (day.totalWorkshop || 0) + (day.totalWaiting || 0)).toFixed(2)} zł
                    </div>
                    <button 
                      onClick={(e) => handleDelete(day.id, e)} 
                      className="p-1.5 text-slate-300 hover:text-red-500 rounded-lg transition-colors"
                    >
                      <Trash2 size={16}/>
                    </button>
                  </div>
                </div>
                {day.type === DayType.WORK && (
                  <div className="mt-2 pt-2 border-t border-slate-50 text-[10px] text-slate-400 flex flex-wrap gap-2">
                    {day.trips.map(t => t.locationName).join(', ')}
                  </div>
                )}
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

