              <X size={18} />
            </button>
          )}
        </div>
      </div>

      {message && (
        <div className="absolute top-20 left-4 right-4 z-50 p-3 bg-blue-600 text-white rounded-lg text-center text-sm font-bold shadow-xl animate-fade-in ring-4 ring-blue-100">
          {message}
