               <Search size={18} />
             </div>
             <input
              ref={inputRef}
              type="text"
              value={searchTerm}
              onFocus={() => setIsSearching(true)}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Szukaj w bazie..."
              className="w-full p-2 pl-10 border border-slate-200 rounded-lg bg-slate-50 focus:bg-white focus:ring-2 focus:ring-blue-500 outline-none transition-all font-medium"
             />
             {isSearching && (
               <button 
                onClick={() => { setIsSearching(false); setSearchTerm(trip.locationName); }} 
                className="absolute right-2 top-2 p-1 text-slate-400"
               >
                 <X size={18}/>
               </button>
             )}
          </div>

          {isSearching && (
            <div className="absolute z-50 left-0 right-0 top-full mt-1 bg-white border border-slate-200 rounded-lg shadow-2xl max-h-60 overflow-y-auto">
              {filteredLocations.length === 0 ? (
                 <div className="p-4 text-sm text-slate-400 text-center font-medium italic">Nie znaleziono miejscowości</div>
