                  >
                    <span className="font-bold text-slate-700">{loc.name}</span>
                    <span className="text-xs font-mono font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded">{loc.rate} zł/t</span>
                  </button>
                ))
              )}
            </div>
          )}
        </div>

        <div className="col-span-4">
          <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">
             {isFixedRate ? 'Ryczałt' : 'Tony'}
          </label>
          <input 
            type="number" 
            step="0.1"
            value={trip.weight || ''}
            onChange={(e) => onChange('weight', parseFloat(e.target.value) || 0)}
            disabled={isFixedRate}
