export const saveWorkDays = (days: WorkDay[], sync = true) => {
  localStorage.setItem(STORAGE_KEYS.DAYS, JSON.stringify(days));

  const settings = getSettings();
  if (sync && !isInitialSyncing && settings.driverId) {
