const STORAGE_KEYS = {
  DAYS: 'kierowcapro_days',
  LOCATIONS: 'kierowcapro_locations',
  DRIVERS: 'kierowcapro_drivers',
  SETTINGS: 'kierowcapro_settings',
};

const INITIAL_LOCATIONS: LocationRate[] = [
  { id: '1', name: 'Siemianowice DOMBUD', rate: 2.85 },
  { id: 'extra3', name: 'MATERIAŁ FREZY', rate: 9 },
];

const DEFAULT_SETTINGS: AppSettings = {
  vacationRateOld: 210,
  vacationRateNew: 230,
  sickLeaveRate: 150,
  hourlyRate: 4.5,
  extraHourlyRate: 15, // Domyślna stawka za pracę na godziny
  workshopRate: 10,
  waitingRate: 8,
  totalVacationDays: 30,
  vacationDaysLimit: 26
};

export const getSettings = (): AppSettings => {
  const data = localStorage.getItem(STORAGE_KEYS.SETTINGS);
  return data ? JSON.parse(data) : DEFAULT_SETTINGS;
};

export const saveSettings = (settings: AppSettings) => {
  localStorage.setItem(STORAGE_KEYS.SETTINGS, JSON.stringify(settings));
};

export const getLocations = (): LocationRate[] => {
  const data = localStorage.getItem(STORAGE_KEYS.LOCATIONS);
  return data ? JSON.parse(data) : INITIAL_LOCATIONS;
};

export const saveLocations = (locations: LocationRate[], sync = true) => {
  localStorage.setItem(STORAGE_KEYS.LOCATIONS, JSON.stringify(locations));
  if (sync) {
      ApiService.syncLocations(locations);
  }
};

export const getDrivers = (): Driver[] => {
  const data = localStorage.getItem(STORAGE_KEYS.DRIVERS);
  return data ? JSON.parse(data) : [];
};

export const saveDrivers = (drivers: Driver[], sync = true) => {
  localStorage.setItem(STORAGE_KEYS.DRIVERS, JSON.stringify(drivers));
  if (sync) {
    ApiService.syncDrivers(drivers);
  }
};

export const getWorkDays = (): WorkDay[] => {
  const data = localStorage.getItem(STORAGE_KEYS.DAYS);
  return data ? JSON.parse(data) : [];
};

export const saveWorkDays = (days: WorkDay[]) => {
  localStorage.setItem(STORAGE_KEYS.DAYS, JSON.stringify(days));
  const settings = getSettings();
  if (settings.driverId) {
    ApiService.syncDriverData(settings.driverId, days);
  }
};

export const getDayById = (id: string): WorkDay | undefined => {
  const days = getWorkDays();
  return days.find((d) => d.id === id);
};

const recalculateVacations = (allDays: WorkDay[]): WorkDay[] => {
    const settings = getSettings();
    const oldVacationPool = Math.max(0, settings.totalVacationDays - settings.vacationDaysLimit);
    const years = Array.from(new Set(allDays.map(d => new Date(d.date).getFullYear())));
    let updatedDays = [...allDays];

    years.forEach(year => {
        const vacationDays = updatedDays
            .filter(d => d.type === DayType.VACATION && new Date(d.date).getFullYear() === year)
            .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

        vacationDays.forEach((day, index) => {
            const isOldRate = index < oldVacationPool;
            day.totalAmount = isOldRate ? settings.vacationRateOld : settings.vacationRateNew;
        });

        updatedDays = updatedDays.map(d => {
            const updatedVacation = vacationDays.find(vd => vd.id === d.id);
            return updatedVacation || d;
        });
    });

    return updatedDays;
};

export const saveDay = (day: WorkDay) => {
  let days = getWorkDays();
  const index = days.findIndex((d) => d.id === day.id);
  const calculatedDay = calculateDayTotals(day);

  if (index >= 0) {
    days[index] = calculatedDay;
  } else {
    days.push(calculatedDay);
  }

  if (calculatedDay.type === DayType.VACATION || days.some(d => d.type === DayType.VACATION)) {
      days = recalculateVacations(days);
  }

  days.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  saveWorkDays(days);
};

export const deleteDay = (id: string) => {
  let days = getWorkDays().filter((d) => d.id !== id);
  days = recalculateVacations(days);
  saveWorkDays(days);
};

export const updateRecentHistoryRates = (): number => {
    const days = getWorkDays();
    const locations = getLocations();
    const now = new Date();
    const cutoffDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    cutoffDate.setHours(0, 0, 0, 0);

    let modifiedDaysCount = 0;

    const updatedDays = days.map(day => {
        const dayDate = new Date(day.date);
        dayDate.setHours(0,0,0,0);
        if (dayDate < cutoffDate) return day;
        if (day.type !== DayType.WORK) return day;

        let dayModified = false;
        const newTrips = day.trips.map(trip => {
            const loc = locations.find(l => l.id === trip.locationId);
            if (loc && (loc.rate !== trip.rate || loc.name !== trip.locationName)) {
                dayModified = true;
                const { amount, bonus } = calculateTrip(trip.weight, loc.rate);
                return { ...trip, rate: loc.rate, locationName: loc.name, amount, bonus };
            }
            return trip;
        });

        if (dayModified) {
            modifiedDaysCount++;
            return calculateDayTotals({ ...day, trips: newTrips });
        }
        return day;
    });

    if (modifiedDaysCount > 0) {
        saveWorkDays(updatedDays);
    }
    return modifiedDaysCount;
};

export const calculateTrip = (weight: number, rate: number): { amount: number; bonus: number } => {
  const amount = weight * rate;
  const bonus = amount * 0.20;
  return { amount, bonus };
};

const calculateDurationHours = (start: string, end: string): number => {
  if (!start || !end) return 0;
  const [startH, startM] = start.split(':').map(Number);
  const [endH, endM] = end.split(':').map(Number);
  let diff = (endH * 60 + endM) - (startH * 60 + startM);
  if (diff < 0) diff += 24 * 60;
  return diff / 60;
};

export const calculateDayTotals = (day: WorkDay): WorkDay => {
  const settings = getSettings();
  const zeros = {
    totalBonus: 0,
    totalHourlyBonus: 0,
    totalWeight: 0,
    workshopHours: 0,
    totalWorkshop: 0,
    waitingHours: 0,
    totalWaiting: 0,
    extraHourlyHours: 0,
    totalExtraHourly: 0,
    trips: []
  };

  if (day.type === DayType.VACATION) {
    return { ...day, totalAmount: day.totalAmount || settings.vacationRateNew, ...zeros };
  }
  if (day.type === DayType.SICK_LEAVE) {
    return { ...day, totalAmount: settings.sickLeaveRate, ...zeros };
  }

  let totalAmount = 0;
  let totalBonus = 0;
  let totalWeight = 0;
  let totalHourlyBonus = 0;

  if (day.startTime && day.endTime && day.endTime !== '04:00') {
     const hours = calculateDurationHours(day.startTime, day.endTime);
     totalHourlyBonus = hours * settings.hourlyRate;
  }

  const workshopHours = day.workshopHours || 0;
  const totalWorkshop = workshopHours * settings.workshopRate;
  const waitingHours = day.waitingHours || 0;
  const totalWaiting = waitingHours * settings.waitingRate;

  // NOWE: Praca na godziny (ręczna)
  const extraHourlyHours = day.extraHourlyHours || 0;
  const totalExtraHourly = extraHourlyHours * settings.extraHourlyRate;

  const recalculatedTrips = day.trips.map(trip => {
    const { amount, bonus } = calculateTrip(trip.weight, trip.rate);
    totalAmount += amount;
    totalBonus += bonus;
    totalWeight += trip.weight;
    return { ...trip, amount, bonus };
  });

  return {
    ...day,
    trips: recalculatedTrips,
    totalAmount,
    totalBonus,
    totalHourlyBonus,
    totalWorkshop,
    totalWaiting,
    totalExtraHourly,
    totalWeight
  };
};

export const exportData = () => {
  const data = {
    settings: getSettings(),
    locations: getLocations(),
    days: getWorkDays(),
    exportDate: new Date().toISOString(),
  };
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `kierowcapro_backup_${new Date().toISOString().slice(0, 10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
};

export const importData = async (file: File): Promise<boolean> => {
  try {
    const text = await file.text();
    const data = JSON.parse(text);
    if (data.settings) saveSettings(data.settings);
    if (data.locations && Array.isArray(data.locations)) saveLocations(data.locations, true);
    if (data.days && Array.isArray(data.days)) saveWorkDays(data.days);
    return true;
  } catch (e) {
    console.error("Import failed", e);
    return false;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { Plus, Trash2, Save, ArrowLeft, Clock, Search, X, Wrench, Hourglass, Thermometer, Moon, Briefcase } from 'lucide-react';
import { WorkDay, DayType, LocationRate, Trip, AppSettings } from '../types';
import * as StorageService from '../services/storage';

interface DayEditorProps {
  dayId?: string | null;
  onClose: () => void;
}

const DayEditor: React.FC<DayEditorProps> = ({ dayId, onClose }) => {
  const [locations, setLocations] = useState<LocationRate[]>([]);
  const [settings, setSettings] = useState<AppSettings>(StorageService.getSettings());

  // Local UI states to keep inputs visible even if value is 0 during typing
  const [showWorkshop, setShowWorkshop] = useState(false);
  const [showWaiting, setShowWaiting] = useState(false);
  const [showExtraHourly, setShowExtraHourly] = useState(false);

  // State for Daily Rest Calculation
  const [restInfo, setRestInfo] = useState<{ label: string; colorClass: string } | null>(null);

  const [day, setDay] = useState<WorkDay>({
    id: uuidv4(),
    date: new Date().toISOString().slice(0, 10),
    type: DayType.WORK,
    startTime: '04:00',
    endTime: '04:00',
    trips: [],
    workshopHours: 0,
    totalWorkshop: 0,
    waitingHours: 0,
    waitingNote: '',
    totalWaiting: 0,
    extraHourlyHours: 0,
    totalExtraHourly: 0,
    totalAmount: 0,
    totalBonus: 0,
    totalHourlyBonus: 0,
    totalWeight: 0,
    note: ''
  });

  useEffect(() => {
    setLocations(StorageService.getLocations());
    setSettings(StorageService.getSettings());
    if (dayId) {
      const existingDay = StorageService.getDayById(dayId);
      if (existingDay) {
        setDay(existingDay);
        // Initialize toggles based on existing data
        setShowWorkshop((existingDay.workshopHours || 0) > 0);
        setShowWaiting((existingDay.waitingHours || 0) > 0);
        setShowExtraHourly((existingDay.extraHourlyHours || 0) > 0);
      }
    } else {
        // Reset toggles for new day
        setShowWorkshop(false);
        setShowWaiting(false);
        setShowExtraHourly(false);
    }
  }, [dayId]);

  // Effect to calculate rest time whenever relevant fields change
  useEffect(() => {
    calculateDailyRest();
  }, [day.date, day.startTime, day.type]);

  const calculateDailyRest = () => {
    if (day.type !== DayType.WORK) {
        setRestInfo(null);
        return;
    }

    const allDays = StorageService.getWorkDays();
    // Filter out current day (in case we are editing an existing one) to find the previous one correctly
    const otherDays = allDays.filter(d => d.id !== day.id && d.type === DayType.WORK);

    // Sort descending by date
    const sorted = otherDays.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    const currentDayDate = new Date(day.date);

    // Find the most recent work day strictly BEFORE the current date
    const prevDay = sorted.find(d => new Date(d.date) < currentDayDate);

    if (!prevDay) {
        setRestInfo(null);
        return;
    }

    // Calculate Previous Shift END Timestamp
    let prevEndDate = new Date(`${prevDay.date}T${prevDay.endTime}`);
    const prevStartDate = new Date(`${prevDay.date}T${prevDay.startTime}`);

    // Handle overnight shift
    if (prevEndDate <= prevStartDate) {
        prevEndDate.setDate(prevEndDate.getDate() + 1);
    }

    // Calculate Current Shift START Timestamp
    const currentStart = new Date(`${day.date}T${day.startTime}`);

    // Difference in milliseconds
    const diffMs = currentStart.getTime() - prevEndDate.getTime();

    // If negative, it means overlap or data error
    if (diffMs < 0) {
        setRestInfo({
            label: "Błąd (nakładanie się zmian)",
            colorClass: "bg-red-50 text-red-600 border-red-200"
        });
        return;
    }

    const diffMins = Math.floor(diffMs / 1000 / 60);
    const hours = Math.floor(diffMins / 60);
    const mins = diffMins % 60;

    let colorClass = "bg-green-50 text-green-700 border-green-200"; // Safe

    if (hours < 9) {
        colorClass = "bg-red-50 text-red-600 border-red-200";
    } else if (hours < 11) {
        colorClass = "bg-orange-50 text-orange-700 border-orange-200";
    }

    setRestInfo({
        label: `${hours}h ${mins}m`,
        colorClass
    });
  };

  const handleTripChange = (tripId: string, field: keyof Trip, value: any) => {
    const updatedTrips = day.trips.map(trip => {
      if (trip.id !== tripId) return trip;
      const newTrip = { ...trip, [field]: value };
      if (field === 'locationId') {
        const loc = locations.find(l => l.id === value);
        if (loc) {
          newTrip.locationName = loc.name;
          newTrip.rate = loc.rate;
          if (loc.rate > 10) {
            newTrip.weight = 1;
          }
        }
      }
      const { amount, bonus } = StorageService.calculateTrip(newTrip.weight, newTrip.rate);
      newTrip.amount = amount;
      newTrip.bonus = bonus;
      return newTrip;
    });
    setDay({ ...day, trips: updatedTrips });
  };

  const addTrip = () => {
    setDay({
      ...day,
      trips: [
        ...day.trips,
        {
          id: uuidv4(),
          locationId: '',
          locationName: '',
          weight: 0,
          rate: 0,
          amount: 0,
          bonus: 0
        }
      ]
    });
  };

  const removeTrip = (id: string) => {
    setDay({ ...day, trips: day.trips.filter(t => t.id !== id) });
  };

  const handleSave = () => {
    const dayToSave = { ...day };
    if (!showWorkshop) {
        dayToSave.workshopHours = 0;
        dayToSave.totalWorkshop = 0;
    }
    if (!showWaiting) {
        dayToSave.waitingHours = 0;
        dayToSave.totalWaiting = 0;
        dayToSave.waitingNote = '';
    }
    if (!showExtraHourly) {
        dayToSave.extraHourlyHours = 0;
        dayToSave.totalExtraHourly = 0;
    }

    StorageService.saveDay(dayToSave);
    onClose();
  };

  const toggleWorkshop = () => {
    const newState = !showWorkshop;
    setShowWorkshop(newState);
    if (newState) {
      setDay({ ...day, workshopHours: 1 });
    } else {
      setDay({ ...day, workshopHours: 0 });
    }
  };

  const toggleWaiting = () => {
    const newState = !showWaiting;
    setShowWaiting(newState);
    if (newState) {
      setDay({ ...day, waitingHours: 1 });
    } else {
      setDay({ ...day, waitingHours: 0, waitingNote: '' });
    }
  };

  const toggleExtraHourly = () => {
    const newState = !showExtraHourly;
    setShowExtraHourly(newState);
    if (newState) {
      setDay({ ...day, extraHourlyHours: 1 });
    } else {
      setDay({ ...day, extraHourlyHours: 0 });
    }
  };

  const totals = StorageService.calculateDayTotals(day);

  return (
    <div className="flex flex-col h-full bg-slate-50">
      <div className="bg-white border-b border-slate-200 p-4 flex items-center justify-between sticky top-0 z-20 shadow-sm flex-none">
        <button onClick={onClose} className="p-2 text-slate-600 hover:bg-slate-100 rounded-full">
          <ArrowLeft size={24} />
        </button>
        <h2 className="text-lg font-bold text-slate-800">
          {dayId ? 'Edycja Dnia' : 'Nowy Dzień'}
        </h2>
        <button 
          onClick={handleSave} 
          className="flex items-center gap-2 bg-green-600 text-white px-4 py-2 rounded-lg font-medium shadow hover:bg-green-700 transition"
        >
          <Save size={18} />
          <span>Zapisz</span>
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6">

        <section className="bg-white p-4 rounded-xl shadow-sm space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium text-slate-500 mb-1">Data</label>
              <input 
                type="date" 
                value={day.date} 
                onChange={e => setDay({...day, date: e.target.value})}
                className="w-full p-3 border border-slate-300 rounded-lg bg-gray-50 text-lg"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-500 mb-1">Typ dnia</label>
              <select 
                value={day.type} 
                onChange={e => setDay({...day, type: e.target.value as DayType})}
                className="w-full p-3 border border-slate-300 rounded-lg bg-gray-50 font-medium text-slate-700"
              >
                <option value={DayType.WORK}>Praca (Kursy)</option>
                <option value={DayType.VACATION}>Urlop</option>
                <option value={DayType.SICK_LEAVE}>L4 ({settings.sickLeaveRate} zł)</option>
              </select>
