export const syncDriverData = async (driverId: string, days: WorkDay[], settings?: AppSettings) => {
    if (!isFirebaseConfigured() || !driverId) return;
    try {
        const driverRef = doc(db, "driverData", driverId);
        const dataToSync: any = { 
            days: JSON.stringify(days),
            lastSync: new Date().toISOString(),
            driverId: driverId
        };

        // Jeśli przekazano ustawienia, dodaj je do synchronizacji
        if (settings) {
            dataToSync.settings = JSON.stringify(settings);
        }

        await setDoc(driverRef, dataToSync, { merge: true });
    } catch (e) {
        console.error("Błąd zapisu danych kierowcy w Firebase:", e);
    }
};

export const fetchDriverFullProfile = async (driverId: string): Promise<{days: WorkDay[], settings?: AppSettings}> => {
    if (!isFirebaseConfigured() || !driverId) return { days: [] };
    try {
        const driverRef = doc(db, "driverData", driverId);
        const docSnap = await getDoc(driverRef);
        if (docSnap.exists()) {
            const data = docSnap.data();
            return {
                days: JSON.parse(data.days || '[]'),
                settings: data.settings ? JSON.parse(data.settings) : undefined
            };
        }
    } catch (e) {
        console.error("Błąd pobierania danych kierowcy z Firebase:", e);
    }
    return { days: [] };
};

