  const [editingDayId, setEditingDayId] = useState<string | null>(null);
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [showAdmin, setShowAdmin] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    const settings = StorageService.getSettings();
    if (settings.driverId) {
      setIsLoggedIn(true);
      initializeData(settings.driverId);
    }
  }, []);

  const initializeData = async (driverId: string) => {
    setIsLoading(true);
    try {
        // Pobierz lokalizacje z chmury (globalne)
        const locations = await ApiService.fetchLocations();
        if (locations && locations.length > 0) {
            StorageService.saveLocations(locations, false);
        }

        // Pobierz PEŁNY profil kierowcy (dni + ustawienia)
        const profile = await ApiService.fetchDriverFullProfile(driverId);

        // 1. Zastosuj pobrane ustawienia (stawki), jeśli istnieją w chmurze
        if (profile.settings) {
            // Zachowaj driverId, ale nadpisz resztę stawek z chmury
            const mergedSettings = { ...profile.settings, driverId };
            StorageService.saveSettings(mergedSettings, false); // false = nie wysyłaj z powrotem od razu
        }

        // 2. Zastosuj dni pracy
        if (profile.days && profile.days.length > 0) {
            StorageService.saveWorkDays(profile.days);
            setRefreshTrigger(prev => prev + 1);
        }
    } catch (e) {
